window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-cirurgia-med-cir-05"]={"block":"med:med-cirurgia-med-cir-05","label":"MED · MED CIR 05","count":350,"questions":[{"id":"med-cirurgia-med-cir-05-182606","number":"182606","sourceNumber":"182606","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente masculino, 56 anos, refere dor periumbilical com evolução de 24 horas,\nassociado à parada de eliminação de flatos e\nfezes. Revisão de sistemas: aparelho gastrointestinal\n\n- Constipação intestinal crônica. Exame físico: mucosas úmidas. AC: RCR 2T, FC: 110 bpm, PA:\n100X80 mmHg. RX de abdome com imagem em \"grão de café\". Qual a hipótese diagnóstica?","options":{"A":"Intussuscepção intestinal.","B":"Volvo de sigmoide.","C":"Obstrução por fitobezoar.","D":"Obstrução por tumor."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-108695","number":"108695","sourceNumber":"108695","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente feminina, 84 anos, deu entrada na UPA com queixas de dor abnominal difusa,\ntipo cólicas e vômitos com evolução de 48h.\nHá 24h com parada de eliminação de fezes e flatos.\n\nSolicitaram, RX de abdome em pé e deitado, que demostrou distensão difusa de delgado e de todo\ncólon. Com base apenas nesses dados, como diferenciar uma obstrução mecânica de um íleo\nmetabólico?","options":{"A":"Verificar se há macicez móvel;","B":"Realizar toque retal;","C":"Avaliar se o Sinal de Joubert é positivo;","D":"Realizar tonometria do suco gástrico."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-84490","number":"84490","sourceNumber":"84490","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"O segmento do cólon mais sujeito torções, originado quadro de volvo é o:","options":{"A":"Ceco.","B":"Cólon transverso.","C":"Ângulo esplênico.","D":"Sigmoide.","E":"Reto alto."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-50054","number":"50054","sourceNumber":"50054","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Qual o exame mais indicado para pesquisas de malformações do trato gastrointestinal?","options":{"A":"Ultrassonografia abdominal.","B":"Radiografia simples do abdome.","C":"Tomografia computadorizada.","D":"Ressonância nuclear magnética."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-29365","number":"29365","sourceNumber":"29365","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Nas hérnias inguinais, à direita, por deslizamento, que víscera mais frequentemente\ncompõe a parede do saco herniário?","options":{"A":"cólon sigmoide","B":"ceco","C":"epíplon","D":"ligamento redondo","E":"bexiga"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-372093","number":"372093","sourceNumber":"372093","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente masculino, 57 anos, procura atendimento médico queixando-se de dor e\ndistensão abdominal há 1 dia. Queixa-se de dor\nabdominal difusa, tipo cólica, iniciada há 1 dia,\nprogressiva, sem melhora com analgésicos e antiespasmódicos, associada a vários episódios de\nvômitos. Nega trauma. Nega episódios prévios. Nega cirurgias abdominais. Nega perda de peso ou\nsangramento nas fezes. É portador de cardiomiopatia dilatada, hipertenso e diabético.\n\nEletrocardiograma evidencia taquicardia sinusal, com bloqueio divisional ântero-superior. Ao exame\nfísico, encontra-se em regular estado geral, desidratado, taquipneico, anictérico, acianótico,\nafebril.\nEstável hemodinamicamente. Abdome com ruídos presentes e aumentados, distendido, doloroso à\npalpação superficial e profunda, sem sinais de irritação peritoneal. Foi submetido aos exames\nradiológicos abaixo. Assinale a principal hipótese diagnóstica.","options":{"A":"Isquemia mesentérica.","B":"Úlcera duodenal perfurada e bloqueada.","C":"Neoplasia de cólon esquerdo.","D":"Volvo de sigmoide."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-372094","number":"372094","sourceNumber":"372094","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente masculino, 57 anos, procura atendimento médico queixando-se de dor e\ndistensão abdominal há 1 dia. Queixa-se de dor\nabdominal difusa, tipo cólica, iniciada há 1 dia,\nprogressiva, sem melhora com analgésicos e antiespasmódicos, associada a vários episódios de\nvômitos. Nega trauma. Nega episódios prévios. Nega cirurgias abdominais. Nega perda de peso ou\nsangramento nas fezes. É portador de cardiomiopatia dilatada, hipertenso e diabético.\n\nEletrocardiograma evidencia taquicardia sinusal, com bloqueio divisional ântero-superior. Ao exame\nfísico, encontra-se em regular estado geral, desidratado, taquipneico, anictérico, acianótico,\nafebril.\nEstável hemodinamicamente. Abdome com ruídos presentes e aumentados, distendido, doloroso à\npalpação superficial e profunda, sem sinais de irritação peritoneal. Foi submetido aos exames\nradiológicos abaixo. Assinale a conduta imediata mais adequada para este caso.","options":{"A":"Colostomia de urgência.","B":"Retossigmoidoscopia descompressiva.","C":"Procedimento de Hartmann.","D":"Anticoagulação plena."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-315170","number":"315170","sourceNumber":"315170","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"O tratamento inicial a ser instituído em paciente com Volvo de sigmóide é:","options":{"A":"Colonoscopia.","B":"Cirurgia de Hartmann.","C":"Sigmoidostomia.","D":"Transversostomia.","E":"Colectomia total."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-315171","number":"315171","sourceNumber":"315171","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A hérnia que produz protuberância abaixo do ligamento inguinal é chamada de:","options":{"A":"Inguinal direta.","B":"Inguinal indireta.","C":"Mista.","D":"De Spiegel.","E":"Crural."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-307046","number":"307046","sourceNumber":"307046","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente, sexo masculino, 60 anos de idade, refere dor em região testicular há vários\nmeses. A dor piora ao fazer esforço físico, como agachar. Refere que melhora ao deitar. Sua\nesposa percebeu que o lado onde sente dor (direito) está com um volume maior que o esquerdo.\nProcurou um médico para avaliação que, ao fazer o exame físico completo com o paciente deitado\ne em pé, notou abaulamento em região inguino-escrotal ao solicitar que tossisse. Indique a\nestrutura importante para a fixação da tela de polipropileno, quando utilizada a técnica de\nLichtenstein.","options":{"A":"Tendão conjunto.","B":"Ligamento lacunar.","C":"Ligamento de Cooper.","D":"Anel inguinal interno."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-307047","number":"307047","sourceNumber":"307047","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente, sexo masculino, 60 anos de idade, refere dor em região testicular há vários\nmeses. A dor piora ao fazer esforço físico, como agachar. Refere que melhora ao deitar. Sua\nesposa percebeu que o lado onde sente dor (direito) está com um volume maior que o esquerdo.\nProcurou um médico para avaliação que, ao fazer o exame físico completo com o paciente deitado\ne em pé, notou abaulamento em região inguino-escrotal ao solicitar que tossisse. Indique a técnica\nutilizada para a correção da hérnia femoral do paciente.","options":{"A":"Bassini.","B":"Shouldice.","C":"McVay.","D":"Mayo."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-314211","number":"314211","sourceNumber":"314211","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"O terço distal do cólon transverso, o cólon descendente e o reto evoluem da cissura do\nintestino posterior e são supridos pela:","options":{"A":"Artéria mesentérica superior.","B":"Tronco celíaco.","C":"Artéria mesentérica inferior.","D":"Artéria cólica direita."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-314212","number":"314212","sourceNumber":"314212","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Embora tenha elasticidade, uma dilatação aguda do ceco que pode ser medida por uma\nradiografia abdominal simples pode resultar em necrose isquêmica e perfuração da parede\nintestinal. Neste contexto, o valor de corte, em centímetros, para este tipo de lesão é:","options":{"A":"6 cm","B":"8 cm","C":"10 cm","D":"12 cm"},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-314213","number":"314213","sourceNumber":"314213","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Representa a fusão do mesentério com o peritônio posterior. Este ponto de referência\nperitoneal sutil serve ao cirurgião como um guia para a mobilização do cólon e do mesentério do\nretroperitônio. É um marco anatômico importante na dissecção do cólon.","options":{"A":"A linha branca de Toldt.","B":"Ponto de Sudeck.","C":"Ponto de Griffith.","D":"Ponto de Cattel."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-314214","number":"314214","sourceNumber":"314214","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A fáscia endopélvica é uma camada espessa do peritônio parietal que reveste as\nparedes e o assoalho da pelve. Seu\nconhecimento anatômico é importante pois sua secção durante\na dissecção por ocasião de uma abordagem abdominal proporciona o acesso para a pelve\n\nretro-retal. A dissecção entre as fáscias acompanha os princípios da oncologia cirúrgica e minimiza\nos riscos de lesões vasculares e neurais. A\nfigura abaixo traz a representação da fáscia\nendopélvica. Assinale a alternativa com a correta associação.","options":{"A":"A: Fáscia pré-sacral, B: Fáscia retossacral, C: Fáscia de Denonvilliers.","B":"A: Fáscia de Denonvilliers, B: Fáscia retossacral, C: Fáscia pré-sacral.","C":"A: Fáscia de Denonvilliers, B: Fáscia pré-sacral, C: Fáscia retossacral.","D":"A: Fáscia pré-sacral, B: Fáscia de Denonvilliers, C: Fáscia retossacral."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-314215","number":"314215","sourceNumber":"314215","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"O assoalho ou diafragma pélvico é constituído um grupo muscular que, em conjunto,\nformam o elevador do ânus. São eles:","options":{"A":"Músculos pubococcígeos, ileococcígeos e puborretais.","B":"Músculos pubococcígeos, piriformes e puborretais.","C":"Músculos pubococcígeos, puborretais e psoas maior.","D":"Músculos pubococcígeos, obturadores internos e puborretais."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-314218","number":"314218","sourceNumber":"314218","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"É uma condição na qual o intestino sofre uma torção sobre o seu eixo mesentérico,\numa situação que resulta em obstrução parcial ou\ncompleta do lúmen intestinal e de um grau\nvariável do seu suprimento sanguíneo. A condição geralmente afeta o cólon.","options":{"A":"Hérnia interna.","B":"Volvo.","C":"Intussuscepção.","D":"Estenose colônica."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-314219","number":"314219","sourceNumber":"314219","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"O achado tomográfico de uma dobra mesentérica típica, representado na imagem\nabaixo, pode ser encontrada mais frequentemente em qual patologia abaixo?","options":{"A":"Apendicite aguda.","B":"Pancreatite aguda.","C":"Adenite mesentérica.","D":"Volvo de sigmoide."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-279057","number":"279057","sourceNumber":"279057","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"O ceco é um segmento dilatado em forma de saco do cólon proximal. Embora tenha\nelasticidade, uma dilatação aguda do ceco pode resultar em necrose isquêmica e perfuração da\nparede intestinal. O diâmetro limítrofe notado em radiografia simples de abdome para\ndesenvolvimento de tais repercussões é:","options":{"A":"Diâmetro maior de 6 cm.","B":"Diâmetro maior de 10 cm.","C":"Diâmetro maior de 12 cm.","D":"Diâmentro maior de 20 cm."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-279058","number":"279058","sourceNumber":"279058","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A artéria retal inferior é um ramo da artéria pudenda que é, ela mesma, um ramo mais\ndistal da:","options":{"A":"Artéria ilíaca interna.","B":"Artéria ilíaca externa.","C":"Artéria mesentérica superior.","D":"Artéria mesentérica inferior."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-279060","number":"279060","sourceNumber":"279060","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"É responsável pela irrigação do intestino posterior:","options":{"A":"Tronco celíaco.","B":"Artéria mesentérica anterior.","C":"Artéria mesentérica superior.","D":"Artéria mesentérica inferior."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-279061","number":"279061","sourceNumber":"279061","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"É um ramo proximal da artéria mesentérica superior. Ela geralmente se divide em\nramos direito e esquerdo, que irrigam o cólon transverso proximal e distal, respectivamente.\nTrata-se da:","options":{"A":"Artéria mesentérica anterior.","B":"Artéria ileocecocólica.","C":"Artéria cólica direita.","D":"Artéria cólica média."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-279062","number":"279062","sourceNumber":"279062","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Conecta diretamente as porções proximais às porções da artéria mesentética superior\ncom a artéria mesentética inferior e pode\nservir como um canal vital quando uma ou outra destas\nartérias está ocluída. Ela também é conhecida como artéria mesentérica sinuosa e tem um\ntamanho bastante variável. Trata-se da:","options":{"A":"Arcada de Riolan.","B":"Arcada Sudeck.","C":"Arcada de Ghriffts.","D":"Arcada celíaca."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-279065","number":"279065","sourceNumber":"279065","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Irriga todo o intestino delgado, dando 12 a 20 ramos jejunais e ileais para a esquerda e\naté três ramos colônicos principais à direita. Trata-se da:","options":{"A":"Artéria celíaca.","B":"Artéria mesentérica anterior.","C":"Artéria mesentérica superior.","D":"Artéria mesentérica inferior."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-278648","number":"278648","sourceNumber":"278648","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"As imagens abaixo foram realizadas na investigação de uma paciente feminina, 24\nanos de idade, com queixas de dor e\ndistensão abdominal pós-prandial e eructações frequentes há\naproximadamente 2 meses. Relata perda ponderal importante neste mesmo período. As imagens\nevidenciam compressão da terceira porção duodenal entre a artéria mesentérica superior e a aorta,\ncom consequente dilatação a montante. Trata-se da:","options":{"A":"Síndrome de Wilkie.","B":"Síndrome de Foley.","C":"Síndrome de Prader Willi.","D":"Síndrome de Cocket."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-279068","number":"279068","sourceNumber":"279068","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A fáscia retossacra é uma condensação espessada da fáscia endopélvica conectando a\nfáscia pré-sacra à fáscia própria no nível de S4 e estendendo-se até o anel anorretal. É um ponto\nde referência cirúrgico importante, e a sua secção durante a dissecção por ocasião de uma\nabordagem abdominal proporciona o acesso para a pelve retro-retal. Tal fáscia é conhecida como:","options":{"A":"Fáscia dos Denonvilliers.","B":"Fáscia de Waldeyer.","C":"Fáscia de Blumberg.","D":"Fáscia de Houston."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-279070","number":"279070","sourceNumber":"279070","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Origina-se da aorta no nível de L2 a L3, aproximadamente 3 cm acima da bifurcação\naórtica. A artéria cólica esquerda é seu\nramo mais proximal, irrigando a porção distal do cólon\ntransverso, a flexura esplênica e o cólon descendente. Trata-se da:","options":{"A":"Artéria mesentérica inferior.","B":"Artéria mesentérica superior.","C":"Artéria mesentérica médica.","D":"Artéria celíaca."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-249413","number":"249413","sourceNumber":"249413","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 53 anos, admitido em pronto-socorro por vômitos há 3 dias, associado à\ndor abdominal importante, em cólicas, que vem\nse tornando progressiva. Nega febre. Queixa-se de\nhiporexia. Nega sintomas urinários. Ao exame físico, apresenta-se regular estado geral,\ndesidratado, discretamente taquicárdico, com exame físico cardiopulmonar normal. Ruídos\nreduzidos em todo o abdome, doloroso difusamente, distendido, sem sinais de irritação peritoneal.\nFoi submetido à radiografia abaixo, com achado pouco comum destacado pela seta. Hemograma\ncom discreta leucocitose, função renal normal. Análise de exame de urina normal. A principal\nhipótese diagnóstica é:","options":{"A":"Volvo de sigmóide.","B":"Úlcera perfurada.","C":"Íleo Biliar.","D":"Ureterolitíase."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-212162","number":"212162","sourceNumber":"212162","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"O estudo da anatomia e semiologia é de grande importância para as correlações\nmédico-cirúrgicas. Dessa forma, o diagnóstico de\ndiversas patologias cirúrgicas pode ser possível a\npartir do exame clínico e físico. Além disso, o entendimento da anatomia servirá de base para\nrealização adequada do procedimento cirúrgico. Em relação à correlação entre anatomia e/ou\nsemiologia e algumas patologias cirúrgicas, assinale a alternativa correta.","options":{"A":"Um paciente jovem que apresente abaulamento na região inguinal e exteriorização do conteúdo\nherniário pelo anel inguinal externo possui o diagnóstico de hérnia inguinal direta e o tratamento\nindicado deverá ser realizado pela técnica de Bassini.","B":"Durante a colecistectomia videolaparoscópica para o tratamento de colelitíase sintomática,\npode-se identificar o triângulo cistohepático (ou\ntriângulo de Calot) que é delimitado pelo ducto\nhepático comum, o ducto cístico e a vesícula biliar.","C":"O apêndice vermiforme mede cerca de 8 cm de comprimento, sua localização mais frequente é\nretrocecal e, quando está inflamado, a presença do sinal de Blumberg sugere irritação do peritônio\nparietal e o provável diagnóstico de apendicite\n\naguda.","D":"Em um paciente estável hemodinamicamente que apresenta hemorragia digestiva alta e exame\nendoscópico com identificação de uma úlcera duodenal, o provável vaso responsável pelo\nsangramento será a artéria gastroduodenal e o tratamento será cirúrgico.","E":"Paciente portador de neoplasia de esôfago médio, durante uma esofagectomia, optou-se pelo\nestômago como órgão para a reconstrução do trânsito a partir da confecção de um tubo gástrico\npara anastomose com esôfago proximal. Dessa forma, deve-se ter cuidado especial em preservar a\nartéria gástrica esquerda que será responsável por nutrir o tubo gástrico."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-180142","number":"180142","sourceNumber":"180142","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A causa mais comum de obstrução do intestino grosso em adultos é:","options":{"A":"Neoplasia de cólon.","B":"Volvo de sigmoide.","C":"Doença diverticular na forma hipertônica.","D":"Aderências e bridas.","E":"Hérnia interna."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-134874","number":"134874","sourceNumber":"134874","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 65 anos, sexo masculino, portador de laparotomia prévia (ráfia de úlcera\nduodenal perfurada há 15 anos), vem ao pronto-socorro com queixa de dor abdominal, náuseas,\nvômitos (inicialmente com restos alimentares e depois biliosos), além da parada de eliminação de\ngases e fezes há 24 horas. Ao exame clínico, apresenta algum grau de desidratação, distensão\nabdominal e ruídos hidroaéreos presentes e aumentados. A radiografia do abdome mostra\ndistensão das alças do intestino delgado com a presença de níveis hidroaéreos. Considerando o\ndiagnóstico de abdome agudo obstrutivo, sendo uma suboclusão intestinal, a MELHOR conduta,\nneste caso, é:","options":{"A":"Laparotomia exploradora.","B":"Descompressão abdominal através de sonda nasogástrica aberta em sifonagem e correção\nhidroeletrolítica.","C":"Tomografia abdominal.","D":"Êntero-clisma com solução glicerinada."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-131356","number":"131356","sourceNumber":"131356","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Febre alta, taquicardia, dilatação colônica e leucocitose. Pensar em:","options":{"A":"Doença de Chron.","B":"Enteropatia chagásica.","C":"Megacólon tóxico.","D":"Diverticulose.","E":"Apendicite."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-110032","number":"110032","sourceNumber":"110032","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Das alternativas abaixo, qual delas apresenta um fator que interfere em pior\nprognóstico, o caso de abdome agudo obstrutivo?","options":{"A":"Obstrução do 1/3 proximal do intestino delgado.","B":"Obstrução do sigmoide.","C":"Estrangulamento de alça intestinal.","D":"Insuficiência renal aguda."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-108564","number":"108564","sourceNumber":"108564","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente ictérico, com dor e distensão abdominal, parada na eliminação de gases e\nfezes, febril e com episódios de vômito.\nQual o exame de imagem você solicitaria inicialmente neste\ncaso?","options":{"A":"TC abdome.","B":"USG abdome.","C":"CPRE.","D":"Rotina radiológica para abdome agudo.","E":"Colangioressonância."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-13206","number":"13206","sourceNumber":"13206","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 70 anos com hérnia inguinal de início recente. Com relação ao\npré-operatório, assinale a INCORRETA:","options":{"A":"Deve-se investigar pneumopatia e tratá-la previamente à cirurgia.","B":"Na anamnese deve-se pesquisar sinais de prostatismo.","C":"História de episódios de suboclusão intestinal, sem encarceramento associado, não necessita de\ninvestigação adicional.","D":"A avaliação cardiológica é obrigatória.","E":"Deve-se orientar o paciente quanto a possibilidade de uso da tela."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-362510","number":"362510","sourceNumber":"362510","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente do sexo feminino, 49 anos, dá entrada no pronto atendimento queixando dor\nabdominal tipo cólica, difusa, progressiva, há 3 dias, associada a vários episódios de vômitos.\n\nRefere parada de eliminação de gases e fezes desde o início do quadro. Encontra-se desidratada,\nFR: 28irpm, FC: 90bpm, P.A.: 100x70mmHg,\nnormocorada, anictérica, sem edemas. Refere\ndiminuição do volume urinário. Seu abdome é distendido, sem cicatrizes ou circulação colateral,\nhipertimpânico, com RHA aumentados em frequência e intensidade, difusamente doloroso à\npalpação, sem sinais de irritação peritoneal e sem massas palpáveis. Regiões inguinais e crurais\nsem herniações. Foi solicitada radiografia simples de abdome que evidenciou volumosa distensão\nde intestino delgado, com sinal de empilhamento de moeda e vários níveis hidroaéreos, sem\ndistensão do cólon e sem pneumoperitôneo. Sobre o caso acima, assinale a alternativa\nINCORRETA:","options":{"A":"A ausência gás na árvore de biliar e de cálculos na vesícula na radiografia de abdome exclui o\ndiagnóstico diferencial de íleo biliar.","B":"Apesar da paciente não ter sido submetida a cirurgias abdominais prévias, não se pode excluir\nas bridas e aderências como diagnóstico\ndiferencial.","C":"O próximo passo na avaliação desta paciente é a tomografia de abdome para definição da\netiologia do quadro e investigação de possíveis sinais de sofrimento de alças intestinais.","D":"Radiografias seriadas de abdome após administração de contraste oral hidrossolúvel podem\nauxiliar na escolha do tratamento para o caso."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-298214","number":"298214","sourceNumber":"298214","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente do sexo feminino, 64 anos, dá entrada no serviço de urgência apresentando\nquadro de dor abdominal difusa, tipo cólica,\nprogressiva, associada a vômitos e parada de\neliminação de gases e fezes, com evolução de 3 dias. Apresentava-se em REG, bastante\ndesidratado, taquicárdico, taquipneico e discretamente hipotenso. Seu abdome é distendido,\ndifusamente doloroso à palpação difusamente, sem irritação peritoneal. Os exames laboratoriais\nevidenciaram anemia, leucocitose moderada, hiponatremia, hipopotassemia e acidose metabólica.\nA radiografia de abdome evidencia distensão significativa de cólon, porém sem distensão\nimportante do intestino delgado. A tomografia de abdome confirmou os dados acima e evidenciou\nárea de estenose tumoral a nível da transição retossigmoidea e sinais de dissecção gasosa da\nparede do cólon direito. Sobre o caso descrito acima, assinale a alternativa INCORRETA:","options":{"A":"Os dados acima nos permitem afirmar que o paciente apresenta válvula íleo-cecal competente.","B":"O tratamento com maiores chances de sucesso para o caso é a sondagem nasogástrica\ndescompressiva, ressuscitação volêmica, correção dos\ndistúrbios eletrolíticos, antibioticoterapia e\nobservação clínica por 48 horas.","C":"O paciente deve ter tratamento adequado instituído urgentemente devido ao risco iminente de\nperfuração do ceco.","D":"A colostomia é parte do acervo técnico cirúrgico possível para o caso acima."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-286719","number":"286719","sourceNumber":"286719","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente do sexo feminino, 56 anos, apresenta quadro de dor abdominal difusa, tipo\ncólica, de intensidade progressiva, há 3 dias, associada à parada de eliminação de gases e fezes.\nApresentou 2 episódios de vômitos de coloração escura e nega febre. Refere constipação crônica\nque piorou nos últimos 6 meses, com perda de peso não referido. Ao exame físico, apresenta-se\nem regular estado geral, algo emagrecida, bastante desidratada, taquicárdica, levemente\ntaquipneica e hipotensa. Seu abdome é distendido, hipertimpânico, difusamente doloroso à\npalpação, sem sinais de irritação peritoneal. Movimento peristáltico visível a nível do epigástrio.\n\nRuídos hidroaéreos aumentados em volume e frequência. Na radiografia de abdome, observamos\nvolumosa distensão de cólon com interrupção do\npadrão gasoso a nível do sigmoide, ausência de\ngás no reto e discreta presença de gases no intestino delgado. Assinale a alternativa INCORRETA:","options":{"A":"O próximo passo no tratamento desta paciente é a colonoscopia, por ser diagnóstica e\nterapêutica neste caso.","B":"Há indicação de laparotomia urgente devido ao risco de perfuração do ceco.","C":"O tratamento inicial com sondagem nasogástrica provavelmente será pouco efetivo no alívio da\ndistensão abdominal desta paciente.","D":"A radiografia de abdome sugere que esta paciente apresenta válvula ileocecal competente."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-139128","number":"139128","sourceNumber":"139128","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Na classificação de Nyhus para as hérnias, as femorais são caracterizadas como:","options":{"A":"tipo V","B":"tipo II","C":"tipo III C","D":"tipo III B"},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-129718","number":"129718","sourceNumber":"129718","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Dentro das etiologias da obstrução mecânica do intestino delgado, qual das abaixo é\nresponsável por até 75% dos casos?","options":{"A":"Aderências intra-abdominais relacionadas à cirurgia abdominal anterior.","B":"Corpos estranhos.","C":"Doença de Crohn.","D":"Tumores."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-103801","number":"103801","sourceNumber":"103801","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Distenção colônica sem fator obstrutivo que simula abdomen agudo cirúrgico, que é\ntratada com procinéticos ou mesmo descompressão através de colonoscopia.","options":{"A":"Megacolon Tóxico.","B":"Síndrome de Ogilvie.","C":"Colite Pseudomembranosa.","D":"Íleo Paralítico."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-81988","number":"81988","sourceNumber":"81988","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Hérnia localizada anterosuperiormente ao ligamento de Poupart, se refere a hérnia:","options":{"A":"Inguinal","B":"De Spiegel","C":"Perineal","D":"Obturadora","E":"Femural"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-81960","number":"81960","sourceNumber":"81960","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Lactente apresentando início súbito de dor em cólica paroxística intensa, seguida de\nvômitos. Mãe refere também eliminação de fezes com aspecto de geleia de morango. À palpação\nabdominal observa-se uma massa em forma de salsicha. O diagnóstico mais provável é:","options":{"A":"Cólicas do lactente","B":"Intussuscepção ou invaginação intestinal","C":"Parasitose intestinal","D":"Gastroenterite aguda","E":"Síndrome do colón irritável"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-60840","number":"60840","sourceNumber":"60840","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um homem de 68 anos, com múltiplas cirurgias abdominais apresenta-se com dor\nabdominal em cólica, de moderada intensidade há três dias, náuseas e vômitos. Ao exame físico,\nas mucosas estão secas e ele está taquicárdico (118 bpm): O abdome está distendido, globoso,\nmas sem sinais de irritação peritoneal. Suspeita-se de oclusão intestinal por bridas. Neste caso, o\nexame complementar e a conduta terapêutica mais adequada são, respectivamente:","options":{"A":"USG e antibioticoterapia.","B":"TC de abdome e laparotomia.","C":"Trânsito de delgado e hidratação.","D":"RX simples de abdome e observação.","E":"Rotina de abdome agudo e colocação de SNG."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-60866","number":"60866","sourceNumber":"60866","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Pela classificação de Nyhus, a hérnia inguinal femoral é de qual tipo?","options":{"A":"Tipo I","B":"Tipo II","C":"Tipo IIIA","D":"Tipo IIIC","E":"Tipo IV"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-61518","number":"61518","sourceNumber":"61518","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente, 55 anos, portador de hérnia inguinoescrotal, foi submetido à hernioplastia\ncujo achado intraoperatório foi de um anel inguinal\ninterno dilatado, medialmente destruindo a\nfáscia transversalis do triângulo de Hasselbach com um componente de saco herniário por\ndeslizamento. Qual a classificação de Nyhus e a técnica cirúrgica a ser adotada?","options":{"A":"Tipo II e reparo à Shouldice.","B":"Tipo III A e reparo à McVay.","C":"Tipo III B e reparo à Lichtenstein.","D":"Tipo III C e reparo à Bassini.","E":"Tipo IV D e reparo à Andrews II."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-60824","number":"60824","sourceNumber":"60824","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Sobre colite de Crohn, todas as alternativas abaixo são corretas, EXCETO:","options":{"A":"Processo patológico é contínuo, estendendo-se do reto ao colon descendente.","B":"Apresenta característica macroscópica de pedra em pavimentação de rua (cobblestoning).","C":"Diferente da colite ulcerativa, o achado de fissura, fístula e abcessos anais é comum.","D":"Apresenta acometimento ileal em mais de 50% das vezes.","E":"Doença é transmural."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-46660","number":"46660","sourceNumber":"46660","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"São causas de obstrução intestinal funcional, EXCETO:","options":{"A":"Porfiria","B":"Uremia","C":"Hipotireoidismo","D":"Bezoar","E":"Pancreatite"},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-49808","number":"49808","sourceNumber":"49808","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Dentre as hérnias de parede abdominal, as mais frequentemente encontradas são as\ninguinais, em cerca de 85% dos casos. Quando, à exploração cirúrgica da região inguinal,\nencontramos um saco hemiário situado lateralmente aos vasos epigástricos inferiores, dizemos que\nessa hérnia é:","options":{"A":"Direta;","B":"Femoral;","C":"Indireta;","D":"Por deslizamento;","E":"Hérnia de Richter."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-46642","number":"46642","sourceNumber":"46642","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A fáscia transversalis representa:","options":{"A":"O limite inferior do canal inguinal.","B":"Assoalho do canal inguinal.","C":"O limite superior do canal inguinal.","D":"A superfície do canal inguinal.","E":"Parte do tendão conjunto."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-34174","number":"34174","sourceNumber":"34174","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A hérnia inguinal direta representa qual tipo na classificação de Nyhus:","options":{"A":"Tipo II","B":"Tipo I","C":"Tipo IIIB","D":"Tipo IIIA","E":"Tipo IIIC"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-34126","number":"34126","sourceNumber":"34126","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"O ileobiliar ocorre devido fístula entre:","options":{"A":"Vesícula e Colédoco.","B":"Vesícula e Cólon Ascendente.","C":"Colédoco e Cólon Transverso.","D":"Vesícula e Duodeno.","E":"Colédoco e Cólon Ascendente."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-34132","number":"34132","sourceNumber":"34132","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"No triângulo de Hesselbach, ocorrem as hérnias:","options":{"A":"Inguinal Direta.","B":"Femural.","C":"Inguinal Indireta.","D":"Spiegel.","E":"Umbilical."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-26653","number":"26653","sourceNumber":"26653","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Qual a principal causa de obstrução do intestino delgado?","options":{"A":"Tumores do intestino delgado.","B":"Hérnias inguiniais","C":"Aderências","D":"Trauma abdominal","E":"Doença inflamatória do intestino delgado(Crohn)"},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-49321","number":"49321","sourceNumber":"49321","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente, 76 anos de idade, sexo masculino, hipertenso, diabético e dislipidêmico,\npassou a referir dor na fossa ilíaca esquerda\nhá dois dias, associada a febre, náuseas e vômitos.\nRelata obstipação crônica. Ao exame físico, não apresentava sinais de resposta inflamatória\nsistêmica. O exame clínico revelava dor à palpação do quadrante inferior esquerdo do abdome,\nonde se palpava uma tumoração ? ponto de maior dor - , porém era difusamente flácido e sem\nsinais de irritação peritoneal. Ruídos hidroaéreos presentes e propulsivos. A principal suspeita\ndiagnóstica é:","options":{"A":"neoplasia de cólon sigmoide.","B":"diverticulite aguda.","C":"infecção do trato urinário.","D":"urolitíase à esquerda.","E":"GIST de intestino delgado."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-49329","number":"49329","sourceNumber":"49329","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente, 76 anos de idade, sexo masculino, hipertenso, diabético e dislipidêmico,\npassou a referir dor na fossa ilíaca esquerda\nhá dois dias, associada a febre, náuseas e vômitos.\nRelata obstipação crônica. Ao exame físico, não apresentava sinais de resposta inflamatória\nsistêmica. O exame clínico revelava dor à palpação do quadrante inferior esquerdo do abdome,\nonde se palpava uma tumoração ? ponto de maior dor - , porém era difusamente flácido e sem\nsinais de irritação peritoneal. Ruídos hidroaéreos presentes e propulsivos. O paciente deve ser\nsubmetido imediatamente a:","options":{"A":"colonoscopia.","B":"urografia excretora.","C":"tomografia axial computadorizada do abdome.","D":"radiografia de trânsito intestinal.","E":"sumário de urina e urocultura."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-49343","number":"49343","sourceNumber":"49343","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente 76 anos de idade, sexo masculino, hipertenso, diabético e dislipidêmico,\npassou a referir dor na fossa ilíaca esquerda\nhá dois dias, associada à febre, náuseas e vômitos.\nRelata obstipação crônica. Ao exame físico, não apresentava sinais de resposta inflamatória\nsistêmica. O exame clínico revelava dor à palpação do quadrante inferior esquerdo do abdome,\nonde se palpava uma tumoração ? ponto de maior dor -, porém era difusamente flácido e sem\nsinais de irritação peritoneal. Ruídos hidroaéreos presentes e propulsivos. O tratamento inicial da\nprincipal suspeita diagnóstica envolve:","options":{"A":"retossigmoidectomia de urgência.","B":"repouso intestinal e antibioticoterapia sistêmica.","C":"antibioticoterapia sistêmica, apenas.","D":"ureterolitotripsia de urgência.","E":"enterectomia de delgado."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-49356","number":"49356","sourceNumber":"49356","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente, 76 anos de idade, sexo masculino, hipertenso, diabético e dislipidêmico,\npassou a referir dor na fossa ilíaca esquerda\nhá dois dias, associada a febre, náuseas e vômitos.\nRelata obstipação crônica. Ao exame físico, não apresentava sinais de resposta inflamatória\nsistêmica. O exame clínico revelava dor à palpação do quadrante inferior esquerdo do abdome,\nonde se palpava uma tumoração ? ponto de maior dor - , porém era difusamente flácido e sem\nsinais de irritação peritoneal. Ruídos hidroaéreos presentes e propulsivos. Os antibióticos\nrelacionados a seguir são eficazes para o caso, exceto:","options":{"A":"meropenen.","B":"piperacilina + tazobactam.","C":"ampicilina + sulbactam.","D":"teícoplanina.","E":"ceftriaxone + metronidazol."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-34995","number":"34995","sourceNumber":"34995","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A protusão do divertículo de Meckel por um defeito na parede abdominal denomina-se\nhérnia de:","options":{"A":"Richter.","B":"Littré.","C":"Spiegel.","D":"Lichtenstein.","E":"Bassini."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-35007","number":"35007","sourceNumber":"35007","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente, sexo feminino, 51 anos de idade, notou tumoração dolorosa na cicatriz\numbilical, de crescimento progressivo desde a\nsua última gravidez. Ao exame físico, presença de\nabaulamento de 3,O cm, redutível na cicatriz umbilical, que aumenta à manobra de Valsalva. O\ndiagnóstico mais provável é:","options":{"A":"nódulo de Irmã Maria José.","B":"hérnia umbilical.","C":"ascite.","D":"lipoma umbilical.","E":"sarcoma umbilical."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-35010","number":"35010","sourceNumber":"35010","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente, sexo feminino. 51 anos de idade, notou tumoração dolorosa na cicatriz\numbilical, de crescimento progressivo desde a\nsua última gravidez. Ao exame físico, presença de\nabaulamento de 3,O cm, redutível na cicatriz umbilical, que aumenta à manobra de Valsalva. O\ntratamento indicado é:","options":{"A":"quimioterapia paliativa.","B":"herniorrafia umbilical.","C":"administração de albumina humana, após paracentese.","D":"ressecção limitada da tumoração umbilical.","E":"ressecção radical com margens de 2,O cm da tumoração umbilical, envolvendo segmentos dos\nmúsculos retos abdominais bilateralmente."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-27431","number":"27431","sourceNumber":"27431","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"O estreitamento do ânulo inguinal profundo para correção das hérnias inguinais é\ndenominado técnica de:","options":{"A":"McVay.","B":"Bassini.","C":"Marcy.","D":"Shouldice.","E":"Wantz."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-27434","number":"27434","sourceNumber":"27434","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Hérnia inguinal indireta com ânulo inguinal profundo alargado (assoalho do canal\ninguinal íntegro) e parede posterior preservada é classificada como Nyhus:","options":{"A":"I.","B":"II.","C":"III.","D":"IV.","E":"V."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-13320","number":"13320","sourceNumber":"13320","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A hérnia que protrai em zona medial à linha semilunar e lateral à bainha extrema do\nmúsculo reto abdominal denomina-se hérnia de:","options":{"A":"Spiegel","B":"Littré","C":"Richter","D":"Crural","E":"Bochdalek"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-11114","number":"11114","sourceNumber":"11114","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente, sexo masculino, 76 anos de idade, com relato de dor abdominal difusa, tipo\ncólica e de forte intensidade, há 3 dias, associada à parada de eliminação de fezes e flatos, no\nmesmo período. Não apresentou vômitos e nega cirurgias prévias sobre o abdome. Ao exame\nfísico, mostrava-se diaforético, com pulso de 116 bpm, fino, frequência respiratória de 26 ipm e\ntensão arterial: 76X37 mmHg. Abdome muito distendido, com RHA deprimidos e dor à palpação\ndifusamente. Radiografia de abdome em ortostase mostra interrupção no trânsito intestinal em 2\npontos distintos. A terapêutica adequada ao caso é:","options":{"A":"indicação cirúrgica absoluta, após rápida otimização clínica inicial","B":"tratamento conservador, com conduta expectante","C":"tratamento clínico apenas, baseado em descompressão nasogástrica, com sonda e\nantibioticoterapia dirigida para bactérias gram-negativas e anaeróbias","D":"definida após a realização e avaliação da tomografia axial computadorizada helicoidal, com triplo\ncontraste do abdome","E":"heparinização plena"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-343355","number":"343355","sourceNumber":"343355","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A conduta mais adequada para este quadro é:","options":{"A":"Cirurgia de emergência.","B":"Correção de distúrbios hidroeletrolíticos e ácido-base, e cirurgia de urgência assim que\nestabilização clínico-laboratorial.","C":"Redução hidrostática ou pneumática.","D":"Correção de distúrbios hidroeletrolíticos e ácido-base e redução do volume da dieta em 30%,\ninibidor de bomba de prótons e reavaliação em 1 semana."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-281876","number":"281876","sourceNumber":"281876","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 72 anos, hipertensa e diabética, queixando-se de dor abdominal de início\nhá 2 dias associada a vômitos, distensão\nabdominal e redução da eliminação de flatos e fezes.\n\nRelata que nos últimos meses apresentou várias crises de cólicas abdominais necessitando de\nmedicação endovenosa para alívio. Nega febre. Nega perda ponderal. Nega sangramento\ngastrointestinal. Ao exame: regular estado geral, desidratada +/4+, corada, anictérica, acianótica,\nafebril. Abdome distendido, com ruídos presentes doloroso a palpação difusa, mas sem sinais de\nirritação peritoneal. Toque retal com ampola vazia. Pela hipótese de síndrome obstrutiva, realizou a\ntomografia de abdome abaixo. A principal hipótese diagnóstica é:","options":{"A":"Síndrome de Bouveret Duodenal.","B":"Cólon Biliar.","C":"Neoplasia de Sigmoide.","D":"Síndrome Ogilvie."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-350868","number":"350868","sourceNumber":"350868","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Mulher de 31 anos com quadro de dor abdominal de início há 3 dias, em região\nperiumbilical, associada a distensão, diarreia e\nvômitos. O vômito tem aspecto esverdeado com\nresíduos alimentares, evoluindo para vômitos biliosos. A diarreia é líquida e com pouco resíduo.\nRealizou cirurgia há 2 semanas para histerectomia transabdominal devido a mioma volumoso. Uma\nradiografia é solicitada. Qual o diagnóstico mais provável?","options":{"A":"Diarreia por abscesso pélvico.","B":"Obstrução intestinal por brida.","C":"Semiobstrução intestinal.","D":"Íleo paralítico."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-259696","number":"259696","sourceNumber":"259696","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente, 72 anos, foi admitido em um hospital secundário, com história de perda\nponderal de 20 kg em 3 meses e quadro clínico\nsugestivo de abdome agudo obstrutivo. Durante a\nlaparotomia, foi evidenciada neoplasia de reto superior estenosante e grande distensão colônica à\nmontante. Qual a melhor estratégia operatória para essa laparotomia?","options":{"A":"Colostomia em alça para descompressão colônica.","B":"Colectomia total com ileorretoanastomose e linfadenectomia.","C":"Retossigmoidectomia com linfadenectomia e anastomose primária.","D":"Retossigmoidectomia com linfadenectomia e colostomia à Hartmann."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-234015","number":"234015","sourceNumber":"234015","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente do sexo masculino, 42 anos, procurou a UPA com relato de que há dois dias\napresenta vômitos, inicialmente claros e, posteriormente, com conteúdo fecaloide, redução na\neliminação de fezes e flatos, associada à dor abdominal em cólica difusa no abdome. Ao exame da\nadmissão, se observava cicatriz mediana de cirurgia anterior por ferimento por arma branca há dez\nanos, distensão abdominal importante e aparentemente sem hérnias de parede abdominal. Foram\nrealizadas radiografias simples de abdome e tórax e o paciente foi regulado para um serviço de\nemergência cirúrgica, onde foi feita a opção por tratamento conservador com medidas de suporte e\ndescompressão gástrica. Atualmente, está com 48 horas de tratamento conservador com o mesmo\nquadro clínico de entrada (não houve piora ou melhora). Qual deve ser a próxima conduta?","options":{"A":"Manter conduta conservadora por mais 48 horas.","B":"Solicitar tomografia computadorizada do abdome.","C":"Solicitar ressona?ncia nuclear magne?tica do abdome.","D":"Indicar abordagem ciru?rgica (laparotomia exploradora)."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-172943","number":"172943","sourceNumber":"172943","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Homem, 20 anos, iniciou quadro de dor abdominal há 6 dias associada a febre e\nvômitos nas últimas 72 horas. Foi submetido\nà apendicectomia, incisão mediana infraumbilical,\ndevido à apendicite aguda, com abscesso em fossa ilíaca direita. Foi coletado material para cultura\ne realizada drenagem da cavidade com dreno tubulolaminar. No 2º pós-operatório, após a\nrealimentação, o paciente começou a apresentar distensão abdominal, náuseas e vômitos,\ninicialmente biliosos e, depois, fecaloides. Após zerar a dieta, qual a melhor conduta a ser\ntomada?","options":{"A":"Requerer pré-operatórios e indicar laparotomia exploradora","B":"Providenciar hemograma, PCR e ultrassonografia abdominal total.","C":"Passar sonda nasogástrica e solicitar radiografia de tórax e abdome.","D":"Solicitar hemocultura e iniciar antibioticoterapia de acordo com a cultura."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-172992","number":"172992","sourceNumber":"172992","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Criança de dois anos de idade chega à Emergência com relato de aspiração de corpo\nestranho, apesar de nenhum adulto ter presenciado o evento. Apresenta sintomas de obstrução,\nerosão ou perfuração em estômago ou intestino: dor abdominal, náuseas, vômitos, febre,\nhematoquezia. Radiografias revelam pneumoperitônio e distensão de alças com nível líquido. Qual\na principal hipótese diagnóstica?","options":{"A":"Ingestão cáustica.","B":"Ingestão de moedas.","C":"Ingestão de ímãs ou baterias.","D":"Ingestão de objetos pontiagudos."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-150795","number":"150795","sourceNumber":"150795","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Mulher de 68 anos submetida à colectomia parcial por pólipo gigante em cólon\ndescendente por laparoscopia. A cirurgia foi\nsem intercorrências, exceto pelo fato da grande\nadiposidade visceral, dificultando de certo modo o procedimento. Evoluiu sem queixas, mantém\npulso de 90 bpm, abdome levemente distendido, flácido e pouco doloroso à palpação. Ruídos\nhidroaéreos ausentes. Esse quadro persiste até o quarto dia pós-operatório, apesar de eletrólitos\nnormais, leucócitos de 13.000/mm3 e proteína C-reativa de 9,3 mg/dl. Diante do quadro descrito,\nqual a conduta mais adequada nesse momento?","options":{"A":"Realizar uma laparoscopia diagnóstica.","B":"Solicitar tomografia para orientar a conduta.","C":"Realizar laparotomia para possível colostomia.","D":"Solicitar ultrassonografia abdominal e iniciar antibióticos."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-126954","number":"126954","sourceNumber":"126954","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Menina, 10 meses de idade, bem nutrida, é atendida no setor de emergência por choro\nintenso há 6 horas. Face a episódios de movimento das pernas de encontro ao abdome,\n\npercebe-se padrão de cólicas abdominais, com intensidade progressiva e a intervalos cada vez\nmenores. Mãe relata ainda vômitos há 2\nhoras. Ao exame, criança encontra-se alerta,\npermanecendo calma nos intervalos de dor e não apresenta alterações hemodinâmicas ou indícios\nclínicos de choque séptico. Abdome se encontra distendido, sem sinais de peritonite. No toque\nretal: ampola vazia, com muco e sangue. Ultrassonografia de abdome revela alça intestinal com\nmulticamadas visíveis (aparência de um ?alvo?). Hemograma normal. Considerando a hipótese\ndiagnóstica mais provável para essa criança, a melhor conduta terapêutica, entre as opções abaixo,\né:","options":{"A":"Distorção da lesão isquêmica por acesso videolaparoscópico.","B":"Enema usando contraste baritado ou ar guiado por fluoroscopia.","C":"Ressecção da lesão intestinal e confecção de ostomias por laparotomia exploradora.","D":"Ressecção da lesão intestinal seguida de anastomose primária por acesso videoassistido."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-102139","number":"102139","sourceNumber":"102139","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Uma criança de nove meses de idade, anteriormente sadia, apresenta subitamente\nchoro intenso, alguns vômitos e distensão\nabdominal. O toque retal revela a presença de sangue.\nQual a hipótese diagnóstica mais provável?","options":{"A":"Íleo infeccioso.","B":"Apendicite aguda.","C":"Invaginação intestinal.","D":"Hérnia inguinal estrangulada."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-65773","number":"65773","sourceNumber":"65773","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Lactente, 6 meses de vida, sexo masculino, nascido prematuro, é trazido pelos pais à\nemergência, com história de irritabilidade iniciada há uma hora, associada a vômitos. Ao exame\nfísico, a criança encontra-se alerta, com bom estado geral. O abdome revela-se flácido e indolor,\nmas se observa abaulamento inguinal tenso e doloroso à esquerda, compatível com hérnia\ninguinal. A melhor conduta inicial para esta criança é:","options":{"A":"agendar operação eletiva.","B":"indicar operação de urgência.","C":"internar e reavaliar após 48 horas.","D":"tentar reduzir o conteúdo herniário.","E":"aguardar o período de jejum anestésico e proceder a operação."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-65752","number":"65752","sourceNumber":"65752","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 80 anos, com queixa de dor epigástrica há 6 meses, há cerca de 3 dias\ncomeçou a apresentar vômitos, inicialmente pós-prandiais e atualmente com conteúdo claro, não\nbilioso em vários episódios e sem melhora com tratamento medicamentoso. O exame de raio X de\nabdome apresenta imensa distensão gástrica com pobreza de imagens de gases no restante da\ncavidade abdominal. Considerando os distúrbios hidroeletrolíticos e acidobásicos mais frequentes\nnessa situação, qual das seguintes propostas de reposição hidroeletrolítica é mais aplicável?","options":{"A":"Ringer Simples seguida de NaCl 19,1%.","B":"Ringer Lactato seguido de salina isotônica.","C":"Salina hipotônica seguida de Ringer Lactato.","D":"Salina isotônica seguida de solução com KCl.","E":"Salina hipertônica seguida de Ringer Lactato."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-51140","number":"51140","sourceNumber":"51140","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"O câncer colorretal é uma doença cujo rastreamento (?screening?) é justificável\nconsiderando tratar-se de doença grave,\nrelativamente comum, de crescimento lento e, em geral,\nse origina de lesões pré-neoplásicas. Em qual das opções abaixo a indicação de colonoscopia para\nrastreamento (\"screening\") de câncer colorretal é indicada?","options":{"A":"Paciente de 55 anos com anemia sem causa aparente.","B":"Paciente de 60 anos com lesão tumoral palpável ao toque retal.","C":"Paciente de 40 anos com 2 parentes em primeiro grau com câncer colorretal.","D":"Paciente de 65 anos com alteração de hábito intestinal e fezes mucossanguinolentas."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-141619","number":"141619","sourceNumber":"141619","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Com relação ao quadro clínico de obstrução intestinal aguda, é correto afirmar:","options":{"A":"Faixas de aderência ou hérnias internas secundárias a uma operação abdominal realizada no\npassado e hérnias externas respondem por\ncerca de 75% dos casos.","B":"A incidência de obstrução intestinal pós-operatória é maior nos pacientes submetidos a\noperações laparoscópicas do que nos procedimentos abertos.","C":"A obstrução intestinal mecânica caracteriza-se por dor em pontadas na região média do\nabdome, que tende a ser menos grave quanto mais alta for a obstrução.","D":"Leucograma normal exclui a presença de estrangulamento."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-45396","number":"45396","sourceNumber":"45396","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Pacientes com quadro clínico característico de obstrução intestinal alta podem\napresentar:","options":{"A":"alcalose metabólica hiperclorêmica e hipocalêmica.","B":"acidose metabólica hipoclorêmica e hipocalêmica.","C":"acidose metabólica hiperclorêmica e hipocalêmica.","D":"alcalose metabólica hipoclorêmica e hipocalêmica.","E":"alcalose metabólica hipoclorêmica e hipercalêmica."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-36951","number":"36951","sourceNumber":"36951","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Qual a melhor maneira de tratar um paciente de 48 anos, previamente saudável, com\nquadro de obstrução intestinal por hérnia inguinal, na emergência?","options":{"A":"Redução do conteúdo do saco herniário com manobras de compressão percutânea.","B":"Basear-se no exame físico e laboratorial para indicar cirurgia de urgência.","C":"Realizar laparotomia exploradora na possibilidade de ressecção de alça intestinal.","D":"Abordar por inguinotomia, mesmo havendo a necessidade de ressecção intestinal."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-37392","number":"37392","sourceNumber":"37392","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A.P.S.D., masculino, 78 anos, é admitido na emergência com quadro de dois dias de\nevolução caracterizado por dor abdominal tipo cólica, náuseas, vômitos inicialmente alimentares e\nposteriormente de conteúdo entérico e parada da eliminação de flatos e fezes. Ao exame\nabdominal, notava-se abaulamento doloroso na região inguinal direita, irredutível e ruídos\nabdominais diminuídos em número e com timbre metálico. Com relação ao quadro exposto, qual\ndos seguintes achados imaginológicos é mais característico da afecção pela qual o paciente é\nacometido?","options":{"A":"Sinal de empilhamento de moedas.","B":"Presença de gás sob a cúpula diafragmática direita.","C":"Presença de gás no reto.","D":"Sinal da mordida da maçã (?Apple core?).","E":"Sinal do bico de ave."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-30933","number":"30933","sourceNumber":"30933","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Durante herniorrafia inguinal eletiva, um cirurgião observa que uma porção da parede\ndo ceco faz parte do saco herniário. Isto o\nfaz não ressecar completamente o saco, e sim, reduzí-lo.\nQual o nome desse tipo de hérnia?","options":{"A":"Littré.","B":"Richter.","C":"Deslizamento.","D":"Encarcerada.","E":"Estrangulada."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-24328","number":"24328","sourceNumber":"24328","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"São causas de íleo paralítico, EXCETO:","options":{"A":"Hemorragia retroperitoneal.","B":"Aderências.","C":"Isquemia intestinal.","D":"Sepse sistêmica."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-24338","number":"24338","sourceNumber":"24338","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Qual das opções relatadas abaixo não representa uma complicação diretamente\nrelacionada com o tratamento cirúrgico das hérnias inguinais?","options":{"A":"Orquite isquêmica.","B":"Infecção de ferida cirúrgica.","C":"Azospermia.","D":"Hematoma de saco escrotal."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-27767","number":"27767","sourceNumber":"27767","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A hérnia inguinal cujo conteúdo é um divertículo de Meckel é chamada de:","options":{"A":"Littré","B":"Petit","C":"Spiegel","D":"Pantaloon","E":"Grynfelt"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-25306","number":"25306","sourceNumber":"25306","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Em relação ao Volvo de ceco, assinale a alternativa correta:","options":{"A":"A redução endoscópica é menos eficaz que nos volvulos distais, mas apresenta resultados\npromissores nos casos de báscula cecal.","B":"É causa frequente de obstrução intestinal","C":"Ocorre mais em idosos e homens","D":"Tem como principal fator de risco a constipação crônica","E":"O tratamento inicial de escolha é sondagem nasogástrica e jejum para destorção espontânea."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-25342","number":"25342","sourceNumber":"25342","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Qual cirurgia confere menor índice de recidiva para tratamento de uma hérnia inguinal\nNihus III C?","options":{"A":"Ligadura do saco herniário","B":"Bassini","C":"Shouldice","D":"Mac Vay","E":"Lichtenstein"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-13421","number":"13421","sourceNumber":"13421","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Mulher de 43 anos apresenta abaulamento em região inguinal logo abaixo do ligamento\ninguinal. Refere que este abaulamento fica doloroso quando realiza esforços físicos e que\nconsegue com dificuldade reduzir o volume através de compressão. Classifique este tipo de hérnia:","options":{"A":"Nihus IIa.","B":"Nihus IIb.","C":"Nihus IIIa.","D":"Nihus IIIb.","E":"Nihus IIIc."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-17823","number":"17823","sourceNumber":"17823","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Em relação ao choque, assinale a alternativa verdadeira.","options":{"A":"Diferente da sepse, o choque é uma condição essencialmente hemodinâmica e não mediada por\nmediadores inflamatórios e neuroendócrinos","B":"Durante o choque prolongado, pode ocorrer perda da barreira epitelial entérica, com\nconsequente translocação bacteriana e amplificação da resposta inflamatória.","C":"A resposta homeostática à hipoperfusão promove uma redistribuição circulatória desviando o\nfluxo de tecidos como trato gastrintestinal e SNC para o coração.","D":"Durante a perda sanguínea, os primeiros parâmetros clínicos que se alteram são a pressão\nsistólica e o volume urinário.","E":"Durante o manejo do choque, após garantir uma boa ventilação, devem-se administrar\nprecocemente soluções para reposição volêmica como coloides e cristaloides."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-365624","number":"365624","sourceNumber":"365624","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A principal artéria do apêndice cecal é a artéria apendicular, que é um ramo direto da\nartéria","options":{"A":"ileocólica.","B":"cólica média.","C":"mesentérica superior.","D":"cólica direita."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-365622","number":"365622","sourceNumber":"365622","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Uma paciente de 65 anos de idade, obesa, com dislipidemia, diabética e tabagista,\nprocurou atendimento de urgência queixando-se de\ndor abdominal que iniciou há dois dias. Refere\nparada de evacuação há três dias e iniciou quadro de vômitos há 12 horas. Nega febre, calafrios ou\nsintomas associados. Ao exame físico, os sinais vitais na admissão são PA = 140 mmHg x 72\nmmHg, FC = 115 bpm, glicemia capilar = 280 mg/dL e SatO2 = 93%. Foram constatados\nabaulamento na região inguinal esquerda, endurecimento local à palpação logo abaixo do\nligamento inguinal direito, com dor intensa local, abdome distendido, com dor difusa, porém sem\nsinais de irritação peritoneal. Foi feito o diagnóstico sindrômico de abdome agudo. De acordo com\nesse caso clínico, assinale a alternativa que apresenta o tipo de abdome agudo, a etiologia dos\nsintomas e a melhor conduta para a paciente.","options":{"A":"Obstrutivo-hérnia femoral encarcerada-inguinotomia","B":"Inflamatório-hérnia femoral encarcerada-laparotomia exploradora","C":"Obstrutivo-hérnia inguinal estrangulada-laparotomia exploratória","D":"Inflamatório-hérnia inguinal estrangulada-inguinotomia."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-365617","number":"365617","sourceNumber":"365617","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Uma paciente de 65 anos de idade apresenta uma massa indolor na região abdominal\ninferior direita há cerca de seis meses. Ela\nrelatou desconforto ocasional na área da massa mas\nsem outros sintomas associados. Seu histórico médico inclui hipertensão arterial controlada e\nosteoartrite. Na admissão, os sinais vitais apresentavam PA = 140 mmHg x 90 mmHg, FC = 80\nbpm, FR = 16 irpm e temperatura = 37 °C. Ao exame físico, observou-se a presença de uma massa\npalpável, não dolorosa, na região abdominal inferior direita, não redutível à palpação. Considerando\na apresentação clínica dessa paciente, o diagnóstico mais provável é hérnia","options":{"A":"inguinal direta.","B":"femoral.","C":"incisional.","D":"de Spiegel."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-349764","number":"349764","sourceNumber":"349764","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Qual das seguintes alternativas apresenta a maior causa de obstrução do intestino\ndelgado?","options":{"A":"Hérnias.","B":"Doença de Crohn.","C":"Aderências.","D":"Neoplasias.","E":"Doenças neurológicas."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-349762","number":"349762","sourceNumber":"349762","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um paciente de 65 anos apresenta dor, distensão abdominal e vômitos repetidos há 2\ndias. Não evacua e não elimina flatos há 3 dias. Os exames de imagem mostram distensão de\nintestino delgado e fezes em reto. Assinale a alternativa que apresenta a melhor conduta inicial\npara tratamento desse paciente.","options":{"A":"Coletar exames laboratoriais para detectar se há distúrbios hidroeletrolíticos e efetuar passagem\nde sonda nasogástrica para drenagem e\nhidratação.","B":"Indicar laparotomia exploradora para melhor diagnosticar e tratar o paciente, já que ele\napresenta o quadro há mais de 2 dias.","C":"Coletar exames laboratoriais para detectar se há sinais de infecção associada; passar sonda\nnasoenteral para alimentação pós-pilórica e iniciar antibióticos de forma profilática.","D":"Conversar com os familiares e indicar laparotomia exploradora com ileostomia associada, pois,\nnesses casos de distensão grande do delgado, não é recomendada anastomose primária.","E":"Coletar exames laboratoriais; realizar tomografia para melhor avaliação e, a seguir, encaminhar\no paciente para cirurgia, pois a maior parte\ndesses casos é solucionada por meio de cirurgia."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-305281","number":"305281","sourceNumber":"305281","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um paciente com dor e distensão abdominal associadas a vômitos deu entrada no\npronto atendimento. A suspeita é de uma obstrução do intestino delgado. Qual das seguintes\nalternativas representa a causa mais comum, em geral, desse tipo de obstrução?","options":{"A":"Doença de Crohn.","B":"Neoplasia.","C":"Retocolite ulcerativa.","D":"Aderências.","E":"Hérnia interna."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-298851","number":"298851","sourceNumber":"298851","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um paciente com 62 anos de idade apresenta alteração de hábito intestinal há um ano\ne perda ponderal de 15 kg em 2 meses. Nega\nter realizado exames de rotina. No momento,\napresenta diarreia intensa há 24 horas, com vários episódios de evacuações líquidas, associado a\ndor abdominal difusa. Ao exame físico, está desidratado, com FC = 115 bpm, FR = 19 irpm, SatO2\n\n= 97% e temperatura axilar = 37ºC. Considerando esse caso clínico e os conhecimentos médicos\ncorrelatos, julgue os itens a seguir. O quadro clínico do paciente é incompatível com obstrução\nintestinal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-274353","number":"274353","sourceNumber":"274353","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Referente a vascularização do intestino grosso, é correto afirmar que","options":{"A":"o arco de Riolan comunica a irrigação da artéria mesentérica superior com a inferior.","B":"a artéria retal média é um ramo da artéria mesentérica inferior.","C":"a artéria mesentérica superior origina ramos que irrigam principalmente o cólon descendente e\nsigmoide.","D":"a artéria retal inferior, na maioria das vezes, tem origem direta da artéria mesentérica\ninferior.","E":"a artéria cólica média geralmente se origina da artéria mesentérica inferior."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-250132","number":"250132","sourceNumber":"250132","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um paciente de 55 anos de idade procurou o ambulatório de cirurgia, queixando-se de\nabaulamento em região inguinal direita há seis meses, com piora lenta e progressiva. Relata que o\nabaulamento piora com exercícios físicos. Refere apresentar, como doença associada, a\nhipertensão arterial, com uso regular de anti-hipertensivos. Ao exame físico, encontra-se em bom\nestado geral, com abdome plano, flácido e indolor e com abaulamento em região inguinal quando\nrealiza a manobra de Valsalva. Com base nesse caso hipotética e nos conceitos médicos a ele\nassociados, julgue o item a seguir. A investigação de prostatismo é importante na determinação de\num fator de risco para o desenvolvimento de hérnia inguinal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-250133","number":"250133","sourceNumber":"250133","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um paciente de 55 anos de idade procurou o ambulatório de cirurgia, queixando-se de\nabaulamento em região inguinal direita há seis meses, com piora lenta e progressiva. Relata que o\nabaulamento piora com exercícios físicos. Refere apresentar, como doença associada, a\nhipertensão arterial, com uso regular de anti-hipertensivos. Ao exame físico, encontra-se em bom\nestado geral, com abdome plano, flácido e indolor e com abaulamento em região inguinal quando\nrealiza a manobra de Valsalva. Com base nesse caso hipotética e nos conceitos médicos a ele\nassociados, julgue o item a seguir. Após uma avaliação pré-operatória, a cirurgia de correção da\nhérnia está indicada para o paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-250134","number":"250134","sourceNumber":"250134","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um paciente de 55 anos de idade procurou o ambulatório de cirurgia, queixando-se de\nabaulamento em região inguinal direita há seis meses, com piora lenta e progressiva. Relata que o\nabaulamento piora com exercícios físicos. Refere apresentar, como doença associada, a\nhipertensão arterial, com uso regular de anti-hipertensivos. Ao exame físico, encontra-se em bom\nestado geral, com abdome plano, flácido e indolor e com abaulamento em região inguinal quando\nrealiza a manobra de Valsalva. Com base nesse caso hipotética e nos conceitos médicos a ele\nassociados, julgue o item a seguir. A técnica cirúrgica recomendada é a de Bassini, sem a\nnecessidade de colocação de tela, pois o paciente deve apresentar uma parede abdominal\nsuficientemente firme para realizar a sutura das estruturas da parede posterior.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-250135","number":"250135","sourceNumber":"250135","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um paciente de 55 anos de idade procurou o ambulatório de cirurgia, queixando-se de\nabaulamento em região inguinal direita há seis meses, com piora lenta e progressiva. Relata que o\nabaulamento piora com exercícios físicos. Refere apresentar, como doença associada, a\nhipertensão arterial, com uso regular de anti-hipertensivos. Ao exame físico, encontra-se em bom\nestado geral, com abdome plano, flácido e indolor e com abaulamento em região inguinal quando\nrealiza a manobra de Valsalva. Com base nesse caso hipotética e nos conceitos médicos a ele\nassociados, julgue o item a seguir. A cirurgia videolaparoscópica pode ser realizada para o\ntratamento do doente, sendo a técnica intraperitoneal a mais utilizada em casos como esse.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-250136","number":"250136","sourceNumber":"250136","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um paciente de 55 anos de idade procurou o ambulatório de cirurgia, queixando-se de\nabaulamento em região inguinal direita há seis meses, com piora lenta e progressiva. Relata que o\nabaulamento piora com exercícios físicos. Refere apresentar, como doença associada, a\nhipertensão arterial, com uso regular de anti-hipertensivos. Ao exame físico, encontra-se em bom\nestado geral, com abdome plano, flácido e indolor e com abaulamento em região inguinal quando\nrealiza a manobra de Valsalva. Com base nesse caso hipotética e nos conceitos médicos a ele\nassociados, julgue o item a seguir. No pós-operatório da cirurgia de correção de hérnia, o paciente\ndeverá evitar qualquer tipo de atividade física por, pelo menos, seis meses, para reduzir a chance\nde recidiva da hérnia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-250137","number":"250137","sourceNumber":"250137","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um paciente de 55 anos de idade procurou o ambulatório de cirurgia, queixando-se de\nabaulamento em região inguinal direita há seis meses, com piora lenta e progressiva. Relata que o\nabaulamento piora com exercícios físicos. Refere apresentar, como doença associada, a\nhipertensão arterial, com uso regular de anti-hipertensivos. Ao exame físico, encontra-se em bom\nestado geral, com abdome plano, flácido e indolor e com abaulamento em região inguinal quando\nrealiza a manobra de Valsalva. Com base nesse caso hipotética e nos conceitos médicos a ele\nassociados, julgue o item a seguir. A melhor abordagem para uma hérnia recidivada que foi\noperada inicialmente por via aberta é a via laparoscópica, que evitaria as aderências da cirurgia\nanterior, proporcionando efetividade no tratamento e menos dor pós-operatória.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-211991","number":"211991","sourceNumber":"211991","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Considere uma paciente com antecedente de isquemia mesentérica, com colectomia\ntotal, em pós-operatório com boa evolução em\nuso de nutrição parenteral. Durante a explicação do\nmédico para a família a respeito da síndrome de má absorção, ele informa os familiares de que,\nalém da digestão e da absorção de nutrientes, o intestino tem outras funções. Com base nesse\ncaso clínico e nos conhecimentos médicos correlatos, é correto afirmar que o intestino tem as\nfunções de:","options":{"A":"Síntese de vitaminas; absorção de carboidratos; metabolismo da água; e controle de pH\ncorporal.","B":"Defesa do sistema cardiovascular; controle hídrico; e regulação de proteínas e aminas.","C":"Barreira e defesa imune; absorção e secreção de líquidos e eletrólitos; síntese e secreção de\nvárias proteínas; e produção de diversas aminas bioativas e peptídeos.","D":"Sistema tampão no organismo, com controle hídrico, produção de vitaminas e absorção de\naminoácidos essenciais.","E":"Defesa imune; produção de aminas e carboidratos; correção de distúrbios hidroeletrolíticos; e\ncontrole hormonal."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-177714","number":"177714","sourceNumber":"177714","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente do sexo masculino, com 30 anos de idade, vai ao consultório apresentando\nabaulamento com propulsão na região inguinal\ndireita. Exame físico e exame de imagem\napresentam hérnia inguinal tipo II na classificação de Nyhus. O paciente não apresenta outras\nalterações no exame físico; nega outras doenças, uso de medicamentos e cirurgias prévias. Em\nrelação às hérnias inguinais, atualmente, sabe-se que a tensão dos tecidos no reparo das hérnias\ninguinais tem sido considerada um dos principais fatores de recidiva. Com base no caso clínico\napresentado e nos conhecimentos médicos a ele relacionados, julgue o item a seguir. Esse\npaciente se beneficiaria de uma hernioplastia Lichenstein, que é um reparo livre de tensão e com\nuso de tela.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-177627","number":"177627","sourceNumber":"177627","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente do sexo masculino, com 30 anos de idade, vai ao consultório apresentando\nabaulamento com propulsão na região inguinal\ndireita. Exame físico e exame de imagem\napresentam hérnia inguinal tipo II na classificação de Nyhus. O paciente não apresenta outras\nalterações no exame físico; nega outras doenças, uso de medicamentos e cirurgias prévias. Em\nrelação às hérnias inguinais, atualmente, sabe-se que a tensão dos tecidos no reparo das hérnias\ninguinais tem sido considerada um dos principais fatores de recidiva. Com base no caso clínico\napresentado e nos conhecimentos médicos a ele relacionados, julgue o item a seguir. O reparo\nvideolaparoscópico extraperitoneal e pré-peritoneal transabdominal de hérnias inguinais é uma\ntécnica que promove mais tensão nos tecidos pela fixação da tela.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-177632","number":"177632","sourceNumber":"177632","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente do sexo masculino, com 30 anos de idade, vai ao consultório apresentando\nabaulamento com propulsão na região inguinal\ndireita. Exame físico e exame de imagem\napresentam hérnia inguinal tipo II na classificação de Nyhus. O paciente não apresenta outras\nalterações no exame físico; nega outras doenças, uso de medicamentos e cirurgias prévias. Em\nrelação às hérnias inguinais, atualmente, sabe-se que a tensão dos tecidos no reparo das hérnias\ninguinais tem sido considerada um dos principais fatores de recidiva. Com base no caso clínico\napresentado e nos conhecimentos médicos a ele relacionados, julgue o item a seguir. Caso se\noptasse por Bassini, a técnica de reparo seria com tendão conjunto e ligamento inguinal, sem tela,\nsendo uma técnica sem tensão.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-177638","number":"177638","sourceNumber":"177638","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente do sexo masculino, com 30 anos de idade, vai ao consultório apresentando\nabaulamento com propulsão na região\ninguinal direita. Exame físico e exame de imagem\napresentam hérnia inguinal tipo II na classificação de Nyhus. O paciente não apresenta outras\nalterações no exame físico; nega outras doenças, uso de medicamentos e cirurgias prévias. Em\nrelação às hérnias inguinais, atualmente, sabe-se que a tensão dos tecidos no reparo das hérnias\ninguinais tem sido considerada um dos principais fatores de recidiva. Com base no caso clínico\napresentado e nos conhecimentos médicos a ele relacionados, julgue o item a seguir. No reparo de\nhérnia inguinal com tensão, a técnica de McVay utiliza a fáscia transversal e o ligamento de\nCooper.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-179179","number":"179179","sourceNumber":"179179","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"As causas de obstrução do intestino delgado mudaram drasticamente desde 1900. Na\nvirada do século XX, hérnias eram responsáveis por mais de 50% das obstruções intestinais\nmecânicas. Com o reparo eletivo rotineiro das hérnias, esta causa passou a ser a terceira mais\ncomum de obstrução do intestino delgado nos países industrializados. As aderências secundárias à\ncirurgia prévia agora são a causa mais comum de obstrução do intestino delgado. Courtney M.\nTownsend (coord.), Sabiston. Tratado de cirurgia: a base biológica da prática cirúrgica moderna.\n\n19.ª ed. v. 2. Rio de Janeiro: Elsevier, c2015, p. 2173 (e-book). A respeito da temática abordada no\ntexto acima, assinale a alternativa correta.","options":{"A":"A maioria dos tumores malignos que causam obstrução intestinal são provenientes de lesões a\ndistância, como a mama, o pulmão e o melanoma.","B":"No início de uma obstrução, o aumento do peristaltismo ocorre somente acima do ponto da\nobstrução, como tentativa de propelir os conteúdos luminais além do ponto obstruído.","C":"A obstrução do intestino delgado pode ser secundária a um abscesso intra-abdominal, como\nresultado de um íleo local adjacente ao abscesso.","D":"A intuissucepção não é causa de obstrução intestinal no adulto.","E":"Hipocloremia, hipopotassemia e acidose metabólica constituem efeitos metabólicos secundários\nà perda de líquidos para o terceiro espaço\ncausada por uma obstrução alta."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-154343","number":"154343","sourceNumber":"154343","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"L. B., 65 anos de idade, dá entrada no pronto-socorro com quadro de abdome agudo\nobstrutivo. Relata quadro de colecistite aguda há três semanas e nega hérnia ou cirurgia prévia.\nNesse caso, considerando-se a possibilidade de íleo biliar, o diagnóstico radiológico clássico é\ndenominado tríade de Rigler, que compreende a (o):","options":{"A":"distensão do delgado, a aerobilia e calcificações pancreáticas.","B":"distensão do delgado, a aerobilia e a presença de imagem em ampola retal em miolo de pão.","C":"distensão do delgado, a aerobilia e a presença de imagem com calcificação no quadrante inferior\ndireito do abdome.","D":"padrão em grão de café, a aerobilia e a presença de imagem em U invertido.","E":"distensão intestinal, a ausência de ar no reto e a perda da redundância das flexuras do cólon."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-131824","number":"131824","sourceNumber":"131824","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Acerca dos cuidados com determinado paciente que apresenta sintomas de diarreia,\nassinale a alternativa correta.","options":{"A":"A diarreia causada pela Salmonella é de origem osmótica.","B":"O fecaloma pode causar diarreia aparente, uma vez que apenas os líquidos conseguem passar\npela obstrução parcial do reto.","C":"Exames de sangue são dispensáveis, mesmo quando se tratar de diarreia persistente.","D":"Febre e hipersensibilidade à palpação no exame físico confirmam uma causa viral do sintoma.","E":"O teste de Schilling deve ser feito para detectar se a causa do sintoma é a má absorção de\ncarboidratos."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-131821","number":"131821","sourceNumber":"131821","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente masculino de 60 anos de idade, sem comorbidades, deu entrada no\npronto-socorro com quadro de parada de eliminação de gases e fezes, vômitos fecaloides e\ndistensão abdominal há três dias. Ao exame físico, apresentava-se em REG, desidratado,\n\ndescorado e taquicárdico. O abdome se apresentava distendido, com ruídos de luta, com sinais de\nirritação peritoneal. O hemograma era de 20.000 leucócitos, com desvio à esquerda de 12%, e os\nraios X mostravam distensão com stop no sigmoide e sinal de Riddler. Nessa situação hipotética, a\nconduta mais adequada é a seguinte:","options":{"A":"Somente analgesia, pois o paciente idoso com peritonite é considerado de mau prognóstico.","B":"Hidratação + reposição hidroeletrolítica, antibioticoterapia largo espectro e observação.","C":"Hidratação + reposição hidroeletrolítica + passagem de sonda nasogástrica aberta e\nobservação.","D":"Hidratação + reposição hidroeletrolítica, antibioticoterapia largo espectro + laparotomia.","E":"Passagem de stent por colonoscopia."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-135075","number":"135075","sourceNumber":"135075","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A respeito de prevenção e tratamento das doenças infecciosas, julgue o item a seguir.\nA tuberculose peritoneal se manifesta mais\nfrequentemente em pessoas idosas, do sexo feminino,\nprovenientes de áreas endêmicas para essa doença e portadoras de HIV. Os pacientes com\ntuberculose que apresentam quadro de obstrução intestinal devem ser tratados com laparotomia\nexploradora, sendo importante, nesses casos, realizar enterectomia dos segmentos isolados\nestenosados.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-131830","number":"131830","sourceNumber":"131830","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente masculino de 60 anos de idade, sem comorbidades, deu entrada no\npronto-socorro com quadro de parada de eliminação de gazes e fezes, vômitos fecaloides e\ndistensão abdominal há três dias. Ao exame físico, apresentava-se em REG, desidratado,\n\ndescorado, e taquicárdico. O abdome se apresentava distendido, com ruídos de luta, com sinais de\nirritação peritoneal. O hemograma era de 20.000 leucócitos, com desvio à esquerda de 12%, e os\nraios X mostravam distensão com stop no sigmoide e sinal de Ridler. Considerando que o achado\ncirúrgico foi de peritonite fecal franca devido à perfuração no ceco por um tumor obstrutivo de\nsigmoide, assinale a alternativa que indica a conduta cirúrgica mais adequada no caso hipotético\napresentado.","options":{"A":"Cirurgia de Hartmann.","B":"Cecostomia no local da perfuração.","C":"Ileostomia + sutura da perfuração no ceco.","D":"Colectomia subtotal com ileosigmoidoanastomose mecânica.","E":"Colectomia total com ileostomia e sepultamento do coto retal."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-131822","number":"131822","sourceNumber":"131822","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Quanto ao tratamento cirúrgico do câncer colorretal, assinale a alternativa CORRETA:","options":{"A":"Os casos de tumores com fístula duodenocólica não devem ser operados, haja vista que invasão\nde duodeno é contraindicação cirúrgica.","B":"A via laparoscópica é contraindicada nos casos com metástases hepáticas.","C":"Tumores do ceco são mais apropriadamente tratados com hemicolectomia direita.","D":"Nos tumores de retossigmoide com invasão do útero, deve-se realizar ressecção multivisceral\ndenominada exenteração pélvica anterior.","E":"A ooforectomia profilática é sempre recomendada."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-88694","number":"88694","sourceNumber":"88694","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Atualmente existem inúmeros pacientes em filas de espera para tratamentos definitivos.\nConsiderando que o tempo pode agravar as condições clínicas desses pacientes, julgue o item a\nseguir. Para o portador de megacólon chagásico, o início do tratamento é irrelevante, visto que a\nincidência de volvo de sigmoide é desprezível.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-82023","number":"82023","sourceNumber":"82023","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A respeito das doenças infecciosas e de seus aspectos epidemiológicos, julgue o item a\nseguir: Em caso de volvo de sigmoide por doença de Chagas, a passagem de uma sonda\nnasogástrica por via retossigmoidoscópica na tentativa de evitar a cirurgia de urgência é\ndesnecessária, pois, na maioria dos casos, há isquemia irreversível do cólon afetado, indicação de\ncirurgia de urgência, ressecção e anastomose primária.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-82137","number":"82137","sourceNumber":"82137","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um lactente de sete meses de idade está chorando há doze horas seguidas. Sabe-se\nque parou de evacuar após ter eliminado fezes\nmucossanguinolentas e que, nas últimas três horas,\napresentou dois episódios de vômitos. No exame físico, foram observadas expressões de dor na\ncriança, além de sinais de desidratação, sem evidência clínica de choque. Considerando o caso\nclínico descrito, julgue o item subsequente. A avaliação clínica desse doente é soberana no\ndiagnóstico e na conduta terapêutica, ao passo que os exames complementares de diagnóstico são\nmedidas auxiliares que poderão completá-la, mas nunca serão decisivos quanto à conduta médica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-82139","number":"82139","sourceNumber":"82139","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um lactente de sete meses de idade está chorando há doze horas seguidas. Sabe-se\nque parou de evacuar após ter eliminado fezes\nmucossanguinolentas e que, nas últimas três horas,\napresentou dois episódios de vômitos. No exame físico, foram observadas expressões de dor na\ncriança, além de sinais de desidratação e sem evidência clínica de choque. Considerando o caso\nclínico descrito, julgue o item subsequente. Os vômitos e a desidratação que esse paciente\napresenta conduzem à alcalose metabólica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-82162","number":"82162","sourceNumber":"82162","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um lactente de sete meses de idade está chorando há doze horas seguidas. Sabe-se\nque parou de evacuar após ter eliminado fezes\nmucossanguinolentas e que, nas últimas três horas,\napresentou dois episódios de vômitos. No exame físico, foram observadas expressões de dor na\ncriança, além de sinais de desidratação, sem evidência clínica de choque. Considerando o caso\nclínico descrito, julgue o item subsequente. Ultrassonografia do abdome é exame altamente\nsensível e específico para o diagnóstico de intussuscepção intestinal como causa da obstrução.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-82138","number":"82138","sourceNumber":"82138","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um lactente de sete meses de idade está chorando há doze horas seguidas. Sabe-se\nque parou de evacuar após ter eliminado fezes\nmucossanguinolentas e que, nas últimas três horas,\napresentou dois episódios de vômitos. No exame físico, foram observadas expressões de dor na\ncriança, além de sinais de desidratação e sem evidência clínica de choque. Considerando o caso\nclínico descrito, julgue o item subsequente. Caso a intussuscepção intestinal seja considerada a\ncausa da obstrução do paciente, a administração de enema baritado é contraindicada devido ao\nrisco de perfuração intestinal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-64649","number":"64649","sourceNumber":"64649","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um paciente, 60 anos de idade, queixa-se de dor abdominal tipo cólica, intensidade\nmoderada, há 3 (três) dias, iniciada em\ntopografia de mesogástrio e irradiando posteriormente para\ntodo o abdome. Além disso, menciona vômitos e episódio isolado de diarreia. No seguimento,\nevoluiu com parada de eliminação de fezes e flatos. Ao exame físico: REG, anictérico, acianótico,\nafebril; FC = 95 bpm, FR = 20 irpm, PA = 130 x 90 mmHg, T = 36,5ºC. (O exame abdominal\nevidenciou aumento de ruídos hidroaéreos, timpanismo e dor difusa à palpação com\ndescompressão brusca negativa). O toque retal não evidenciou alterações. O paciente afirma uma\nrealização progressa (3 anos) de ulcerorrafia, devido à úlcera gástrica perfurada. Sendo assim,\nassinale a alternativa que apresenta o diagnóstico sindrômico em questão.","options":{"A":"Abdome Agudo Obstrutivo.","B":"Abdome Agudo Inflamatório.","C":"Abdome Agudo Vascular.","D":"Abdome Agudo Perfurativo.","E":"Abdome Agudo Hemorrágico."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-64686","number":"64686","sourceNumber":"64686","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um paciente, 28 anos de idade, trabalhador braçal, é trazido ao serviço de emergência\ncom quadro de dor e abaulamento em região\ninguinal direita. O paciente afirma ao plantonista que\npossui hérnia há cerca de 1 (um) ano e meio e que, normalmente, conseguia reduzi-la com\nfacilidade. Entretanto, após esforço físico vigoroso, ela ficou ''presa'', causando dor local,\nnáuseas e\nvômitos. Ao exame, diminuição de ruídos hidroaéreos, abdômen normotenso, dor à palpação\ninguinal, hiperemia a abaulamento na região acometida. Sendo assim, em relação às hérnias,\nassinale a alternativa correta.","options":{"A":"No caso exposto, o procedimento deveria ser somente com analgesia e manobras de redução\ndo saco herniário.","B":"No caso exposto, é indicado tratamento cirúrgico de urgência.","C":"Nas hérnias de deslizamento (quando a parede da víscera forma parte da parede do saco\nherniário), deve-se proceder com ressecção cirúrgica completa do saco herniário.","D":"A hérnia indireta é aquela que se situa medialmente aos vasos epigástricos, dentro do Triângulo\nde Hasselbach.","E":"Hérnias que cursam com fraqueza da parede posterior e alargamento do anel inguinal interno\npertencem ao tipo II da classificação de Nyhus."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-32164","number":"32164","sourceNumber":"32164","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Na avaliação por imagem do abdome agudo, as radiografias simples continuam\ndesempenhando um importante papel na obtenção de imagem de pacientes com dor abdominal\naguda. A(s) radiografia(s) de rotina para abdome agudo é(são):","options":{"A":"Radiografia de tórax deitado.","B":"Radiografia de bacia.","C":"Radiografia de tórax em pé e radiografias de abdome em pé e deitado.","D":"Radiografias de abdome, somente.","E":"Radiografia de tórax de perfil."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-29723","number":"29723","sourceNumber":"29723","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Com relação aos cuidados no pós-operatório, julgue o item que se segue. No\n\npós-operatório, o índice de recorrência de hérnias inguinais relaciona-se, principalmente, à falha\ntécnica na correção cirúrgica inicial.","options":{"A":"Certo","B":"Errado"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-27544","number":"27544","sourceNumber":"27544","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A hérnia direta recorrente corresponde, na classificação de Nyhus para as hérnias da\nvirilha, ao:","options":{"A":"Tipo I.","B":"Tipo III B.","C":"Tipo IV.","D":"Tipo II.","E":"Tipo III A."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-366254","number":"366254","sourceNumber":"366254","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Considerando o contexto de abdome agudo e as imagens apresentadas e julgue o item\nseguinte. A conduta imediata para o quadro clínico da Figura I é cirúrgica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-366253","number":"366253","sourceNumber":"366253","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Considerando o contexto de abdome agudo e as imagens apresentadas e julgue o item\nseguinte. A imagem da Figura II é compatível com abdome agudo obstrutivo na qual se vê \"o sinal\ndo grão de café\".","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-334870","number":"334870","sourceNumber":"334870","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Uma paciente de 72 anos de idade chega ao pronto-socorro com história de distensão\nabdominal há dois dias, parada de eliminação de flatus e de fezes há um dia. Nega náuseas ou\nvômitos. Com base nesses dados clínicos e na radiografia apresentada, o diagnóstico mais\nprovável é","options":{"A":"síndrome de Ogilvie.","B":"volvo de sigmoide.","C":"volvo de ceco.","D":"obstrução intestinal baixa.","E":"diverticulite aguda."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-343443","number":"343443","sourceNumber":"343443","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"ICSB, sexo feminino, 91 anos, com história de DM, HAS e doença coronariana, foi\ninternada há 2 semanas após complicações de uma cirurgia de prótese total de quadril direito.\nRelata cólica de baixa intensidade e que há 5 dias parou de evacuar. Ao exame físico apresenta\nabdome distendido, hipertimpanismo à percussão difusa, dor à palpação profunda difusa e\nperistalse reduzida. A radiografia abdominal mostrou distensão de todo o cólon até o reto.\n\nConsiderando os dados apresentados, a hipótese diagnóstica mais provável para o caso é:","options":{"A":"Neoplasia de cólon.","B":"Volvo de sigmoide.","C":"Pseudo-obstrução intestinal.","D":"Infarto entero-mesentérico."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-273338","number":"273338","sourceNumber":"273338","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Em relação à síndrome de Ogilvie, assinale a alternativa CORRETA:","options":{"A":"A constipação é o achado mais comumente observado.","B":"A radiografia simples do abdome é o método mais útil ao diagnóstico.","C":"A colonoscopia descompressiva deve ser realizada antes de qualquer outra alternativa\nterapêutica.","D":"O tratamento conservador raramente resolve a síndrome de Ogilvie."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-263370","number":"263370","sourceNumber":"263370","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um paciente com 70 anos de idade, com sequela de acidente vascular encefálico,\nacamado, apresenta quadro de distensão abdominal,\ndor tipo cólica intensa e parada de eliminação\nde gases e fezes há cerca de 24 horas. Nega vômitos ou febre. A acompanhante informou que o\npaciente já apresentava constipação crônica, sendo muitas vezes necessário clister glicerinado\npara retirada de fecaloma. Entretanto, desta vez, relata que realizou o clister, sem saída de fezes\ne\ncom piora do quadro abdominal. O exame do abdome estava prejudicado pela pouca interação do\npaciente, mas ele manifestava dor à palpação difusa. O toque retal mostrou ampola retal vazia.\n\nRealizaram-se as radiografias de rotina para abdome agudo, o que evidenciou, além de imagem de\nfecaloma, intensa dilatação de todo o cólon (mais dilatado no ceco ? 11 cm de diâmetro), ausência\nde gás no reto e ausência de dilatação de intestino delgado. A conduta médica indicada para esse\npaciente é:","options":{"A":"Laparotomia exploradora.","B":"Colonoscopia descompressiva.","C":"Esvaziamento colônico manual.","D":"Laxantes via sonda nasogástrica."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-291514","number":"291514","sourceNumber":"291514","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 60 anos de idade, masculino, procura hospital pronto-socorro com história\nde parada de eliminação de flatos e fezes há\ncerca de 1 semana. Nega vômitos. Ao exame físico,\npaciente em regular estado geral, desidratado, dispneico, taquicárdico. Abdome globoso,\nhipertimpânico, doloroso à palpação difusa, com sinais de irritação peritoneal. Toque retal com\nampola retal vazia, sem fezes, sem muco, sem sangue em \"dedo-de-luva\". Solicitadas radiografias\nde tórax e abdome, demonstrando distensão volumosa de cólon e ceco (maior que 12 cm), com\nníveis hidroaéreos, sem distensão de intestino delgado. Baseado nessas informações, qual a\nconduta?","options":{"A":"Sonda nasogástrica.","B":"Observação.","C":"Laparotomia exploradora.","D":"Clister glicerinado."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-227363","number":"227363","sourceNumber":"227363","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Mulher de trinta e cinco anos de idade compareceu ao pronto-socorro com quadro de\ndor abdominal difusa havia 12 horas, associada\na distensão abdominal, vários episódios de vômito\ne parada de eliminação de flatus. A paciente informou que havia evacuado no dia anterior à\nconsulta, que seus ciclos menstruais estavam regulares e que sua última menstruação havia\nocorrido 20 dias antes da consulta. G3P2C2A1. Ao exame físico, apresentou-se desidratada, com\nsinais vitais normais; além disso, o exame revelou ruídos hidroaéreos diminuídos e abdome pouco\ndistendido, doloroso à palpação difusamente, sem sinais de irritação peritoneal. A respeito desse\ncaso clínico e dos múltiplos aspectos a ele relacionados, julgue o item a seguir. Em casos de\nobstrução intestinal, o acesso videolaparoscópico é contraindicado devido ao risco de lesão\niatrogênica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-227364","number":"227364","sourceNumber":"227364","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Mulher de trinta e cinco anos de idade compareceu ao pronto-socorro com quadro de\ndor abdominal difusa havia 12 horas, associada\na distensão abdominal, vários episódios de vômito\ne parada de eliminação de flatus. A paciente informou que havia evacuado no dia anterior à\nconsulta, que seus ciclos menstruais estavam regulares e que sua última menstruação havia\nocorrido 20 dias antes da consulta. G3P2C2A1. Ao exame físico, apresentou-se desidratada, com\nsinais vitais normais; além disso, o exame revelou ruídos hidroaéreos diminuídos e abdome pouco\ndistendido, doloroso à palpação difusamente, sem sinais de irritação peritoneal. A respeito desse\ncaso clínico e dos múltiplos aspectos a ele relacionados, julgue o item a seguir. O primeiro exame\nde imagem a ser solicitado é a radiografia de abdome.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-227365","number":"227365","sourceNumber":"227365","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Mulher de trinta e cinco anos de idade compareceu ao pronto-socorro com quadro de\ndor abdominal difusa havia 12 horas, associada\na distensão abdominal, vários episódios de vômito\ne parada de eliminação de flatus. A paciente informou que havia evacuado no dia anterior à\nconsulta, que seus ciclos menstruais estavam regulares e que sua última menstruação havia\nocorrido 20 dias antes da consulta. G3P2C2A1. Ao exame físico, apresentou-se desidratada, com\nsinais vitais normais; além disso, o exame revelou ruídos hidroaéreos diminuídos e abdome pouco\ndistendido, doloroso à palpação difusamente, sem sinais de irritação peritoneal. A respeito desse\ncaso clínico e dos múltiplos aspectos a ele relacionados, julgue o item a seguir. Com base na\nhistória clínica da paciente e nesse exame físico, a principal hipótese diagnóstica é de obstrução\nintestinal por bridas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-227366","number":"227366","sourceNumber":"227366","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Mulher de trinta e cinco anos de idade compareceu ao pronto-socorro com quadro de\ndor abdominal difusa havia 12 horas, associada\na distensão abdominal, vários episódios de vômito\ne parada de eliminação de flatus. A paciente informou que havia evacuado no dia anterior à\nconsulta, que seus ciclos menstruais estavam regulares e que sua última menstruação havia\nocorrido 20 dias antes da consulta. G3P2C2A1. Ao exame físico, apresentou-se desidratada, com\nsinais vitais normais; além disso, o exame revelou ruídos hidroaéreos diminuídos e abdome pouco\ndistendido, doloroso à palpação difusamente, sem sinais de irritação peritoneal. A respeito desse\ncaso clínico e dos múltiplos aspectos a ele relacionados, julgue o item a seguir. Em razão dos\nvários episódios de vômito, a paciente pode apresentar acidose metabólica.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-227367","number":"227367","sourceNumber":"227367","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Mulher de trinta e cinco anos de idade compareceu ao pronto-socorro com quadro de\ndor abdominal difusa havia 12 horas, associada\na distensão abdominal, vários episódios de vômito\ne parada de eliminação de flatus. A paciente informou que havia evacuado no dia anterior à\nconsulta, que seus ciclos menstruais estavam regulares e que sua última menstruação havia\nocorrido 20 dias antes da consulta. G3P2C2A1. Ao exame físico, apresentou-se desidratada, com\nsinais vitais normais; além disso, o exame revelou ruídos hidroaéreos diminuídos e abdome pouco\ndistendido, doloroso à palpação difusamente, sem sinais de irritação peritoneal. A respeito desse\ncaso clínico e dos múltiplos aspectos a ele relacionados, julgue o item a seguir. Casos de obstrução\nintestinal alta devem sempre ser tratados cirurgicamente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-227378","number":"227378","sourceNumber":"227378","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"As hérnias em geral são doenças prevalentes na população adulta e motivo frequente\nde atendimento em ambulatórios de cirurgia geral. A\nrespeito desse assunto, julgue o item que se\nsegue. O tratamento indicado para pacientes com hérnia inguinal direta difere do indicado para\npacientes com hérnia inguinal indireta.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-227382","number":"227382","sourceNumber":"227382","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"As hérnias em geral são doenças prevalentes na população adulta e motivo frequente\nde atendimento em ambulatórios de cirurgia geral. A\nrespeito desse assunto, julgue o item que se\nsegue. A técnica de separação de componentes pode ser utilizada no tratamento de hérnia\nincisional complexa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-230580","number":"230580","sourceNumber":"230580","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 65 anos, internado em unidade de terapia intensiva para tratamento de\npneumonia viral e síndrome respiratória aguda grave. Em ventilação mecânica invasiva e dieta por\nsonda nasoenteral. Apresentou distensão abdominal, quando foram realizadas algumas lavagens\ncom solução glicerinada sem retorno satisfatório. Trata-se, POSSIVELMENTE, de:","options":{"A":"síndrome de Olgivie.","B":"colite pseudomembranosa.","C":"colite isquêmica.","D":"isquemia mesentérica."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-203096","number":"203096","sourceNumber":"203096","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Considere um paciente de 60 anos de idade com histórico de hematoquezia e perda de\npeso há seis meses, sem procurar\natendimento médico. Há dois dias, apresenta parada de\neliminação de flatos e fezes e distensão abdominal. Tem antecedentes de tabagismo, hipertensão\narterial sistêmica controlada e apendicectomia há 10 anos. Realizou rotina radiológica para abdome\nagudo com laudo de distensão de todo o cólon, sem gás no reto e sem distensão de alças de\ndelgado. Quanto a esse caso clínico, é correto afirmar que a hipótese diagnóstica mais provável e o\nrespectivo tratamento de escolha são:","options":{"A":"Obstrução intestinal por bridas e laparotomia exploradora.","B":"Obstrução intestinal por bridas e tratamento clínico.","C":"Obstrução intestinal por câncer colorretal e laparotomia exploradora.","D":"Obstrução intestinal por câncer colorretal e tratamento clínico.","E":"Diverticulite aguda e antibioticoterapia."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-129032","number":"129032","sourceNumber":"129032","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um paciente com 35 anos de idade, portador de doença de Crohn há cerca de quinze\nanos, apresentou-se com sintomas de obstrução\nintestinal alta. Foi submetido a exames de\nimagem, enterotomografia abdominal e enterorressonância de abdome, que demonstraram áreas\nde estenose compatíveis com fibrose. Considerando essa situação hipotética, assinale a alternativa\nque apresenta a conduta mais apropriada para a resolução definitiva da obstrução intestinal.","options":{"A":"Uso de terapia com medicamentos biológicos.","B":"Prescrição de corticoides.","C":"Terapia de nutrição enteral de alta absorção.","D":"Prescrição de medicação estimuladora da motilidade intestinal.","E":"Ressecção intestinal ou plástica das estenoses."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-133987","number":"133987","sourceNumber":"133987","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A respeito do divertículo de Meckel, assinale a alternativa correta.","options":{"A":"É a anomalia congênita mais comum do trato alimentar e reportada em 1% a 4% da população.","B":"Ocorre em razão do fechamento completo do ducto onfalomesentérico ou incompleto do ducto\nvitelínico durante a gestação.","C":"A maioria é sintomático.","D":"É associado à regra dos 10: fica há 10 cm da válvula ileocecal, é 10 vezes mais frequente em\nhomens, 10% são sintomáticos e aflige crianças aos 10 anos de idade.","E":"Raramente pode estar presente em saco herniário em uma hérnia inguinal encarcerada, que é\nchamada de Hérnia de Pasteur."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-133940","number":"133940","sourceNumber":"133940","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Acerca do íleo paralítico ou adinâmico, assinale a alternativa incorreta.","options":{"A":"Refere a dismotilidade do intestino na ausência de obstrução mecânica.","B":"Por definição, é considerado ausência de peristalse por 10 ou mais dias.","C":"Os sinais e sintomas podem simular obstrução intestinal.","D":"Devem ser afastados distúrbios metabólicos.","E":"É diagnóstico diferencial com brida precoce."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-111310","number":"111310","sourceNumber":"111310","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Em relação ao diagnóstico e tratamento do abdome agudo está INCORRETO:","options":{"A":"A ultrassonografia tem grande acurácia nas patologias da vesícula biliar.","B":"A radiografia simples identifica aproximadamente 5% dos apendicolitos, 10% das colelitíases e\n90% das nefrolitíases.","C":"O volvo do cólon sigmoide costuma ter imagem típica na raidografia simples, sendo o tratamento\na cirurgia de emergência.","D":"Síndrome de Ogilvie é a obstrução funcional do cólon, cujo tratamento medicamentoso é o\nneostigmine.","E":"Devido à frequência e ao mimetismo, a apendicite aguda faz parte do diagnóstico diferencial de\nquase todo o abdômen agudo."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-80725","number":"80725","sourceNumber":"80725","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Acerca da anatomia da região inguinal e das hérnias que acometem essa região,\nassinale a alternativa correta.","options":{"A":"O músculo cremáster origina-se das fibras mais baixas do músculo oblíquo interno.","B":"O ligamento de Cooper é formado por fibras do músculo transverso abdominal.","C":"O saco herniário nas hérnias indiretas localiza-se em posição medial aos vasos epigástricos.","D":"A fáscia transversal é a camada mais externa do canal inguinal e recobre o cordão espermático.","E":"O saco herniário na hérnia femoral é habitualmente lateral aos vasos femorais."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-80745","number":"80745","sourceNumber":"80745","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Assinale a alternativa que apresenta a causa mais comum de abdome agudo obstrutivo\nno adulto.","options":{"A":"Hérnia femoral.","B":"Carcinomatose peritoneal.","C":"Aderências pós-operatórias.","D":"Enterite actínica.","E":"Fitobezoar."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-97820","number":"97820","sourceNumber":"97820","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um paciente com 35 anos de idade vem à Unidade Básica de Saúde com queixa de\ntumoração em região inguinal presente há cerca de um ano. Relata que a tumoração aumentou de\ntamanho desde o início da sintomatologia e que causa dor principalmente aos esforços físicos,\nquando também se torna mais proeminente. Ao exame físico apresenta abdome globoso, flácido,\nindolor à palpação superficial e profunda, ausência de massas palpáveis e/ou visceromegalias,\nruídos hidroaéreos presentes. Em região inguinal direita, apresenta abaulamento não redutível,\ndoloroso à palpação, ausência de hiperemia local; região inguinal esquerda sem alterações;\nausência de espessamento do cordão espermático bilateralmente. O diagnóstico correto e a\nconduta adequada são:","options":{"A":"hérnia inguinal estrangulada à direita; encaminhar para cirurgia de urgência.","B":"hérnia inguinal direta à direita; recomendar evitar esforço físico e uso de analgésico por via\noral.","C":"hérnia inguinal indireta à direita; recomendar evitar esforço físico e uso de fundas para redução\nda hérnia.","D":"hérnia inguinal encarcerada à direita; recomendar evitar esforço físico e encaminhamento ao\nAmbulatório de Cirurgia."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-97832","number":"97832","sourceNumber":"97832","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Uma mulher, com 27 anos de idade, apresentou-se em Serviço de Emergência com dor\nabdominal em cólicas, em mesogástrio, há 48 horas. Houve aumento progressivo na intensidade e\nfrequência da dor e há um dia apresenta vômitos biliosos de diminuição na eliminação de flatos e\nfezes. Os ruídos hidroaéreos estão aumentados em número e intensidade, com timbre francamente\nmetálico. O abdome é pouco distendido, levemente doloroso à palpação profunda e sem\ndescompressão brusca positiva. A paciente relata apendicectomia prévia na infância. Com base no\nquadro clínico exposto, qual a hipótese diagnóstica e exame complementar indicado para\ninvestigação inicial da paciente?","options":{"A":"Urolitíase; radiografia simples de abdome.","B":"Cisto de ovário roto; ultrassonografia pélvica.","C":"Torção de cisto de ovário; ultrassonografia pélvica.","D":"Aderências intestinais; radiografia de abdome de pé e deitada."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-75531","number":"75531","sourceNumber":"75531","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Homem com 65 anos de idade procura a Unidade de Pronto Atendimento porque está\nhá cinco dias sem evacuar, com dor abdominal\ncontínua no hemiabdome esquerdo, de baixa\nintensidade, sem outras queixas. Nega operações prévias, não faz uso de nenhuma medicação e\nrefere peso estável. Quando questionado sobre a dieta, informa que somente come arroz, feijão e\nbife, tanto no almoço como no jantar. Hábito intestinal a cada três dias, com fezes endurecidas. O\npaciente informa que há cerca de dois meses fez exame de fezes com pesquisa de sangue oculto\nnegativa. Ao exame: frequência cardíaca = 68 bpm, pressão arterial = 120 x 80 mmHg, corado,\nhidratado, anictérico, com dor discreta à palpação da fossa ilíaca e flanco esquerdo, onde se palpa\nmassa imprecisa, móvel. Radiografia de abdome em decúbito e ortostatismo evidencia grande\nquantidade de fezes no trajeto de todo o cólon. Para este paciente, a melhor conduta é:","options":{"A":"orientar quanto à mudança de hábitos dietéticos e\nsolicitar enema opaco.","B":"prescrever uso de laxativo e mudança dietética e solicitar colonoscopia.","C":"fazer lavagem intestinal e solicitar ultrassonografia de abdome.","D":"solicitar nova pesquisa de sangue oculto nas fezes.","E":"realizar lavagem intestinal e retossigmoidoscopia."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-137553","number":"137553","sourceNumber":"137553","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um homem de 70 anos de idade, tabagista há mais de trinta anos, com doença\npulmonar obstrutiva crônica, chega ao Pronto Atendimento com queixa de \"dor na virilha\" e\n\"caroço duro\" no local, que surgiram após acesso de tosse importante, há cerca de 10 horas. O\npaciente informa que a intensidade da dor está aumentando. Ao exame físico: paciente\nhidratado, normocorado, frequência cardíaca = 92 bpm, pressão arterial = 140 x 80 mmHg. O\npaciente apresenta tumoração endurecida na fossa ilíaca direita, dolorosa e irredutível; ruídos\nhidroaéreos presentes na ausculta abdominal. Qual a conduta mais indicada para o caso?","options":{"A":"Solicitar ultrassonografia para esclarecimento diagnóstico.","B":"Encaminhar para tratamento cirúrgico de urgência.","C":"Manter paciente em observação, com prescrição de hidratação e analgesia parenterais.","D":"Prover analgesia com opioides por via endovenosa e, em seguida, realizar nova tentativa de\nredução da massa.","E":"Solicitar tomografia abdominal de urgência para esclarecimento diagnóstico."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-137559","number":"137559","sourceNumber":"137559","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um homem de 61 anos de idade foi admitido hoje no Pronto-Socorro com queixas de\nconstipação, inapetência progressiva, aceitando somente dieta líquida desde ontem. O familiar\nrelata parada de eliminação de gases, dor abdominal, vômitos fecaloides e aumento do volume\nabdominal nas últimas 24 horas. O paciente tem diagnóstico de retardo mental desde criança e faz\nuso de haloperidol (5 mg/dia). Nega cirurgia e internação prévias. Ao exame físico, apresenta-se\ndesidratado, com facies de sofrimento, abdome intensamente distendido, timpânico, ruídos\nhidroaéreos ausentes, dor à palpação superficial e profunda, ausência de sinais de irritação\nperitoneal. Toque retal sem fezes na ampola retal, ausência de massas ou alterações palpáveis. A\nradiografia simples de abdome demonstra ausência de gás no reto e imagem de distensão de alças\ncom padrão de \"U\" invertido. Qual deve ser a conduta imediata no tratamento desse paciente?","options":{"A":"Laparotomia exploradora.","B":"Vídeocolonoscopia descompressiva.","C":"Hidratação vigorosa e instalação de sonda nasogástrica.","D":"Instalação de sonda retal e aplicação de clister glicerinado.","E":"Hidratação vigorosa e antibioticoterapia para esterilização do trato intestinal."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-138407","number":"138407","sourceNumber":"138407","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Homem, com 58 anos de idade, é atendido em serviço de urgência e relata a\nocorrência, há cerca de seis meses, de\nmodificação de seu hábito intestinal - períodos de\nconstipação intercalados por evacuações de fezes pastosas, às vezes acompanhadas da\neliminação de muco e sangue. Nesse período foi visto em consultas, nas quais foi prescrito\ntratamento antiparasitário, não havendo melhora da sintomatologia. O paciente informa ainda que\nhá cerca de um mês, vem apresentando intensificação do esforço evacuatório. Nesse período as\nfezes têm se tornado cada vez mais afiladas e há dois dias vem observando a diminuição quase\ncompleta da eliminação de flatos e fezes, relatando também a ocorrência de náuseas e um\nepisódio de vômitos de conteúdo biliar. Com base nessa história, qual a conduta imediata a ser\nseguida ?","options":{"A":"Instalar sonda nasogástrica, prescrever hidratação\nparenteral, lactulona e antieméticos e manter\npaciente em observação.","B":"Instalar sonda nasogástrica, prescrever hidratação\n\nparenteral, clister com solução glicerinada e manter paciente em observação.","C":"Instalar sonda nasogástrica, prescrever hidratação parenteral e clister com solução glicerinada.\n\nA posteriori instalar sonda retal e manter paciente em\nobservação.","D":"Prescrever antiespasmódicos, dimeticona e solicitar colonoscopia com biópsia e dosagem de\nantígeno carcino-embrionário.","E":"Encaminhar imediatamente o paciente para\navaliação cirúrgica."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-30954","number":"30954","sourceNumber":"30954","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Julgue o item seguinte, a respeito da anatomia e fisiologia humanas. A parede\nposterior, ou assoalho, do canal inguinal é\nformada pela fáscia transversal e pela aponeurose do\nmúsculo oblíquo interno.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-138619","number":"138619","sourceNumber":"138619","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente do sexo masculino, com 58 anos de idade, casado, pedreiro, tabagista há 15\nanos (13 cigarros/dia), procura a Unidade\nBásica de Saúde queixando-se de um ?caroço na virilha\nesquerda? que surgiu há cinco meses. Informa que essa tumoração apresentou crescimento\nlentamente progressivo desde então e que procurou o serviço de saúde porque passou a\napresentar dor na região inguinal esquerda durante suas atividades laborais. O exame do tórax não\napresenta alterações. O abdome é indolor e sem visceromegalias palpáveis. O exame das\nextremidades superiores e inferiores, bem como o do períneo, não apresenta anormalidades. Ao\nexame da região inguinal esquerda verifica-se a presença de tumoração mole, bem delimitada,\nretrátil, dolorosa à palpação profunda e que aumenta de tamanho quando se realiza a manobra de\nValsalva. Diante dessa situação, a hipótese diagnóstica e conduta são, respectivamente,","options":{"A":"hérnia inguino-escrotal esquerda, encarcerada;\n\nsolicitar ultrassom escrotal e encaminhar o paciente para o Pronto-Socorro para avaliação de\nurgência pelo cirurgião.","B":"linfoadenomegalia a esclarecer, suspeita de neoplasia; solicitar biópsia excisional e encaminhar\no paciente para o ambulatório de especialidades\npara avaliação do cirurgião.","C":"hérnia inguinal direta esquerda, não complicada;\nencaminhar o paciente para o ambulatório de\nespecialidades para avaliação do cirurgião geral.","D":"hérnia inguinal indireta esquerda; solicitar tomografia de abdome e pelve e encaminhar o\npaciente para avaliação ambulatorial especializada com cirurgião.","E":"massa inguinal a esclarecer, provável neoplasia; solicitar biópsia por punção guiada por\nultrassom e referenciar o paciente para avaliação ambulatorial com cirurgião."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-138734","number":"138734","sourceNumber":"138734","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente, com 60 anos de idade, do sexo masculino, residente da zona da mata de\nPernambuco, procura serviço médico de urgência porque iniciou há 48 horas dor abdominal em\ncólica, agora difusa, vômitos de cor acastanhada escura e odor fétido. Relata ter ?intestino preso?,\nhá muitos anos, mas nunca se preocupou, pois sempre foi assim. Não faz uso de qualquer\nmedicação e nunca foi submetido a procedimento cirúrgico. Não é tabagista e nem etilista. Ao\nexame, está desidratado, hipocorado 1+/++++, Frequência cardíaca = 110 bpm, Pressão arterial =\n90/40 mmHg, sem alteração do aparelho respiratório. Apresenta abdome muito distendido, com\nruídos hidroaéreos presentes, com timbre metálico, timpânico e doloroso à percussão difusa e à\npalpação superficial em todo o abdome. Além da correção da desidratação, a conduta sequencial\npara esse paciente é","options":{"A":"iniciar sedação e encaminhá-lo para tratamento cirúrgico de urgência.","B":"passar cateter nasogástrico, prescrever jejum e iniciar antibioticoterapia.","C":"passar cateter nasogástrico e encaminhá-lo para tratamento cirúrgico de urgência.","D":"encaminhar para centro de especialidades médicas para realizar propedêutica complementar e\ndiagnóstico.","E":"prescrever jejum, iniciar antibioticoterapia e encaminhá-lo para tratamento cirúrgico de\nurgência."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-22151","number":"22151","sourceNumber":"22151","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Considerando que um homem de 50 anos de idade procure o setor de emergência de\num hospital com queixas de dor abdominal,\nvômitos e distensão abdominal associados à parada de\neliminação de fezes e flatos, julgue o próximo item. Caso o paciente seja de zona endêmica para\ndoença de Chagas, o megacólon com volvo deve ser considerado, e o exame diagnóstico principal\na ser utilizado será o clister opaco.","options":{"A":"certo","B":"errado"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-22152","number":"22152","sourceNumber":"22152","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Considerando que um homem de 50 anos de idade procure o setor de emergência de\num hospital com queixas de dor abdominal,\nvômitos e distensão abdominal associados à parada de\neliminação de fezes e flatos, julgue o próximo item. No caso descrito, os vômitos serão mais tardios\ne a distensão abdominal maior quanto mais distal estiver uma eventual obstrução.","options":{"A":"certo","B":"errado"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-22154","number":"22154","sourceNumber":"22154","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Considerando que um homem de 50 anos de idade procure o setor de emergência de\num hospital com queixas de dor abdominal,\nvômitos e distensão abdominal associados à parada de\neliminação de fezes e flatos, julgue o próximo item. Caso fosse detectado pneumoperitônio em\nradiografia simples de abdome, o quadro clínico em questão seria classificado como urgência\nabsoluta, em decorrência do risco de desenvolvimento de peritonite e morte.","options":{"A":"certo","B":"errado"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-354095","number":"354095","sourceNumber":"354095","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um paciente de 30 anos é internado com distensão abdominal e parada de eliminação\nde gases e fezes há 7 dias. Nega episódios\nanteriores parecidos, febre e emagrecimento, mas\nrefere náuseas e vômitos. De histórico patológico pregresso, refere laparotomia devido acidente\nautomobilístico. Quais achados radiográficos e a conduta imediata frente ao caso em questão?","options":{"A":"Níveis hidroaéreos; laparotomia exploradora.","B":"Sinal do \"\"grão de café\"\"; passagem de sonda retal.","C":"Sinal \"\"de empilhamento de moedas\"\"; passagem de sonda nasogástrica e hidratação\nintravenosa.","D":"Sinal de \"\"maçã mordida\"\"; lavagem intestinal com clister.","E":"Sinal de Rigler; desobstrução Intestinal por videocolonoscopia"},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-336253","number":"336253","sourceNumber":"336253","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Mulher, 67 anos procurou pronto socorro por constipação há 10 dias, náuseas e\nvômitos. História de atendimento prévio há 20\ndias devido dor em hipocôndrio direito, náuseas,\nvômitos, porém com resolução espontânea. Submetida a tomografia de abdome com imagem\nsugestiva de aerobilia intra-hepática. A hipótese diagnóstica mais provável para o quadro atual é:","options":{"A":"Colangiocarcinoma avançado","B":"Síndrome de Mirizzi","C":"Síndrome de dumping","D":"Íleo biliar"},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-337621","number":"337621","sourceNumber":"337621","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Leia o trecho a seguir: Um paciente internado com quadro de obstrução intestinal,\napresenta no RX de abdome agudo imagem\ncujo tratamento deve ser a\nprincípio . Assinale a alternativa que preenche CORRETAMENTE as lacunas.","options":{"A":"em pilha de moeda, laparoscopia para lise de aderência.","B":"de níveis hidroaéreos, laparotomia exploradora.","C":"de \"\"U\"\" invertido, colonoscopia descompressiva.","D":"apagamento do psoas, laparoscopia para higiene da cavidade e descompressão."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-335082","number":"335082","sourceNumber":"335082","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A causa mais provável de orquite isquêmica após o reparo de uma hérnia inguinal é","options":{"A":"ligadura da artéria testicular.","B":"excisão completa de um grande saco herniário escrotal.","C":"torção inadvertida do cordão testicular durante o reparo.","D":"compressão excessiva e muita manipulação do cordão testicular durante a operação."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-314017","number":"314017","sourceNumber":"314017","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"O volvo é uma condição na qual o intestino sofre uma torção sobre o seu eixo\nmesentérico, uma situação que resulta em\nobstrução parcial ou completa do lúmen intestinal e de\num grau variável do seu suprimento sanguíneo. Com relação ao volvo intestinal, analisar os itens\nabaixo: I. O volvo é mais comum no cólon sigmoide, com ocorrências menos frequentes envolvendo\no cólon direito e o íleo terminal. II. Medicamentos psicotrópicos podem predispor ao volvo por\nafetarem a motilidade intestinal. III. Os pacientes com volvo de sigmoide podem apresentar uma\nobstrução intestinal aguda ou subaguda, com sinais e sintomas indistinguíveis daqueles causados\npor um câncer do cólon distal. IV. Um nível hidroaéreo pode ser visualizado anterior à alça do cólon\ndilatado, e quase sempre há ar no reto. Estão CORRETOS:","options":{"A":"Somente os itens I, II e III.","B":"Somente os itens I, II e IV.","C":"Somente os itens I, III e IV.","D":"Somente os itens II, III e IV.","E":"Todos os itens."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-314028","number":"314028","sourceNumber":"314028","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Conforme DUNCAN, et al., as hérnias são bastante frequentes, e por isso é\nfundamental o reconhecimento dos seus tipos\ne particularidades para que ocorra adequado\nencaminhamento, pois muitos portadores de hérnia irão receber algum tipo de tratamento cirúrgico\ndesde que não tenham comorbidades clínicas que o contraindiquem. Em relação às hernias de\nparede abdominal, analisar a sentença abaixo: Referente à etiologia, as hérnias de parede\nabdominal podem ser: congênitas, adquiridas ou pós-cirúrgicas (1ª parte). Quando uma hérnia\nencarcerada apresenta sofrimento vascular (isquemia) do seu conteúdo, tem-se uma hérnia\nestrangulada (2ª parte). Hérnia encarcerada dolorosa não redutível ou a suspeita de\nestrangulamento são situações que exigem encaminhamento imediato para avaliação por cirurgião\ngeral em caráter de urgência (3ª parte). A sentença está:","options":{"A":"Totalmente correta.","B":"Correta somente em sua 3ª parte.","C":"Correta somente em suas 1ª e 2ª partes.","D":"Correta somente em suas 2ª e 3ª partes.","E":"Totalmente incorreta."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-257370","number":"257370","sourceNumber":"257370","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente apresenta dor abdominal de cerca de 12 horas, associada à abaulamento na\nregião inguinal direita e náuseas. Você indica a cirurgia de emergência e na indução do ato\nanestésico houve redução espontânea do conteúdo herniado para a cavidade abdominal. Diante\ndesta situação, a MELHOR conduta a ser adotada seria:","options":{"A":"Suspender a cirurgia e programar nova intervenção em caráter eletivo.","B":"Fazer a correção do orifício herniário com reforço da parede com tela de marlex.","C":"Suspender a cirurgia e aguardar a evolução.","D":"Fazer laparotomia exploradora ou laparoscopia."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-266399","number":"266399","sourceNumber":"266399","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente idoso, acamado, trazido a Unidade de Pronto Atendimento com quadro agudo\nde dor abdominal e distensão abdominal,\nmais evidente em andar inferior do abdome, associado\ncom parada de eliminação de fezes e flatos. Família relata histórico de fecaloma de repetição. No\nRaio X de abdome fica evidente imagem com sinal de \"bico de pássaro\" e grande dilatação em\ncólon sigmóide, sem dilatação a montante em alças de delgado. Dentre as hipóteses abaixo, qual o\nprovável diagnóstico?","options":{"A":"Úlcera Gástrica Perfurada.","B":"Pancreatite Aguda.","C":"Retocolite Ulcerativa.","D":"Volvo de Cólon Sigmóide."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-266404","number":"266404","sourceNumber":"266404","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente masculino, 55 anos, com história prévia de laparotomia mediana infraumbilical\nhá 20 anos devido à apendicite aguda. Deu\nentrada no pronto-socorro com quadro de parada de\neliminação de fezes há 4 dias, com eliminação de flatos presentes. Ao exame físico, foi observado\nabdome com hipertimpanismo discreto, sem sinais de irritação peritoneal ou herniações de parede\nabdominal. Radiografia de abdome mostra distensão leve de intestino delgado difusamente, sem\nníveis hidroaéreos ou pneumoperitônio. Foi optado por tomografia de abdome com contraste oral\nque evidenciou distensão discreta de alças de delgado, sem fatores obstrutivos ou perfurativos\nevidentes, sem sinais de sofrimento intestinal, com contraste chegando até o jejuno. Diante do\nquadro clínico, qual a principal hipótese diagnóstica?","options":{"A":"Suboclusão intestinal por aderências.","B":"Oclusão intestinal metabólica.","C":"Hérnia inguinal encarcerada.","D":"Apendicite aguda."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-246373","number":"246373","sourceNumber":"246373","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Homem de 76 anos, com dor abdominal em fossa ilíaca direita há 6 horas, deu entrada\nno pronto-socorro com vômitos e distensão\nabdominal. Exame físico com abaulamento, dor, calor e\nrubor em topografia inguinal. Exames laboratoriais: Hematócrito 40% / Hemoglobina 13,5mg/dl /\nLeuco 16200 (mielócitos 0%/ metamielócitos 0%/ bastões 8%/ segmentados 66%/ eosinófilos 1% /\nlinfócitos 22%/ monócitos 3%) Plaquetas: 280.000 mm³ / PCR 58. Radiografia simples de abdome\ncom níveis hidroaéreos. Diante da suspeita de hérnia estrangulada, qual a conduta mais resolutiva?","options":{"A":"Antibioticoterapia endovenosa","B":"Laparoscopia diagnóstica","C":"Abordagem pré-peritoneal aberta","D":"Laparotomia xifo-pubiana"},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-232149","number":"232149","sourceNumber":"232149","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Durante o plantão em pronto-soccorro, dá entrada um paciente, masculino, 72 anos,\nhistória de mal de Parkinson, constipação\ncrônica e início de quadro de dor abdominal difusa e mal\ndefinida, associada à distensão abdominal moderada, com parada de eliminação de fezes há\naproximadamente 5 dias. Durante o exame físico evidenciou-se a presença do sinal de Gersuny.\n\nDiante desse quadro apresentado, assinale a alternativa que melhor indica a principal hipótese\ndiagnóstica:","options":{"A":"Isquemia mesentérica.","B":"Constipação crônica refratária ao tratamento clínico.","C":"Diverticulite aguda complicada.","D":"Tumoração estenosante em cólon esquerdo.","E":"Obstrução intestinal por fecaloma."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-212974","number":"212974","sourceNumber":"212974","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 32 anos, feminina, submetida à gastroplastia redutora em Y de Roux\nvideolaparoscópica (by-pass) há 6 meses, apresenta dor em hipocôndrio esquerdo há cerca de 8\ndias, que piora após se alimentar, apresentando também náuseas mas relata que \"não consegue\nvomitar\". Nega disfagia. Relata piora da dor há 4 horas, sem febre ou icterícia, dando entrada no\nPS com PA 120/70 mmHg, corada, Hb 12,1 leucócitos totais 9700 sem desvio, satO2 de 98% em ar\nambiente. Foi realizada radiografia de abdome agudo evidenciando distensão de alças\nisoladamente em hipocôndrio esquerdo e aparente distensão do estômago excluso. Qual a principal\nhipótese diagnóstica?","options":{"A":"Litíase biliar.","B":"Hérnia de Petersen.","C":"Isquemia intestinal.","D":"Estenose da gastroenteroanastomose.","E":"Úlcera marginal na anastomose gastro-jejunal"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-220320","number":"220320","sourceNumber":"220320","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 55 anos é admitido no pronto-socorro onde você estava de plantão.\nApresentava dor abdominal em cólica, que teve\ninício há 24 horas. Associados à dor, apresenta\nvários episódios de vômitos e distensão abdominal. Na história pregressa, tem passado de cirurgia\npara uma esplenectomia devido à queda em escada ocorrida 10 anos atrás. Hipertenso, usa\ndiuréticos e captopril. Na radiografia de tórax, não se encontra nada de anormal e, na radiografia\nde\nabdome, apresenta distensão de alças e pilhas de moeda. Sobre o caso descrito, assinale a\nalternativa CORRETA:","options":{"A":"O quadro clínico sugere possível neoplasia de cólon direito.","B":"O tratamento inicial deve ser realizado com hidratação, sonda nasogástrica e prescrição de\nantibioticoterapia profilática.","C":"O toque retal deve ser dispensado para exame desse paciente.","D":"O mais provável diagnóstico seria uma possível brida."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-199506","number":"199506","sourceNumber":"199506","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Sobre as hérnias inguinais, assinale a alternativa CORRETA:","options":{"A":"Paciente com parede posterior preservada e anel inguinal interno dilatado seria uma\nclassificação de Nyhus 3A.","B":"Em paciente com uma classificação de Nyhus 3C, o tratamento seria pela técnica de McVay.","C":"Se um paciente com hérnia encarcerada é admitido, a cirurgia deve ser realizada em até 24\nhoras do início do quadro de dor.","D":"A hérnia de Amyand é aquela encontrada na linha semilunar."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-199521","number":"199521","sourceNumber":"199521","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 16 anos relata dor constante na região inguinal direita, associada a\nnáuseas nas últimas 12 horas. Foi operado há\n5 anos de uma apendicite aguda complicada. Ao\nexame físico, apresenta tumoração inguinal irredutível e distensão abdominal discreta. Não há\nirritação peritoneal. Nessas circunstâncias, a conduta ADEQUADA consiste em:","options":{"A":"Cirurgia.","B":"Tomografia computadorizada de abdômen.","C":"Sedação inicial com morfina seguida de tentativa de redução da tumoração.","D":"Repouso absoluto, sonda nasogástrica e hidratação com correção hidroeletrolítica."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-199594","number":"199594","sourceNumber":"199594","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A correção cirúrgica de hérnia inguinal é o procedimento cirúrgico mais comum da\ninfância. Na hérnia inguinal é CORRETO afirmar:","options":{"A":"A indicação operatória das hérnias inguinais é após os dois anos de idade, pois 70% das hérnias\nregridem após essa idade.","B":"O principal diagnóstico diferencial é com hidrocele, que pode ser feito pela técnica de\ntransluminação (positiva na hérnia e negativa na hidrocele).","C":"O risco de encarceramento é maior nos primeiros seis meses de vida e raramente ocorre após\noito anos de idade.","D":"A apresentação clínica é de inchaço na região inguinal, com eritema e dor à manipulação. Sinais\nde obstrução intestinal (vômitos e distensão)\nafasta o diagnóstico."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-199588","number":"199588","sourceNumber":"199588","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Contribuem para o íleo pós-operatório, exceto:","options":{"A":"Manipulação cirúrgica de alças intestinais no intra-operatório.","B":"Restrição ao leito.","C":"Tempo cirúrgico prolongado.","D":"Uso de anestésicos não narcóticos."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-188025","number":"188025","sourceNumber":"188025","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Mulher, 68 anos, é examinada no ambulatório por perda ponderal a esclarecer. Ela\nafirma que 6 meses atrás pesava 70,5 kg e que hoje pesa 47,7 kg. Ela atribui essa perda à\nimpossibilidade de comer por dor abdominal intensa e difusa após ingesta alimentar. Nega febre,\nnáuseas, vômitos ou constipação. Refere hipertensão controlada com uso regular de captopril.\n\nAfirma tabagismo (1 maço de cigarro por dia) e etilismo social. Ao exame físico, paciente\nemagrecida, anictérica, acianótica, hidratada e\ncorada. Exame cardiopulmonar sem alterações.\nAbdome escavado, sem cicatriz ou sopro epigástrio, indolor e sem massas palpáveis. Hemograma\ne exame de urina normais. As fezes são negativas para sangue oculto. Eletrocardiograma de 12\nderivações mostra ritmo sinusal normal. Quais são as hipóteses diagnósticas mais prováveis?","options":{"A":"Colecistopatia calculosa crônica agudizada e pancreatite.","B":"Angina mesentérica e síndrome da artéria mesentérica superior.","C":"Aneurisma de aorta torácica e aneurisma de artéria esplênica.","D":"Neoplasia de cólon transverso e neoplasia gástrica.","E":"Síndrome do intestino irritável e parasitose intestinal."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-187438","number":"187438","sourceNumber":"187438","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Dentre as patologias listadas abaixo, qual delas tem indicação cirúrgica ao diagnóstico?","options":{"A":"Hérnia umbilical.","B":"Hérnia inguinal.","C":"Criptorquidia.","D":"Hérnia epigástrica.","E":"Orelha de abano."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-174388","number":"174388","sourceNumber":"174388","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 47 anos submetido à correção de hérnia inguinal, sendo evidenciado\ndefeito na parede posterior e anel inguinal\ninterno dilatado deve ser classificado, segundo Nyhus,\ncomo:","options":{"A":"IVC.","B":"II.","C":"IIIA.","D":"IIIC.","E":"III B."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-187491","number":"187491","sourceNumber":"187491","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Sobre abdome agudo obstrutivo é CORRETO afirmar, exceto:","options":{"A":"A radiografia de abdome agudo (abdome em pé e deitado + cúpulas diafragmáticas) é\nconsiderado o exame de imagem inicial, podendo inclusive indicar o tratamento.","B":"Vômitos fecaloides indicam fatores obstrutivos proximais.","C":"Casos de obstrução de cólon em pacientes com a válvula ileocecal competente podem tornar-se\npotencialmente mais graves.","D":"Sinal de empilhamento de moedas e 02 ou mais níveis hidroaéreos são indicativos de obstrução.","E":"As etiologias mais comuns são: hérnias, aderências e neoplasias."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-172783","number":"172783","sourceNumber":"172783","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Sobre as hérnias de parede abdominal podemos afirmar, exceto:","options":{"A":"As hérnias inguinais diretas possuem saco herniário emergindo lateralmente aos vasos\nepigástricos inferiores e as hérnias diretas\npossuem saco herniário emergindo medialmente aos\nmesmos vasos.","B":"A hérnia inguinal direta isolada possui classificação do Nyhus III A.","C":"A hérnia inguinal indireta é o tipo de hérnia mais comum na mulher.","D":"A incidência de encarceramento das hérnias femorais é alta, logo, toda hérnia femoral deve ser\ntratada cirurgicamente."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-172796","number":"172796","sourceNumber":"172796","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Em relação a imagem abaixo podemos afirmar:","options":{"A":"Trata-se de um volvo de sigmoide.","B":"A colonoscopia está contra-indicada nesses casos.","C":"Trata-se de um tumor de reto obstrutivo.","D":"A tomografia é o melhor exame para elucidação do diagnóstico."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-149138","number":"149138","sourceNumber":"149138","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Assinale a alternativa que completa CORRETAMENTE a frase: ?Na classificação de\nNihus, a hernia inguinal que apresenta defeito na parede posterior e está localizada lateralmente\naos vasos epigástricos inferiores é do tipo...?:","options":{"A":"IVB","B":"IIIB","C":"IIA","D":"IIIA","E":"IIIC"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-162567","number":"162567","sourceNumber":"162567","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Jesuíno, portador de hérnia inguinal direta à esquerda, apresenta-se ao pronto-socorro\ncom 4 horas de encarceramento. Qual síndrome\nabdominal pode se desenvolver caso não seja\nreduzido o conteúdo herniário?","options":{"A":"Abdome agudo hemorrágico.","B":"Abdome agudo traumático.","C":"Abdome agudo inflamatório.","D":"Abdome agudo isquêmico.","E":"Síndrome compartimental abdominal."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-155481","number":"155481","sourceNumber":"155481","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Quando indicado, qual o tratamento cirúrgico de escolha para pacientes portadores de\nSíndrome de Wilkie?","options":{"A":"Duodenopancreatectomia.","B":"Duodenojejunostomia.","C":"Gastroenteroanastomose.","D":"Duodeno-transversoanastomose.","E":"Duodenostomia."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-162579","number":"162579","sourceNumber":"162579","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"O reparo laparoscópico das hérnias inguinais é um método de reparo livre de tensão\nbaseado na abordagem pré-peritoneal. Durante a abordagem laparoscópica de uma hérnia\ninguinal, o nervo com maior risco de ser lesado é o:","options":{"A":"Gênito-femoral em seu ramo genital.","B":"Ileoinguinal.","C":"Íleo-hipogástrico.","D":"Cutâneo femoral lateral.","E":"Femoral."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-148542","number":"148542","sourceNumber":"148542","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente, 45 anos, homem, procura ambulatório com queixas de dor e pequeno\nabaulamento redutível em região de quadrante inferior esquerdo, próximo a borda lateral do\nmúsculo reto abdominal e sua linha semilunar. Seu provável diagnóstico é:","options":{"A":"Hérnia de Littre.","B":"Hérnia de Spiegel.","C":"Hérnia de Boudalec.","D":"Hérnia de Petit.","E":"Hérnia de Grynfelt."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-126908","number":"126908","sourceNumber":"126908","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A principal causa de abdômen agudo obstrutivo é:","options":{"A":"A intussuscepção.","B":"A aderência.","C":"O adenocarcinoma de cólon.","D":"O íleo paralítico."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-127173","number":"127173","sourceNumber":"127173","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A intussuscepção intestinal ocorre quando uma parte do trato digestivo se introduz\n(invagina) em um segmento adjacente. Nestes casos é CORRETO afirmar que:","options":{"A":"A presença de muco sanguinolento no exame retal descarta o diagnóstico de intussuscepção.","B":"É uma emergência abdominal que raramente ocorre em lactentes, sendo mais comum em\nmaiores de seis anos.","C":"O ultrassom não tem indicação na intussuscepção intestinal, pois a sensibilidade é menor que\n10%.","D":"Ocorre principalmente de forma insidiosa, em crianças com mais de seis anos de idade e após\nhistória prolongada de diarreia.","E":"Nos casos típicos, ocorre com início súbito, em crianças previamente hígidas, com dor intensa\nparoxística em cólicas que recorre em intervalos frequentes."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-100974","number":"100974","sourceNumber":"100974","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Criança de 10 meses de idade é atendida devido a choro intenso nas últimas seis\nhoras, vômitos, distensão abdominal e eliminação\nde muco e sangue pelo ânus, sem febre. Qual o\nprovável diagnóstico?","options":{"A":"Alergia à proteína do leite de vaca.","B":"Doença inflamatória do intestino.","C":"Divertículo de Meckel.","D":"Invaginação intestinal.","E":"Fissura anal."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-111641","number":"111641","sourceNumber":"111641","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente apresenta quadro agudo de dor abdominal em cólica acompanhada de\ndistensão do abdome, vômitos e parada de\neliminação de gases. A radiografia simples de abdome\nmostra níveis hidroaéreos e pneumobilia. O diagnóstico provável é:","options":{"A":"síndrome de Mirizzi","B":"íleo biliar","C":"síndrome de Bouveret","D":"colangite supurativa","E":"Síndrome de Raynald"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-87451","number":"87451","sourceNumber":"87451","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Homem, 65 anos, queixa-se de dor abdominal há 3 dias, associada a vômitos, parada\nde eliminação de gases e fezes, e distensão\nabdominal. Comorbidades: Hipertensão arterial e\ndislipidemia. Relata cirurgia abdominal prévia por trauma. Exame físico: REG, eupneico, afebril.\n\nAbdome distendido, ruídos hidroaéreos diminuídos, doloroso à palpação difusa, sem herniações.\nRaio X de abdome: distensão de alças de\nintestino delgado com níveis hidroaéreos. Qual a\nprovável causa do abdome obstrutivo no caso descrito?","options":{"A":"Fecaloma.","B":"Intussuscepção.","C":"Aderências/bridas.","D":"CA intestinal.","E":"Volvo de sigmoide."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-87457","number":"87457","sourceNumber":"87457","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Homem, 65 anos, queixa-se de dor abdominal há 3 dias, associada a vômitos, parada\nde eliminação de gases e fezes, e distensão\nabdominal. Comorbidades: Hipertensão arterial e\ndislipidemia. Relata cirurgia abdominal prévia por trauma, Exame físico: REG, eupneico, afebril.\n\nAbdome distendido, ruídos hidroaéreos diminuídos, doloroso à palpação difusa, sem herniações.\nRaio X de abdome: distensão de alças de\nintestino delgado com níveis hidroaéreos. Qual o\ntratamento inicial mais adequado para esse quadro clínico?","options":{"A":"Hidratação venosa e sondagem nasogástica.","B":"Desimpactação manual.","C":"Retossigmoidoscopia com colocação de sonda de Fouchet.","D":"Laparotomia exploradora imediata.","E":"Jejum e enema de retenção."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-77560","number":"77560","sourceNumber":"77560","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"O conhecimento anatômico detalhado da região inguinal é essencial para o tratamento\noperatório das hérnias inguinais. Dentre as estruturas abaixo, assinale a que não faz parte do\nfunículo espermático:","options":{"A":"Ducto deferente.","B":"Artéria epigástrica inferior.","C":"Ramo genital do nervo genitofemoral.","D":"Nervos autônomos do testículo.","E":"Plexo pampiniforme."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-59055","number":"59055","sourceNumber":"59055","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"O trígono de Hesselbach é formado por:","options":{"A":"Bainha do reto, ligamento inguinal e vasos femorais.","B":"Vasos epigástricos, tendão conjunto e ligamento de Cooper.","C":"Vasos epigástricos, bainha do reto abdominal e ligamento inguinal.","D":"Vasos epigástricos, vasos femorais e ligamento inguinal.","E":"Ligamento inguinal, espinha ilíaca anterossuperior e bainha do reto."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-43951","number":"43951","sourceNumber":"43951","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 24 anos apresenta dor em região inguinal e bolsa escrotal que vem\naumentando de volume nas últimas semanas;\nrelata que após acordar, o volume da bolsa escrotal\nestá quase normal. O provável diagnóstico é:","options":{"A":"Hidrocele.","B":"Cisto de cordão.","C":"Varicocele.","D":"Epididimite.","E":"Hérnia inguinal."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-43971","number":"43971","sourceNumber":"43971","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Lactente de seis meses chega ao ambulatório para consulta de rotina, chorando muito.\nO médico percebe um choro intenso,\n''diferente'' e adianta a entrada da criança na sala. A mãe\ninforma que a criança estava bem, mas que há cerca de quatro horas não para de chorar. Todos os\ndias, a criança apresenta choro ao final do dia; eliminações presentes; está com aleitamento\nmaterno exclusivo, regurgita após cada mamada, sem alterações na gestação e parto. Ao exame,\nabdômen muito distendido, difícil palpação pelo choro intenso; aumento de volume em região\ninguinal-escrotal à direita, sem sinais flogísticos. Sem outras alterações ao exame físico. Qual\npossível diagnóstico?","options":{"A":"Hérnia inguinal encarcerada.","B":"Cólicas do lactente.","C":"Hidrocele.","D":"Obstrução intestinal.","E":"Intussuscepção intestinal."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-23109","number":"23109","sourceNumber":"23109","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"LAPA, 62anos, com hérnia inguinal direita encarcerada, foi submetido à inguinotomia\ncom constatação de divertículo de Meckel\nestrangulado com necrose de alça segmentar. Assinale a\nalternativa correta:","options":{"A":"Trata-se de hérnia de Littré. Deve ser realizada ressecção segmentar de segmento acometido +\nanastomose primária pela própria inguinotomia + correção da hérnia inguinal.","B":"Trata-se de hérnia de Littré. Deve ser realizada ressecção segmentar do divertículo +\nanastomose primária por laparotomia mediana + correção da hérnia inguinal.","C":"Trata-se de hérnia de Littré. Deve ser realizada ressecção segmentar do segmento acometido +\nileostomia de proteção + correção da hérnia inguinal.","D":"Trata-se de hérnia de Littré. Deve ser realizada ressecção do íleo terminal e cólon dierito +\ncorreção da hérnia inguinal.","E":"Trata-se de hérnia de Littré. Deve-se realizar apenas o tratamento do divertículo, sem\nabordagem da hérnia inguinal."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-23111","number":"23111","sourceNumber":"23111","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"As obstruções intestinais podem ser classificadas como altas ou baixas. Quanto às\nobstruções intestinais altas, marque a alternativa incorreta.","options":{"A":"Distensão abdominal geralmente não está presente","B":"Apresenta vômitos intensos","C":"Pode apresentar ondas peristálticas visíveis na parede abdominal que é conhecida como Sinal\nde Kusmaul","D":"A radiografia de abdome em ortostase e em decúbito dorsal é capaz de diferenciar a obstrução\nintestinal alta da obstrução intestinal baixa","E":"Quanto mais alta for a obstrução, maior a possibilidade de o paciente apresentar acidose\nmetabólica à gasometria arterial"},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-8067","number":"8067","sourceNumber":"8067","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um menino de 03 anos é levado ao pronto-socorro do HUCAM por sua mãe, com um\nquadro de retenção urinária aguda de 6 horas de duração. Tem abdômen doloroso a palpação. O\nsinal vésico-peniano é evidente. Qual é o provável diagnóstico?","options":{"A":"Infecção urinária aguda.","B":"Trauma gênito-urinário.","C":"Cálculo vesical.","D":"Orquite.","E":"Fimose."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-8075","number":"8075","sourceNumber":"8075","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Homem com 72 anos, dor abdominal em cólica há 24 horas. Parada de eliminação de\ngases e fezes, negando enjôo ou vômitos.\nAo exame clínico distensão abdominal, timpanismo, com\nausência de descompressão dolorosa e ruídos peristálticos aumentados.Toque retal descrito como\nsem anormalidades. Recebendo este paciente no pronto-socorro, qual procedimento solicitaria para\nconfirmar o diagnóstico?","options":{"A":"Colonoscopia virtual.","B":"Tomografia abdominal.","C":"Enema (clister) Opaco.","D":"Radiografia simples de abdome.","E":"Videocolonoscopia."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-8076","number":"8076","sourceNumber":"8076","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente do caso anterior foi submetido a laparotomia e devido as condições locais\nfavoráveis, foi submetido a ressecção do seguimento de cólon esquerdo acometido pelo tumor e\nfeita anastomose primária sem ileostomia descompressiva. No 5°dia do pós-operatório apresentou\nsaída da secreção escura no dreno que foi mobilizado anteriormente, sem alterações nos\nparâmetros clínicos. Qual o diagnóstico mais provável?","options":{"A":"Secreção geralmente presente, sempre com utilização de drenos intraperitoniais.","B":"Secreção esperada neste tipo de cirurgia pela contaminação operatória.","C":"Deiscência parcial da anastomose com fistula.","D":"Presença de corpo estranho.","E":"Fístula provocada pelo tempo prolongado no contato do dreno tubular com parede da alça\nintestinal."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-355631","number":"355631","sourceNumber":"355631","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente feminina, 44 anos, deu entrada no pronto socorro com história de vômitos\nrecorrentes, distensão abdominal acompanhada\nde dor difusa há três dias. Nega comorbidades e\ntem antecedente cirúrgico de duas cesáreas. Ao exame físico, pulso 120 bpm, pressão arterial 130\nmmHg × 90 mmHg, abdome distendido, hipertimpânico, descompressão brusca positiva. Realizou\nRaio X de abdome agudo que mostrou empilhamento de moedas e níveis. Analise as afirmativas\nabaixo e dê valores Verdadeiro (V) ou Falso (F): ( ) A primeira hipótese diagnóstica é abdome\nagudo obstrutivo por brida. ( ) A primeira hipótese diagnóstica é tumor obstrutivo de cólon. ( ) O\npróximo exame imaginológico que pode ser realizado para elucidação do caso é tomografia\ncomputadorizada de abdome total com contraste venoso e oral. ( ) Não se deve realizar nenhum\noutro exame de imagem e, sim, indicar laparotomia exploradora. ( ) Deve-se tentar tratamento\nclínico nesta paciente a princípio. Assinale a alternativa que apresenta a sequência correta de cima\npara baixo:","options":{"A":"V, F, F, V, V","B":"V. F, V, F, V","C":"F, V, V, F, V","D":"F, V, V, F, F","E":"F, V, F, F, F"},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-355633","number":"355633","sourceNumber":"355633","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A hérnia que se projeta através de um defeito no ligamento lacunar é conhecida como\nhérnia de:","options":{"A":"Cloquet","B":"Laugier","C":"Velpeau","D":"Hesselbach","E":"Partridge"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-355634","number":"355634","sourceNumber":"355634","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A hérnia inguinal é uma das doenças mais frequentes para cirurgia geral. Sua correção\nse baseia na correção do defeito anatômico,\ncongênito ou adquirido, que permitiu a passagem das\nvísceras abdominais através da parede abdominal. O substrato anatomopatológico para a hérnias\ninguinais indiretas é:","options":{"A":"passagem das vísceras pelo anel crural","B":"passagem das vísceras pelo anel femoral","C":"passagem das vísceras pelo Triângulo de Hesselbach","D":"passagem das vísceras abominais pelo conduto peritonio vaginal patente através do canal\ninguinal","E":"passagem das vísceras abdominais pelo anel umbilical por um defeito de fechamento da cicatriz\numbilical"},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-353829","number":"353829","sourceNumber":"353829","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A obstrução intestinal é definida como a dificuldade da passagem de gases, líquidos e\npastosos através do lúmen intestinal. Sobre a obstrução intestinal na pediatria, é CORRETO\nafirmar:","options":{"A":"No lactente, a causa mais rara de obstrução intestinal é a invaginação intestinal.","B":"A obstrução intestinal é o diagnóstico cirúrgico menos comum nas unidades de terapia intensiva\nneonatais.","C":"No Recém-Nascido (RN), as principais causas de obstrução intestinal são atresias intestinais,\nmá rotação, íleo meconial, Doença de Hirschsprung\n(DH) e má-formação anorretal.","D":"No lactente, a principal causa de obstrução intestinal é a má-formação anorretal."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-362649","number":"362649","sourceNumber":"362649","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Sobre obre as situações de ingestão de corpo estranho em que a EDA é\ncontraindicada, assinale a alternativa correta.","options":{"A":"Presença de vômitos.","B":"Última refeição a menos de 2h.","C":"Sinais de complicação como pneumoperitoneo.","D":"Presença de sialorreia."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-362671","number":"362671","sourceNumber":"362671","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Qual é a conduta indicada nos casos em que a moeda ingerida ultrapassa o estômago?","options":{"A":"A remoção deve ser realizada em até 2 semanas.","B":"Deve-se aguardar a eliminação espontânea na primeira semana após a ingestão.","C":"A conduta é expectante, de modo que a remoção será realizada caso o paciente apresente\nsintomas obstrutivos ou não haja eliminação em quatro semanas.","D":"Deve-se remover o objeto imediatamente."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-353856","number":"353856","sourceNumber":"353856","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Sobre o Abdome Agudo Obstrutivo, é CORRETO afirmar:","options":{"A":"É uma condição inflamatória/infecciosa gastrointestinal que vai precisar de conduta imediata,\npodendo ser cirúrgica ou não e destacando-se\ncomo a causa mais comum de dor abdominal aguda\nnos serviços de emergência.","B":"Achados possíveis na radiografia: distensão de alças intestinais, nível líquido dentro de alças\n(próximas à obstrução), alças ?carecas?, pneumoperitônio, líquido livre na cavidade, fecaloma,\nvolvo de sigmoide, empilhamento de moeda.","C":"Causas mais comuns: rotura apendicular e diverticular gerando a obstrução, Síndrome de\nCrohn, úlceras pépticas perfuradas.","D":"É mais frequentemente causado por impactação de corpos estranhos, lesões vasculares\nabdominais e hérnia inguinal."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-353798","number":"353798","sourceNumber":"353798","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Em um caso clínico, um homem de 45 anos chega ao pronto-socorro com queixas de\ndor e desconforto na região inguinal. Após\navaliação médica e realização de exames de imagem, é\ndiagnosticada uma hérnia inguinal redutível. O paciente relata que a dor é moderada e que não há\nsinais de estrangulamento ou encarceramento da hérnia. Diante deste cenário, a conduta médica\nmais adequada é:","options":{"A":"Administrar analgesia e liberar o paciente, pois a hérnia redutível não requer qualquer\nintervenção cirúrgica.","B":"Administrar analgesia para alívio da dor e encaminhar o paciente para correção cirúrgica\neletiva.","C":"Encaminhar o paciente imediatamente para cirurgia de emergência, visto que todas as hérnias\nsão casos urgentes.","D":"Redução da hérnia e encaminhamento do paciente à cirurgia imediata."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-354758","number":"354758","sourceNumber":"354758","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"De acordo com a classificação de Nyhus para hérnia da virilha, como se classifica um\npaciente com recidiva de quadro de hérnia com anel inguinal interno dilatado, parede inguinal\nposterior intacta e vasos epigástricos profundos inferiores não deslocados?","options":{"A":"Tipo IV A","B":"Tipo IV B","C":"Tipo IV C","D":"Tipo IV D"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-354769","number":"354769","sourceNumber":"354769","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Sobre a hérnia de Spiegel, sabe-se que","options":{"A":"é mais comum na infância.","B":"ocorre abaixo da linha arqueada.","C":"apresenta-se com grande volume.","D":"tem alto índice de recidiva."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-342603","number":"342603","sourceNumber":"342603","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Sobre as hérnias de parede abdominal, é correto afirmar que:","options":{"A":"os pacientes com hérnia epigástrica podem apresentar dor desproporcional ao tamanho da\nhérnia, devido ao encarceramento de gordura\npré-peritoneal, sendo essas hérnias múltiplas em até\n20% dos pacientes","B":"as hérnias umbilicais nos adultos são, na maioria das vezes, adquiridas, mais frequentemente\nem pacientes com condições que possam aumentar a\npressão intra-abdominal, devendo ser\nsubmetidas a tratamento cirúrgico sempre que diagnosticadas, pelo elevado risco de\nestrangulamento","C":"as hérnias incisionais ocorrem como resultado do excesso de tensão e cicatrização inadequada\nde uma incisão previa, podendo estar\nassociadas a infecção de sítio cirúrgico. O tratamento\ncirúrgico preferencial consiste em reparo primário sem tela, já que a prótese não diminui a taxa de\nrecidiva","D":"as hérnias inguinais indiretas assintomáticas devem ser tratadas de forma conservadora, devido\nao baixo potencial de encarceramento e\nestrangulamento"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-342607","number":"342607","sourceNumber":"342607","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"As aderências são a causa mais comum de obstrução do intestino delgado em países\nindustrializados. A 2a causa mais comum é(são):","options":{"A":"neoplasias","B":"hérnias","C":"doença de Crohn","D":"infecções"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-337420","number":"337420","sourceNumber":"337420","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A artéria mesentérica superior tem origem na aorta abdominal. Emite ramos arteriais\npara todo o delgado e a metade proximal do\ncólon. Seus ramos principais são, exceto:","options":{"A":"Ramos jejunoileais.","B":"Ileocólica e apendicular.","C":"Cólica direita.","D":"Cólica esquerda."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-330100","number":"330100","sourceNumber":"330100","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Sobre o abdome agudo obstrutivo, é CORRETO afirmar:","options":{"A":"Nos casos de hérnias da região inguinal, pode-se realizar a inguinotomia com avaliação da\nviabilidade de alças e da necessidade de laparotomia.","B":"Em situações de perfuração, peritonite e necrose de alça, os índices de mortalidade são baixos\ne geralmente se restringem aos mais idosos.","C":"No exame físico, os ruídos hidroaéreos de timbre metálico não indicam obstáculo mecânico ao\ntrânsito intestinal.","D":"Na obstrução alta ocorrem alcalose metabólica hipocalêmica e hipoclorêmica, e, na obstrução\nbaixa, é mais comum haver acidose\nmetabólica."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-334138","number":"334138","sourceNumber":"334138","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 14 anos, feminina, queixando-se de episódios de vômitos de conteúdo\nbiliar de início há aproximadamente há 5\nmeses. Nega febre. Nega diarreia. Relata piora dos\nvômitos em momentos pós-prandiais, quando se associa dor epigástrica intensa. Associa neste\nmesmo período perda ponderal importante, pois está realizando dieta hipocalórica acompanhada\npor nutricionista devido a obesidade. Internado para investigação levemente desidratada, corada,\nanictérica, afebril. Sem alterações ao exame físico. Exames laboratoriais revelam hipocalemia leve\n(K: 3,1 mEg/L). Realizadas radiografias de abdome com distenção gástrica inespecífica,\nendoscopia digestiva alta com gastrite enantemática leve, teste da urease negativo. Submeteu-se a\ntomografia de abdome que evidenciou distensão da terceira parte duodenal com ângulo\n\naorto-mesentérico reduzido (13°). Qual o provável diagnóstico?","options":{"A":"Síndrome de Wilkie","B":"Estenose hipertrófica de piloro","C":"Gastrite alcalina","D":"Aneurisma de aorta"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-346449","number":"346449","sourceNumber":"346449","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Homem de 40 anos, foi submetido a colectomia esquerda à Hartmann, devido a tumor\nde cólon obstrutivo. Durante a cirurgia,\nobservou-se edema e dilatação de todo o intestino delgado\ne do cólon. No 2° dia de pós-operatório, o paciente está em regular estado geral, eupneico, afebril,\npermanece com distensão abdominal e alto débito de líquido bilioso pela sonda nasogástrica,\neliminação de secreção sero hemática em baixa quantidade pela colostomia. A radiografia simples\nde abdome mostra distensão de intestino delgado e cólon. Das possibilidades abaixo, o diagnóstico\nmais provável seria:","options":{"A":"Obstrução intestinal por bridas;","B":"Íleo paralítico;","C":"Obstrução intestinal por hérnia interna;","D":"Obstrução da colostomia."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-337433","number":"337433","sourceNumber":"337433","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A artéria mesentérica inferior tem sua origem na aorta abdominal e emite ramos para a\nmetade distal do cólon e reto. Os principais ramos são, exceto:","options":{"A":"Cólica esquerda.","B":"Cólica direita.","C":"Sigmoideas.","D":"Retal superior."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-334140","number":"334140","sourceNumber":"334140","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A tríade de Rigler consiste em:","options":{"A":"Hemobilia, hematêmese e icterícia.","B":"Aerobilia, cálculo biliar ectópico, sinais de obstrução intestinal.","C":"Icterícia, febre e dor abdominal.","D":"Pneumobilia, cálculo impactado no infundíbulo e paredes delaminadas."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-337434","number":"337434","sourceNumber":"337434","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"As artérias mesentéricas superior e inferior possuem ampla rede anastomótica que\npermite fluxo de sangue entre a circulação mesentérica. Assinale a alternativa correta.","options":{"A":"A artéria de Riolan conecta o ramo esquerdo da artéria cólica média a artéria cólica esquerda.","B":"Ponto de Griffith: é o ponto mais distal da artéria retal superior, que corresponde à área de\nirrigação arterial da junção retossigmoide.","C":"Ponto de Sudeck: é justamente o ponto do cólon que corresponde à junção dos territórios das\nartérias mesentérica superior e inferior, ao nível do ângulo esplênico. Em tese é o ponto menos\nvascularizado do cólon.","D":"O arco de Riolan compreende a rede anastomótica entre as artérias cólica direita, cólica média e\ncólica esquerda."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-334141","number":"334141","sourceNumber":"334141","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente 65 anos, etilista, procura pronto socorro com quadro de dor abdominal em\ncólicas, de início há 4 dias, progressiva\ne com piora há 1 dia, associada a vômitos, distensão\nabdominal, e parada de eliminação de flatos. Nega febre. Ao exame físico, apresentava-se em\nregular estado geral, desidratado, corado, anictérico, afebril. Sem alterações no aparelho\ncardiopulmonar, com ruídos hidroaéros reduzidos em todo abdome, levemente distendido, sem\nsinais de peritonite, porém com dor a palpação difusa. Sinal de Murphy negativo. Após medicado, o\nplantonista solicita radiografia de abdome agudo que evidencia níveis hidroaéreos em todo intestino\ndelgado com aspecto de \"empilhamento de moedas\", presença de ar na via biliar, associado a\nimagem radiopaca em íleo terminal. Baseado no caso acima, o provável diagnóstico é:","options":{"A":"Obstrução Intestinal por neoplasia de cólon.","B":"Obstrução Intestinal por doença diverticular complicada.","C":"Úlcera gástrica perfurada bloqueada.","D":"Íleo Biliar."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-334146","number":"334146","sourceNumber":"334146","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Mulher de 65 anos chega ao pronto socorro queixando-se de dor e distensão abdominal\nimportante, associada a vômitos e sudorese fria. Relata ser constipada crônica, e que sua\nfrequência evacuatória é de 1 evacuação a cada 10 dias. Ao exame físico, regular estado geral,\ndesidratada, dispneica, taquicárdica, sudoreica, com distensão abdominal importante, ruídos aéreos\naumentados e metálicos, com dor à palpação difusa, sem sinais de peritonite. Segue radiografia de\nadbome. A principal hipótese diagnóstica é:","options":{"A":"Apendicite aguda perfurada e bloqueada.","B":"Volvo de sigmóide.","C":"Colite pseudomembranosa.","D":"Íleo metabólico."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-334147","number":"334147","sourceNumber":"334147","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Mulher de 65 anos chega ao pronto socorro queixando-se de dor e distensão abdominal\nimportante, associada a vômitos e sudorese fria. Relata ser constipada crônica, e que sua\nfrequência evacuatória é de 1 evacuação a cada 10 dias. Ao exame físico, regular estado geral,\ndesidratada, dispneica, taquicárdica, sudoreica, com distensão abdominal importante, ruídos aéreos\naumentados e metálicos, com dor à palpação difusa, sem sinais de peritonite. Segue radiografia de\nadbome. Baseado no seu diagnóstico acima. Qual a conduta imediata?","options":{"A":"Laparotomia exploradora.","B":"Antibioticoterapia.","C":"Colonoscopia descompressiva.","D":"Hemicolectomia direita."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-330113","number":"330113","sourceNumber":"330113","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Acerca das hérnias de parede abdominal, é CORRETO afirmar:","options":{"A":"As hérnias femorais são mais comuns em mulheres do que em homens e 90% são unilaterais, à\ndireita.","B":"Nas hérnias lombares, as mais frequentes são as localizadas no triângulo lombar inferior.","C":"O saco herniário da hérnia inguinal direta é lateral ao anel inguinal interno e aos vasos\nepigástricos inferiores.","D":"A hérnia incisional caracteriza-se pela projeção do saco herniário através da linha semilunar ou\npararretal externa."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-311886","number":"311886","sourceNumber":"311886","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A palavra hérnia vem do latim e significa ruptura. É definida como a protusão anormal\nde um órgão ou tecido por um defeito nas\nparedes que o circundam. Em relação às hérnias\ninguinais, é correto afirmar que:","options":{"A":"são incomuns e perfazem menos de 20% do total de hérnias.","B":"a incidência de hérnias inguinais é igual entre homens e mulheres.","C":"a hérnia mais comum é aquela cujo saco herniário é lateral aos vasos epigástricos inferiores.","D":"o triângulo de Hasselbach é o local por onde ocorre a maior parte das hérnias inguinais\nindiretas."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-314094","number":"314094","sourceNumber":"314094","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Qual a estrutura anatômica determinante na diferenciação entre as hérnias inguinais\ndireta e indireta?","options":{"A":"Ligamento de Cooper.","B":"Ligamento inguinal.","C":"Vasos epigástricos inferiores.","D":"Fáscia transversalis."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-313181","number":"313181","sourceNumber":"313181","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Com relação às hérnias inguinocrurais, assinale a alternativa correta:","options":{"A":"a cirurgia para correção de hérnia inguinal é considerada contaminada e é indicação de\nantibioticoterapia por pelo menos 7 dias","B":"a hérnia inguinal direta, classificada como IIIA por Nyhus, é mais comumente encontrada nos\npacientes jovens e é decorrente da persistência do conduto peritoneovaginal","C":"na técnica de Liechtenstein, o arco aponeurótico do músculo transverso é suturado ao ligamento\ninguinal","D":"as hérnias crurais são mais comuns nas mulheres devido à conformação da bacia que leva a um\nanel crural maior em relação aos homens"},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-317924","number":"317924","sourceNumber":"317924","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"O trato íleo-púbico compõe a anatomia da região inguinal. Fazem parte da sua\nestrutura fibras do músculo","options":{"A":"oblíquo externo.","B":"oblíquo interno.","C":"transverso.","D":"reto abdominal."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-316300","number":"316300","sourceNumber":"316300","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Algumas hérnias têm nomes específicos em função do conteúdo do saco herniário ou\nda localização do defeito causador. Assinale a\nalternativa que apresenta uma em que não haja\ncorrespondência:","options":{"A":"Hérnia de Littré - divertículo de Meckel.","B":"Hérnia de Amyand - apêndice cecal junto a hérnia inguinal.","C":"Hérnia de Spiegel - linha semilunar.","D":"Hérnia de Grynfelt - triângulo lombar inferior."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-294253","number":"294253","sourceNumber":"294253","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Qual é a complicação mais frequente da correção cirúrgica da hérnia inguinal pela\ntécnica de Lichtenstein?","options":{"A":"Dor crônica.","B":"Infecção de ferida operatória.","C":"Orquite isquêmica.","D":"Impotência sexual."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-317147","number":"317147","sourceNumber":"317147","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Em relação as hérnias inguino femorais são afirmativas incorretas, exceto:","options":{"A":"Os limites do anel femoral são o ligamento pectíneo, ligamento lacunar e vasos epigástricos\ninferiores.","B":"A corona mortis é uma comunicação entre ramos da artéria ilíaca interna e externa e localiza-se\nno ramo superior do púbis.","C":"Hérnia inguinal direta origina-se cranialmente aos vasos epigástricos inferiores.","D":"Hernia inguinal infantil por persistência do conduto peritônio vaginal apresenta-se diretamente\npelo trígono de Hesselbach."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-317148","number":"317148","sourceNumber":"317148","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"São afirmativas corretas sobre as hérnias da parede abdominal, exceto:","options":{"A":"A criptorquidia é um diagnóstico diferencial comum na infância.","B":"Hérnias femorais tem maior risco de encarceramento.","C":"Pacientes com baixo peso ao nascer tem maior risco de desenvolver hérnias.","D":"A hérnia de Amyand é caracterizada pela protrusão, com encarceramento ou estrangulamento,\nda borda anti mesentérica intestinal por meio de\num pequeno defeito da parede abdominal."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-317149","number":"317149","sourceNumber":"317149","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Em relação a ocorrência de hérnia inguinal em pacientes do sexo feminino é incorreto\nafirmar, exceto:","options":{"A":"Os vasos epigástricos inferiores fazem uma alça inferiormente ao ligamento redondo na região\ninguinal em pacientes do sexo feminino.","B":"Em pacientes do sexo feminino as hérnias mais comuns são as hérnias femorais.","C":"As hérnias inguinais indiretas exteriorizam-se diretamente através do trígono de Hasselbach.","D":"O ramo genital do nervo genitofemoral em pacientes do sexo feminino acompanha o trajeto dos\nvasos pudendos internos."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-317934","number":"317934","sourceNumber":"317934","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 60 anos, procedente de zona rural, com constipação crônica, comparece\nao pronto-socorro com dor e distensão abdominal,\nparada da eliminação de fezes e flatos há 12\nhoras. Ao exame físico, observa-se emagrecimento e assimetria do abdome com mais distensão à\nesquerda, com hipertimpanismo e visualização de movimentos que sugerem contratilidade de alça\ncolônica e dedo de luva limpo ao toque. A melhor hipótese diagnóstica para esse paciente é:","options":{"A":"fecaloma por colopatia chagásica.","B":"volvo de sigmoide por colopatia chagásica.","C":"isquemia mesentérica.","D":"diverticulite aguda."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-308227","number":"308227","sourceNumber":"308227","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 50 anos, sexo feminino, deu entrada no Pronto Socorro com dor abdominal\nintensa, acompanhada de náuseas e vômitos, após atividade física em academia. Ao exame físico:\nregular estado geral, sobrepeso, hipocorada + em 4+ com dor intensa em abdome a esquerda e\nmassa abdominal palpável em hemiabdome a esquerda de aprox. 3.5cm. Refere parada de\neliminação de gases e fezes e foi submetida a tomografia de abdome com achado de aglomerado\nde alças de delgado e omento entre linha semilunar e reto abdominal. Trata-se, portanto de:","options":{"A":"Hérnia inguinal encarcerada e seria indicado tratamento cirúrgico.","B":"Diverticulite com abscesso e iniciar antibiótico.","C":"Hérnia de Spencer e proceder a correção cirúrgica laparoscópica.","D":"Hérnia de Spiegel."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-315799","number":"315799","sourceNumber":"315799","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 46 anos procura atendimento médico devido ao aparecimento de\nnodulação em dorso, a direita, de\nsurgimento há aproximadamente 1 ano, inicialmente menor e\nindolor, mas notou aumento de tamanho nas últimas semanas, bem como piora da dor local. Nega\ntrauma. Nega febre. Nega sintomas urinários. Relata que o nódulo vem aumentando de tamanho,\nprincipalmente quando pratica esportes, mas que em alguns dias desaparece. Nega sintomas\ngastrointestinais. Ao exame físico, nota-se a nodulação em dorso, a direita, de aproximadamente 4\ncm, mole, depressível, mas não redutível, indolor, na topografia logo acima da crista ilíaca,\nadjacente os limites do m. oblíquo externo e do m. grande dorsal, sem sinais flogísticos associados.\nPara melhor investigação realizado a tomografia abaixo. A principal hipótese diagnóstica é:","options":{"A":"Linfonodomegalia.","B":"Hérnia de Petit.","C":"Ureterolitíase.","D":"Hérnia de Grynfelt."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-315800","number":"315800","sourceNumber":"315800","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A figura abaixo representa a região inguinal direita, com seus elementos em uma face\ninterna. Sobre as hérnias inguinais dest região, assinale a correta.","options":{"A":"As hérnias femorais são mais comuns na região representada pela letra \"\"B\"\", adjacente ao anel\ninguinal interno.","B":"As hérnias inguinais diretas são apresentadas na topografia da região representada pela letra\n\"\"B\"\", visto que passam pelo canal espermático junto com as outras estruturas deste canal.","C":"As hérnias inguinais indiretas são apresentadas na topografia da região representada pela letra\n\n?A?, visto que se localizam na região de fraqueza da parede posterior do abdome.","D":"As hérnias inguinais indiretas, muito comum na infância, geralmente se apresentam lateralmente\naos vasos epigástricos inferiores, situadas na\nregião representada pela letra \"\"B\"\"."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-300840","number":"300840","sourceNumber":"300840","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente, sexo feminino, 57 anos, apresenta dor abdominal e vômito de aspecto bilioso\nnos intervalos das refeições há 2 dias. Relata que não eliminou flatos e fezes nesse período. Há\ncomorbidade clínica de hipotireoidismo controlado com medicação e histórico de laparotomia\nprévia. Desidratada (+/4+), corada, afebril, murmúrio vesicular positivo bilateral; FC = 104 bpm;\nPA\n\n= 117 x 84 mmHg; abdome distendido, hipertimpânico, com ruídos hidroaéreos aumentados, doloso\nà palpação difusa, sem sinais de peritonite. Sem\nhérnias e sem fezes na ampola retal. Seus\nexames de admissão são: Hb = 14,7; Ht = 43,1; leucócitos = 13.700, com 5% de bastonetes;\nplaquetas 220.000; U = 60; Cr = 1,5; Na = 140; K = 2,9; amilase = 45. Raio-X evidencia distensão\nde delgado sem ar no cólon. Considerando as informações do enunciado, a hipótese diagnóstica\nsindrômica e etiológica mais provável é:","options":{"A":"Câncer colorretal.","B":"Abdome agudo obstrutivo por bridas.","C":"Apendicite.","D":"Colecistite."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-315808","number":"315808","sourceNumber":"315808","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"As hérnias inguinais, classificadas por Nyhus em IIIA são:","options":{"A":"Hérnias indiretas com anel preservado.","B":"Hérnias indiretas com anel alargado.","C":"Hérnias femorais.","D":"Hérnias diretas."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-295428","number":"295428","sourceNumber":"295428","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A hérnia inguinal pediátrica deve ser:","options":{"A":"Corrigida cirurgicamente, para a ligadura do saco herniário derivado do conduto\nperitônio-vaginal.","B":"Tratada com injeção de substâncias esclerosantes no saco herniário.","C":"Observada com o crescimento da criança, pois tende a se fechar espontaneamente.","D":"Operada para reparo da parede muscular e/ou implante de uma tela no defeito herniário."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-274744","number":"274744","sourceNumber":"274744","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Em relação às hérnias da parede abdominal:","options":{"A":"as hérnias inguinais devem ser tratadas cirurgicamente mesmo em pacientes assintomáticos e\nidosos.","B":"a classificação de NYHUS tipo I infere que a hérnia se insinue lateralmente em relação aos\nvasos epigástricos inferiores.","C":"a tomografia de abdome é o exame de escolha caso a hérnia inguinal não seja diagnosticada\npelo exame físico.","D":"a abordagem pré-peritoneal aberta é a técnica mais utilizada para o reparo de hérnias inguinais\nunilaterais sem sinais de complicação."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-281964","number":"281964","sourceNumber":"281964","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"M.A.S., sexo feminino, de 58 anos, com histórico de hipertensão e histerectomia prévia,\nfoi submetida a apendicectomia convencional, há\n11 dias, tendo recebido alta em bom estado geral\nno segundo dia de pós-operatório. Retorna hoje com relato de leve distensão e desconforto\nabdominal, náuseas e vômitos, de início há 2 dias. Ao RX de abdome, apresenta distensão de\nalças de delgado com alguns pontos de nível hidroaéreo. Qual a melhor conduta a ser tomada\ninicialmente?","options":{"A":"Antibioticoterapia e encaminhar ao centro cirúrgico para relaparotomia.","B":"Jejum, hidratação com cristaloides e clister glicerinado.","C":"Jejum, SNG aberta, soroterapia para reposição de eletrólitos e observação 24h.","D":"Jejum, SNG e ultrassonografia de abdome."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-281967","number":"281967","sourceNumber":"281967","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 69 anos, com diagnóstico de colelitíase, com cálculo único de 2,5cm,\naguardando cirurgia ambulatorial de\ncolecistectomia há 2 anos, chega ao pronto-socorro com\nqueixa de dor e distensão abdominal. À USG de abdome superior não foi visualizado o cálculo e ao\nRX simples tem sinais de abdome agudo obstrutivo. O local mais provável de obstrução é:","options":{"A":"Ângulo de Treitz.","B":"Íleo terminal.","C":"Cólon esquerdo.","D":"Colédoco distal."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-281972","number":"281972","sourceNumber":"281972","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Mulher, 35 anos, obesa grau II, refere aumento do volume na região inguinal esquerda\nassociado a dor, início dos sintomas após realizar atividades físicas em academia para perda de\npeso. Ao exame físico, , o cirurgião percebe que a tumoração está abaixo do ligamento inguinal.\n\nQual a classificação de Nyhus e a técnica cirúrgica que deve ser utilizada na correção dessa\nhérnia?","options":{"A":"llla e Shouldice.","B":"IIIb e Lichtenstein.","C":"IIIc e McVay.","D":"II e Lichtenstein."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-281973","number":"281973","sourceNumber":"281973","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Para um paciente com recidiva de hérnia inguinal bilateral após técnica de Shouldice há\n2 anos, qual a técnica cirúrgica mais\nindicada neste momento?","options":{"A":"Técnica de Bassini.","B":"Técnica de Lichtenstein.","C":"Técnica laparoscópica.","D":"Técnica Mcvay."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-285075","number":"285075","sourceNumber":"285075","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um paciente de 75 anos é internado por distensão abdominal, vômitos, crises de\ncólicas cada vez mais intensas e frequentes e\nparada de evacuação e de eliminação de gases há 6\ndias. Nega emagrecimento recente. Proveniente de casa de repouso, o paciente é acamado e\ntotalmente dependente. Está em regular estado geral, mas muito desidratado. Pulso: 110 bpm, PA:\n110 x 70 mmHg. O abdome está distendido e tem sinal de Gersuny+. Etapa do exame físico que\npossibilita a confirmação do diagnóstico:","options":{"A":"Toque retal.","B":"Palpação do canal inguinal.","C":"Ausculta dos ruídos hidroaéreos.","D":"Pesquisa de círculos de Skoda.","E":"Descompressão brusca."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-277415","number":"277415","sourceNumber":"277415","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um lactente com 1 mês de vida vem para a segunda consulta no ambulatório de\nPediatria do Hospital Materno-Infantil\nlocal. A mãe relata que a criança possui um nódulo no umbigo\ndesde o nascimento e está ansiosa, pois uma vizinha disse que seria necessário operar. A criança\nestá em bom estado geral, afebril, ativa e reativa. O exame abdominal revela hérnia umbilical de\n1,5cm de diâmetro, indolor e redutível, sinais flogísticos ausentes. Qual seria a conduta imediata\nmais adequada neste caso:","options":{"A":"solicitar ultrassonografia para avaliar conteúdo da hérnia","B":"avaliação do cirurgião pediátrico e orientar a provável necessidade de cirurgia redutiva","C":"acompanhamento do caso e orientações de possível resolução espontânea","D":"indicar esparadrapagem para auxiliar regressão e fechamento da hérnia e avaliar mensalmente"},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-273168","number":"273168","sourceNumber":"273168","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente homem, 20 anos, com presença de saco herniário na região epigástrica,\napresentando dor à palpação. O diagnóstico\ndiferencial para hérnia hepigástrica deverá constatar:","options":{"A":"A diástase do músculo reto abdominal.","B":"A presença de mais de uma abertura aponeurótica na linha Alba.","C":"O aumento da pressão intra-abdominal, forçando a passagem do tecido adiposo pré-peritoneal.","D":"A projeção do saco herniário através da linha semilunar ou pararretal externa."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-281297","number":"281297","sourceNumber":"281297","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A incisão cirúrgica onde ocorre a secção do tendão do musculo reto-abdominal tem o\nnome de:","options":{"A":"Pfannenstiel.","B":"Cherney.","C":"Paramediana.","D":"Mediana."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-273176","number":"273176","sourceNumber":"273176","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Hérnia é a protrusão de um órgão ou de seu revestimento por meio da parede ou da\ncavidade que deveria contê-la. A presença de saco herniário na região da linha alba acima do\numbigo é denominada hérnia:","options":{"A":"Umbilical.","B":"Inguinal.","C":"Epigástrica.","D":"Femoral."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-265916","number":"265916","sourceNumber":"265916","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente 65 anos, feminina, encaminhada ao pronto socorro com queixa de dor\nabdominal importante, em cólicas, em todo o\nabdome, de início há 3 dias, com piora hoje,\nassociada a distensão abdominal e vômitos escurecidos. Não evacua há 3 dias. Nega febre. Ao\nexame: corada, desidratada, sudoreica, taquicárdica, bulhas rítmicas, sem sopros, sem alterações\npulmonares. Ruídos abdominais ausentes, distendido, hipertimpânico, com dor a palpação difusa,\nsem sinais de peritonite, com abaulamento abaixo do ligamento inguinal, endurecido, doloroso,\nimóvel a palpação, sem sinais flogísticos locais. Foi solicitado radiografia de abdome, ilustrada a\nseguir. Qual a PROVÁVEL hipótese diagnóstica?","options":{"A":"hérnia inguinal redutível.","B":"hérnia obturatória redutível.","C":"hérnia femoral encarcerada.","D":"hérnia inguinal encarcerada."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-265920","number":"265920","sourceNumber":"265920","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 13 anos, relata episódios de vômitos, de conteúdo biliar, de início há\naproximadamente 3 meses, porém vem aumentando a frequência dos episódios de êmeses. Nega\nfebre. Nega diarreia. Relata piora dos vômitos em momentos pós-prandiais, quando se associa dor\nepigástrica intensa. Associa neste mesmo período perda ponderal importante, pois está realizando\ndieta hipocalórica acompanhada por nutricionista devido a obesidade. Internado para investigação\nlevemente desidratado, corado, anictérico, afebril. Sem alterações ao exame físico. Exames\nlaboratoriais revelaram hipocalemia leve (K: 3,2 mEq/L); Realizado radiografias de abdome com\ndistensão gástrica inespecífica, endoscopia digestiva alta com gastrite enantemática leve, teste da\nurease negativo. Submeteu-se a tomografia de abdome que evidenciou distensão da terceira parte\nduodenal com o ângulo aorto-mesentérico reduzido (13°). Qual o PROVÁVEL diagnóstico?","options":{"A":"Estenose hipertrófica de piloro.","B":"Gastrite alcalina.","C":"Aneurisma de aorta.","D":"Síndrome de Wilkie."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-265922","number":"265922","sourceNumber":"265922","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Mulher de 65 anos chega ao ponto socorro queixando-se de dor e distensão abdominal\nimportante, associada a vômitos e sudorese fria. Relata ser constipada crônica, e que sua\nfrequência evacuatória é de 1 evacuação a cada 10 dias. Ao exame físico, regular estado geral,\ndesidratada, dispneica, taquicárdica, sudoreica, com distensão abdominal importante, ruídos aéreos\nabdominais aumentados e metálicos, com dor à palpação difusa, sem sinais de peritonite. Diante da\nradiografia de abdome, o PROVÁVEL diagnóstico é:","options":{"A":"apendicite aguda perfurada e bloqueada.","B":"volvo de sigmóide.","C":"colite pseudomembranosa.","D":"íleo metabólico."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-265923","number":"265923","sourceNumber":"265923","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Mulher de 65 anos chega ao ponto socorro queixando-se de dor e distensão abdominal\nimportante, associada a vômitos e sudorese fria. Relata ser constipada crônica, e que sua\nfrequência evacuatória é de 1 evacuação a cada 10 dias. Ao exame físico, regular estado geral,\ndesidratada, dispneica, taquicárdica, sudoreica, com distensão abdominal importante, ruídos aéreos\nabdominais aumentados e metálicos, com dor à palpação difusa, sem sinais de peritonite. Baseado\nno seu diagnóstico acima. Qual a conduta IMEDIATA?","options":{"A":"laparotomia exploradora.","B":"colonoscopia descompressiva.","C":"antibioticoterapia.","D":"hemicolectomia direita."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-247389","number":"247389","sourceNumber":"247389","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 56 anos, sexo masculino, submetido a tratamento cirúrgico de hérnia na\nregião inguinal há cinco anos, sendo\nregistrado em descrição cirúrgica a presença de saco herniário\nmedial ao anel inguinal interno e aos vasos epigástrico inferiores procurou, há dois dias, avaliação\npelo cirurgião geral que indicou novo procedimento cirúrgico, no qual evidenciou a recidiva da\nhérnia em mesmo local de procedimento cirúrgico realizado há cinco anos. De acordo com a\nclassificação de Nyhus, a hérnia inguinal apresentada pelo paciente no momento desse último\nprocedimento cirúrgico é do tipo:","options":{"A":"I.","B":"II.","C":"III A.","D":"IV A."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-246538","number":"246538","sourceNumber":"246538","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A respeito das hérnias da parede abdominal, assinale a alternativa correta.","options":{"A":"Descrita inicialmente por Ramirez, a técnica de separação de componentes pode ser empregada\npara a correção de falhas volumosas da\nparede abdominal, devendo ser empregada apenas a\ntécnica de separação anterior, visto que a técnica de separação posterior está proscrita, não\ndevendo ser realizada em hipótese alguma.","B":"Apesar dos bons resultados obtidos com o emprego de tela na correção de hérnias da região\ninguinal, as hérnias incisionais apresentam maiores taxas de recidiva após o uso destas, devendo\nser realizada, nesses casos, apenas a síntese da falha no ato cirúrgico, sem o uso de telas.","C":"A classificação de Nyhus é uma das mais amplamente utilizadas para descrever as hérnias da\nregião inguinal, avaliando características anatômicas e a integridade da parede posterior. O subtipo\nI consiste em hérnias do tipo indireto sem alargamento do anel inguinal profundo.","D":"A técnica de Bassini continua sendo o padrão ouro para a correção de hérnias inguinais por\ntratar-se de uma técnica livre de tensão.","E":"As hérnias inguinais têm predileção epidemiológica pelo sexo feminino, sendo de 10 a 20 vezes\nmais frequentes nas mulheres que nos homens."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-229831","number":"229831","sourceNumber":"229831","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Com o progressivo desenvolvimento da cirurgia minimamente invasiva, a correção de\nhérnias incisionais tem sido também abordada por via laparoscópica. Neste contexto a melhor\nalternativa é","options":{"A":"a correção por esta via pode ser utilizada inclusive em pacientes com grandes hérnias, evitando\nassim grandes incisões; contudo é contra-indicada em pacientes com hérnia recidivada.","B":"pacientes obesos devem obrigatoriamente perder peso e, após, manterem-se estáveis;\ntabagistas devem cessar o hábito pelo menos 2\nsemanas antes e serem submetidos a fisioterapia\nrespiratória, de forma ideal, e portadores de hérnias medianas a volumosas devem\nobrigatoriamente utilizar no pré-operatório cintas abdominais para adaptação.","C":"contra-indicações à cirurgia minimamente invasiva incluem hérnia encarcerada aguda ou\ncrônica, recorrência de tumores abdominais, pacientes que não toleram pneumoperitôneo e\ninfecção de pele no local da cirurgia.","D":"para o tratamento de moderadas a grandes hérnias não se faz necessária análise pré-operatória\ncom exames de imagem como tomografia ou\nressonância para programação cirúrgica."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-246539","number":"246539","sourceNumber":"246539","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"As hérnias da região inguinal consistem em patologias frequentes na rotina médica,\nsendo de grande valia o conhecimento básico de sua anatomia, propedêutica e tratamento.\n\nLevando esse fato em consideração, julgue os itens a seguir. I. Na faixa etária pediátrica, as\nhérnias inguinais diretas são as mais\nfrequentes, sendo as do tipo indireta raras e praticamente\ninexistentes, devido à configuração anatômica do anel inguinal externo. II. A cirurgia de McVay é\nclassicamente descrita para a correção das hérnias femorais, consiste num reparo anatômico da\nparede posterior da região inguinal (sutura-se o tendão conjunto ao ligamento de Cooper). Pode\ntambém ser empregada para a correção de hérnias inguinais diretas, mesmo não sendo um\nprocedimento livre de tensão. III. A Técnica de Lichtenstain, classificada como livre de tensão,\nutiliza telas de diferentes gramaturas para reforçar a região inguinal e consiste em técnica\namplamente reproduzida em todo o mundo. IV. Não há relato na literatura de encarceramento por\nhérnias femorais, sendo considerados para tratamento cirúrgico apenas os casos sintomáticos\n(parestesia, dor e dificuldade de deambulação). Pode-se afirmar que:","options":{"A":"todos os itens estão certos.","B":"apenas os itens I e IV estão certos.","C":"apenas os itens II e III estão certos.","D":"apenas os itens II e IV estão certos.","E":"apenas o item III está certo."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-241716","number":"241716","sourceNumber":"241716","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente idoso, acamado após acidente vascular cerebral há 2 anos, antecedentes de\ncirurgia devido a síndrome da calda equina, internado para tratamento de infecção de foco urinário,\nevolui com distensão abdominal progressiva há 3 dias, parada de eliminação de flatos e fezes, sem\nnáuseas ou vômitos, sem febre. Estado geral regular, desidratado, corado, eupneico, anictérico.\n\nAbdome pouco doloroso à palpação, timpânico e sem defesa, ruído hidroaéreo hipoativo.\nLeucocitose de 13000 (sem desvio), hipocalemia,\naumento de creatinina e ureia. Tomografia de\nabdome evidencia dilatação de cólon esquerdo, transverso e direito, ceco de 07cm de dilatação;\nnão foi observado fator obstrutivo. Qual é o provável diagnóstico e qual é a conduta inicial a ser\ntomada, respectivamente?","options":{"A":"Pseudo-obstrução aguda do cólon/ laparotomia exploradora.","B":"Volvo do ceco/ cecostomia.","C":"Pseudo-obstrução aguda do cólon/medidas clínicas (jejum, corrigir distúrbio hidroeletrolítico e\nacidobásicos, sonda nasogástrica, tratar foco infeccioso).","D":"Volvo de sigmoide/ colonoscopia.","E":"Volvo de ceco/ medidas clínicas (jejum, corrigir distúrbio hidroeletrolítico e acidobásicos,\nsonda\nnasogástrica, tratar foco infeccioso)."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-248929","number":"248929","sourceNumber":"248929","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Qual é a melhor conduta diante de quadro de obstrução intestinal por volvo de sigmoide\nde recente instalação?","options":{"A":"cirurgia imediata com redução do volvo e fixação do sigmoide","B":"cirurgia imediata com redução do volvo e colostomia em alça","C":"tentativa de redução com retossigmoidoscopia ou colonoscopia","D":"cirurgia imediata com ressecção do sigmoide à Hartmann"},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-248932","number":"248932","sourceNumber":"248932","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Uma hérnia inguinal estrangulada (íleo terminal encarcerado) necessita de:","options":{"A":"tratamento cirúrgico de urgência, sempre por meio de laparotomia","B":"tratamento cirúrgico de urgência, que pode ser feito pela inguinotomia","C":"redução da hérnia e antibioticoterapia caso o tempo de estrangulamento seja inferior a 6 horas","D":"tratamento cirúrgico de urgência, tanto por laparotomia quanto por inguinotomia, sendo que está\nformalmente contraindicado o uso de tela de polipropileno"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-241720","number":"241720","sourceNumber":"241720","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Lactente apresenta hérnia em região umbilical. Em que caso a cirurgia de correção está\nindicada?","options":{"A":"Anel menor que 2 cm após primeiro ano de vida.","B":"Anel menor que 1 cm após primeiro ano de vida.","C":"Anel maior que 1cm após primeiro ano de vida.","D":"Anel menor que 1cm após dois anos de vida.","E":"Anel maior que 2 cm após primeiro ano de vida."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-249508","number":"249508","sourceNumber":"249508","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 53 anos, admitido em pronto-socorro por vômitos há 3 dias, associado à\ndor abdominal importante, em cólicas, que vem\nse tornando progressiva. Nega febre. Queixa-se de\nhiporexia. Nega sintomas urinários. Ao exame físico, apresenta-se em regular estado geral,\ndesidratado, discretamente taquicárdico, com exame físico cardiopulmonar normal. Ruídos\nreduzidos em todo o abdome, doloroso difusamente, distendido, sem sinais de irritação peritoneal.\nFoi submetido à radiografia abaixo, com achado pouco comum destacado pela seta. Hemograma\ncom discreta leucocitose, função renal normal. Análise de exame de urina normal. A principal\nhipótese diagnóstica é:","options":{"A":"Volvo de sigmóide.","B":"Úlcera perfurada.","C":"Íleo Biliar.","D":"Ureterolitíase."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-229543","number":"229543","sourceNumber":"229543","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A tríade de Rigler consiste em:","options":{"A":"Hemobilia, hematêmese e icterícia.","B":"Hemobilia, hematêmese e dor abdominal.","C":"Icterícia, febre e dor abominal.","D":"Aerobilia, cálculo biliar ectópico, sinais de obstrução intestinal."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-229550","number":"229550","sourceNumber":"229550","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente 65 anos, etilista, procura pronto socorro com quadro de dor abdominal em\ncólicas, de início há 4 dias, progressiva\ne com piora há 1 dia, associada a vômitos, distensão\nabdominal, e parada de eliminação de flatos. Nega febre. Ao exame físico, apresentava-se em\nregular estado geral, desidratado, corado, anictérico, afebril. Sem alterações no aparelho\ncardiopulmonar, com ruídos hidroaéros reduzidos em todo o abdome, levemente distendido, sem\nsinais de peritonite porém com dor a palpação difusa. Sinal de Murphy negativo. Após medicado, o\nplantonista solicita radiografia de abdome agudo que evidencia níveis hidroaéreos em todo intestino\ndelgado com aspecto de ?empilhamento de moedas?, presença de ar na via biliar, associado a\nimagem radiopaca em íleo terminal. Baseado no caso acima, o PROVÁVEL diagnóstico é:","options":{"A":"Obstrução Intestinal por neoplasia de cólon.","B":"Obstrução Intestinal por doença diverticular complicada.","C":"Íleo Biliar.","D":"Úlcera gástrica perfurada bloqueada."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-252783","number":"252783","sourceNumber":"252783","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Sobre o tratamento cirúrgico das hérnias inguinais, não podemos afirmar:","options":{"A":"Sendo as hérnias inguinais da criança, em sua grande maioria, do tipo indireta, sua correção\ncirúrgica consiste em ligadura alta do saco herniário.","B":"A técnica de Mc Vay é indicada no tratamento da hérnia femoral.","C":"A técnica de Shouldice é uma das técnicas com menor índice de recidiva por ser livre de tensão\nna sutura dos 4 planos de sutura das\nestruturas musculares - aponeuróticas.","D":"Na técnica de Lichtenstein, a sutura da tela de polipropileno é feita sem tensão ao longo do\nligamento inguinal inferiormente e no tendão conjunto e sob o músculo oblíquo interno."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-252784","number":"252784","sourceNumber":"252784","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Na classificação de Nyhus para hérnia na virilha, a hérnia indireta com alargamento do\nanel interno e destruição da parede posterior do canal inguinal é do tipo:","options":{"A":"II.","B":"III - A.","C":"III - B.","D":"III - C."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-248960","number":"248960","sourceNumber":"248960","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Recém-nascido a termo, 3,2 kg apresenta grande hérnia umbilical com anel herniário\nmaior que 8 cm. É submetido à cirurgia e, no\npós-operatório imediato, em berço comum e já\ndesperto, com sonda nasogástrica aberta e RHA ausentes, evolui com temperatura de 37,7oC,\ntaquicardia e choro estridente. A primeira providência deverá ser:","options":{"A":"alimentar ao seio, pois se trata de fome.","B":"administrar analgésico opióide.","C":"verificar hidratação.","D":"administrar analgésico não opióide."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-252788","number":"252788","sourceNumber":"252788","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente do sexo masculino, 63 anos, chega ao PS com quadro de dor e distensão\nabdominal difusa, náuseas e vômitos. Refere diagnóstico de colelitíase sintomática, aguardando\nchamado para cirurgia eletiva. Submetido a CT de abdome que evidenciou aerobilia e distensão\ndifusa de alças de delgado, além de imagem calcificada circular em íleo terminal. Assinale a\nalternativa que tem o diagnóstico mais provável:","options":{"A":"Neoplasia de íleo terminal.","B":"Suboclusão por bridas.","C":"Hérnia interna.","D":"Íleo biliar."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-252792","number":"252792","sourceNumber":"252792","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente do sexo feminino, 28 anos, em 15º mês de pós-operatório de by-pass gástrico\nem \"Y de Roux\" por videolaparoscopia,\nqueixa-se de dor tipo cólica em mesogástrio há 2 dias, com\npiora progressiva e forte intensidade. Ao exame, apresenta FC:118 bpm, sudoreica, abdome pouco\ndistendido, doloroso à palpação difusa, sem peritonismo. Leucograma com 14600 leucócitos (8%\nbastonetes), amilase 78. Realizado Rx abdome que evidenciou distensão gasosa de alças de\ndelgado em abdome superior, bolha gástrica aumentada, sem sinais de pneumo-peritônio. Assinale\na alternativa que tem a melhor suspeita diagnóstica e conduta:","options":{"A":"Fístula de anastomose gastrojejunal - laparotomia exploradora.","B":"Estenose de anastomose gastrojejunal - dilatação endoscópica.","C":"Gastroenterite aguda - hidratação e analgesia.","D":"Hérnia interna - laparoscopia de urgência."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-254286","number":"254286","sourceNumber":"254286","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Em um ambulatório o staff apresenta o caso ao residente de cirurgia geral de um\nsenhor de 50 anos, tabagista com abaulamento\nna região inguinal que reduz espontaneamente\nquando o paciente deita em decúbito dorsal. Sobre esta patologia marque o item CORRETO.","options":{"A":"Trata-se de uma hérnia inguinal direta e no exame físico da região inguinal o dedo vai de\nencontro a polpa do dedo do examinador.","B":"Trata-se de uma hérnia inguinal indireta causada pelo enfraquecimento da parede abdominal.","C":"Em caso de estrangulamento da hérnia o paciente deve ser submetido a manobras de redução\ncomo o decúbito dorsal e a imposição de\ngolo sobre a área.","D":"Hérnia inguinal direta é a mais comum da infância e deve ser operada o mais precocemente\npossível."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-252816","number":"252816","sourceNumber":"252816","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"\"Alice vem para sua primeira consulta com o Dr. Guilherme que faz todas as\norientações de como será o acompanhamento do\ncrescimento e desenvolvimento da pequena.\nMariana está com dúvida sobre aleitamento materno, quando iniciar alimentação, já que só terá 04\n(quatro) meses de licença e também questiona sobre a hérnia umbilical da pequena Alice. Dr.\n\nGuilherme já a orienta, ao sair da consulta, a passar na sala de vacina para orientações\". Com\nrelação à hérnia umbilical, qual a conduta correta?","options":{"A":"É uma urgência cirúrgica, encaminhar imediatamente ao pronto-socorro infantil.","B":"Orientar a mãe que a conduta é expectante até os 02 (dois) anos de idade.","C":"Orientar a mãe a usar faixa abdominal na criança para ajudar a fortalecer a musculatura\nabdominal e reduzir a hérnia umbilical.","D":"Orientar a mãe para a realização de massagem abdominal para reduzir a hérnia umbilical."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-216461","number":"216461","sourceNumber":"216461","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Homem, 42 anos de idade, pedreiro há 2 décadas, tabagista desde a adolescência de\n20 cigarros/dia. Comparece à UBS devido a\nabaulamento na região inguinal há 1 ano. Ao exame,\nnota-se nodulação indolor e móvel localizada inferiormente ao ligamento inguinal com piora à\nmanobra de valsalva. Diante do quadro, dentre as alternativas abaixo, qual seria a melhor conduta?","options":{"A":"Cirúrgica, sutura do ligamento inguinal ao tendão conjunto.","B":"Cirúrgica, sutura do ligamento inguinal ao ligamento de Cooper.","C":"Cirúrgica, sutura do trato iliopúbico ao ligamento de Cooper.","D":"Cirúrgica, sutura do ligamento inguinal à aponeurose do oblíquo externo."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-216577","number":"216577","sourceNumber":"216577","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A presença do apêndice vermiforme (com ou sem reação inflamatória) no interior do\nsaco herniário inguinal é chamada de hérnia de:","options":{"A":"Spiegel.","B":"Littré.","C":"Richter.","D":"Amyand."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-216467","number":"216467","sourceNumber":"216467","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 28 anos compareceu ao amulatório de cirurgia com relato de dor em região\nsupraumbilical. Ao exame físico, apresentou hérnia epigástrica com conteúdo irredutível, que\nsugere encarceramento de:","options":{"A":"Jejuno proximal.","B":"Cólon transverso.","C":"Grande epíplon.","D":"Gordura pré-peritoneal."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-216475","number":"216475","sourceNumber":"216475","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Uma paciente de 62 anos, diabética, vem ao pronto-socorro com dor na face interna da\nraiz da coxa à direita, abaixo do ligamento inguinal, onde é evidenciada tumoração, hiperemia, calor\nlocal e ponto de flutuação. Ao ser feita a drenagem cirúrgica da coleção, há vazão de secreção\npurulenta, amarronzada e extremamente fétida, misturada com conteúdo entérico. Qual a hipótese\ndiagnóstica mais provável:","options":{"A":"Necrose séptica do assoalho.","B":"Fasceíte necrotizante do assoalho pélvico.","C":"Hérnia de Richter.","D":"Hérnia de Littré."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-214920","number":"214920","sourceNumber":"214920","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Assinale a principal causa de obstrução intestinal mecânica precoce pós-operatória:","options":{"A":"aderências","B":"fleimão ou abscesso","C":"hérnia interna","D":"isquemia intestinal"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-202675","number":"202675","sourceNumber":"202675","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Quanto à anatomia dos cólons e do reto, considera-se que","options":{"A":"a artéria retal superior origina-se da artéria mesentérica inferior.","B":"as válvulas de Houston localizam-se no canal anal e são responsáveis pela continência fecal.","C":"as tênias colônicas proporcionam ao reto maior distensibilidade para funcionar como reservatório\nfecal.","D":"os esfíncteres anais, interno e externo, são estruturas musculares estriadas como função de\ncontinência devido à inervação somática e autonômica."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-218250","number":"218250","sourceNumber":"218250","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Pela classificação de Nyhus, a hérnia inguinal que apresenta defeito na parede\nposterior e está localizada lateralmente aos vasos epigástricos inferiores é a:","options":{"A":"II.","B":"IIIB.","C":"IIIA.","D":"IVB."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-210594","number":"210594","sourceNumber":"210594","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Hérnias que são constituídas pela herniação parcial da parede de uma alça intestinal\n(borda antimesentérica) são denominadas:","options":{"A":"Richter","B":"Amyand","C":"Littré","D":"Spiegel","E":"Petit"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-217014","number":"217014","sourceNumber":"217014","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente masculino, 35 anos, foi submetido à correção cirúrgica de hérnia inguinal. No\npós-operatório, o paciente foi informado de que sua hérnia era indireta. De acordo com esse tipo de\nhérnia, assinale a alternativa correta referente à anatomia do saco herniário.","options":{"A":"Medial aos vasos epigástricos superiores e anteromedial aos elementos do cordão espermático.","B":"Medial aos vasos epigástricos inferiores e posterolateral aos elementos do cordão espermático.","C":"Lateral aos vasos epigástricos superiores e anterolateral aos elementos do cordão espermático.","D":"Lateral aos vasos epigástricos inferiores e anteromedial aos elementos do cordão espermático.","E":"Lateral aos vasos epigástricos inferiores e posterolateral aos elementos do cordão."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-217030","number":"217030","sourceNumber":"217030","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Homem, 58 anos, apresenta há dois dias história de distensão abdominal, vômitos, dor\nabdominal tipo cólica e obstipação. No momento, refere piora da sintomatologia associada a sede e\noligúria. Qual é a origem mais provável da dor abdominal?","options":{"A":"Úlcera perfurada.","B":"Obstrução intestinal.","C":"Colecistite aguda.","D":"Apendicite aguda.","E":"Colangite."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-217050","number":"217050","sourceNumber":"217050","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 6 meses de idade apresenta quadro de obstrução intestinal. Qual é a\ncausa mais comum nessa idade?","options":{"A":"Obstrução por bolo de áscaris.","B":"Invaginação intestinal.","C":"Má-rotação intestinal.","D":"Atresia ou estenose de intestino.","E":"Hérnia inguinal encarcerada."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-215380","number":"215380","sourceNumber":"215380","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Marque a alternativa INCORRETA com relação às hérnias umbilicais.","options":{"A":"Origina-se do fechamento incompleto do orifício de passagem do cordão umbilical ou da\npersistência de estruturas fetais, como ducto onfalomesentérico e úraco.","B":"O diagnóstico é feito pela simples inspeção, observando-se abaulamento da região umbilical de\nvárias proporções que aumenta com o choro ou aos esforços.","C":"Nos casos de hérnia com anel pequeno, pode haver a regressão espontânea do defeito até o\nsegundo ano de vida.","D":"A cirurgia está indicada em caso em que o anel seja maior que 2 cm após o primeiro ano de\nvida, a parede do anel seja espessa, com\npresença de fibrose em sua borda ou pela existência de\ngrandes sacos herniários com conteúdo de alças intestinais."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-185139","number":"185139","sourceNumber":"185139","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A parede abdominal tem origem embrionária da.","options":{"A":"placa medial do mesoderma intraembionário.","B":"ectoderma intraembionário.","C":"placa lateral do mesoderma intraembrionário.","D":"endoderma intraembionário."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-185146","number":"185146","sourceNumber":"185146","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A hérnia da parede abdominal que ocorre entre músculo reto medialmente e a linha\nsemilunar lateralmente é a hérnia de","options":{"A":"Amyand","B":"Richter","C":"Littré","D":"Spiegel"},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-186422","number":"186422","sourceNumber":"186422","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A circulação do cólon e do reto é representada por duas fontes principais de nutrição\nsanguínea: a artéria mesentérica superior, nutrindo o cólon direito através da ileocólica, cólica\ndireita e cólica média, e a artéria mesentérica inferior, através das artérias sigmoidea e retal\nsuperior. Ambos os vasos se unem por rede anastomótica através de:","options":{"A":"Arcada de ângulo esplênico e pancreático.","B":"Arcada de Riolan e artéria marginal de Drummond.","C":"Tronco celíaco.","D":"Plexo hemorroidário."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-186434","number":"186434","sourceNumber":"186434","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"O canal inguinal no adulto tem aproximadamente 4 cm de comprimento e contém o\ncordão espermático ou o ligamento redondo do útero. O triângulo de Hesselbach é representado\nanatomicamente, como borda medial, a bainha do músculo reto abdominal e as outras duas\nbordas, respectivamente, inferior e súpero-lateral, por:","options":{"A":"Ligamento de Cooper e saco herniário.","B":"Ligamento inguinal e plexo pampiniforme.","C":"Ligamento inguinal e vasos epigástricos.","D":"Artéria cremastérica e nervo genitofemoral."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-187719","number":"187719","sourceNumber":"187719","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Na correção cirúrgica da hérnia inguinal no homem é fundamental a identificação e o\nisolamento correto do funículo espermático. São considerados elementos do funículo espermático,\nexceto:","options":{"A":"Ducto deferente.","B":"Artéria testicular.","C":"Músculo cremáster.","D":"Nervo íleo femoral."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-186444","number":"186444","sourceNumber":"186444","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A classificação de Nyhus de Hérnia Inguinal é utilizada na rotina para diferenciação da\netiologia, anatomia e tipo de reparo cirúrgico. A classificação da hérnia chamada da inguinal\ndireta,\ncom defeito da parede posterior é:","options":{"A":"Tipo I.","B":"Tipo II.","C":"Tipo IIIa.","D":"Tipo IV."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-187721","number":"187721","sourceNumber":"187721","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Íleo paralítico é uma complicação comum no pós-operatório de cirurgias abdominais.\nEle é causado freqüentemente por distúrbios\nhidro-eletrolíticos, sendo o mais comum:","options":{"A":"Hipocalemia.","B":"Hipocalcemia.","C":"Hiponatremia.","D":"Hipomagnesemia."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-175382","number":"175382","sourceNumber":"175382","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um homem de 31 anos, com atividade física diária procura cirurgião geral com queixa\nde tumoração protrusa e retrátil na região\ninguinal direita há 2 anos. Ao exame físico apresenta IMC\n\n= 23 e hérnia inguinal à direita primária e redutível. O tratamento é:","options":{"A":"observação clínica","B":"cirúrgico com uso de tela; técnica de Lichtenstein ou laparoscópica","C":"cirúrgico sem tela; técnica de Bassini","D":"cirúrgico sem tela; técnica de McVay","E":"cirúrgico com uso de tela; técnica de Stoppa"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-175385","number":"175385","sourceNumber":"175385","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"O triângulo lombar inferior está relacionado com a hérnia de:","options":{"A":"Grynfeltt","B":"Spiegel","C":"Douglas","D":"Hesselbach","E":"Petit"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-175389","number":"175389","sourceNumber":"175389","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Os tipos de hérnia inguinal mais comuns no homem e na mulher são, respectivamente:","options":{"A":"direta e femoral","B":"indireta e femoral","C":"direta e indireta","D":"indireta e direta","E":"indireta e indireta"},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-178795","number":"178795","sourceNumber":"178795","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente portador de adenocarcimona de ceco será submetido à colectomia direita\nconvencional. As principais artérias que deverão ser ligadas durante o procedimento cirúrgico são:","options":{"A":"ileocólica, cólica direita e ramo direito da artéria cólica média.","B":"cólica direita e cólica média.","C":"ileocólica e ramo direito da artéria cólica média.","D":"ramo esquerdo da artéria cólica média e cólica direita.","E":"cólica média e apendicular."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-178778","number":"178778","sourceNumber":"178778","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Considerando a classificação de Nyhus para a hérnia inguinal, assinale a alternativa\nincorreta.","options":{"A":"Nyhus I: hérnia indireta com anel profundo normal (sem alargamento).","B":"Nyhus II: hérnia indireta com anel profundo alargado.","C":"Nyhus III A: hérnia indireta com defeito da parede posterior.","D":"Nyhus III C: hérnia femoral.","E":"Nyhus IV: hérnia inguinal recidivada."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-186429","number":"186429","sourceNumber":"186429","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Adriana trouxe seu filho para consulta de puericultura na unidade de saúde da família, e\ndurante a consulta, a médica diagnosticou uma hérnia umbilical no lactente de 2 meses de idade.\n\nDiante do diagnóstico, qual a conduta a ser dada à mãe da criança:","options":{"A":"Ensinar massagem abdominal, com movimento circulares.","B":"Encaminhar para cirurgia pediátrica o mais rápido possível.","C":"Explicar para a mãe que a consulta é expectante e observarm até dois anos de idade.","D":"Encaminhar para cirurgia pediátrica, se a hérnia persistir após os 9 meses de idade."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-187567","number":"187567","sourceNumber":"187567","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente de 65 anos, previamente hígido e trabalhador braçal, deu entrada no Pronto\nSocorro com náuseas e vômitos há 6 horas,\ndor inguinal direita intensa com irradiação testicular e\naumento do volume em região inguinal. Refere ter sido submetido há 1 ano a prostatectomia por\ndoença benigna. No exame clínico abaulamento irredutível em região inguinal acompanhado de dor\nintensa à palpação. Achado transoperatório de anel inguinal interno dilatado com preservação de\nparede posterior, contudo isquemia de alça de íleo encarcerada com omento. Neste caso o\ndiagnóstico e tratamento prováveis são","options":{"A":"hérnia inguinal tipo II encarcerada e cirurgia de urgência via aberta sem tela.","B":"hérnia inguinal tipo II encarcerada e cirurgia de urgência via laparoscópica com tela.","C":"hérnia inguinal tipo III encarcerada e cirurgia de urgência via aberta sem tela.","D":"hérnia inguinal tipo I encarcerada e cirurgia de urgência via laparoscópia com tela."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-150725","number":"150725","sourceNumber":"150725","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Qual é o nome da técnica de reparo mais adequada para correção de hérnia da parede\nabdominal localizada inferiormente ao ligamento de Poupart?","options":{"A":"Mac Vay.","B":"Bassini.","C":"Shouldice.","D":"Lichtenstein."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-154636","number":"154636","sourceNumber":"154636","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um paciente de 76 anos, do sexo masculino, é recebido no serviço de emergência\napresentando quadro clínico de parada de\neliminação de gases e fezes, com 4 dias de evolução,\nseguida de vômitos e queda no estado geral. Sinais vitais:\n\nPA = 120 x 70 mmHg; FC = 110 bpm; Tax = 36,8°C; FR = 19irpm; leucograma = 9.000\nleucócitos/mm³, sem desvio para a esquerda. Após\nmedidas de suporte clínico, é submetido a\nestudo radiológico que revela acentuada distensão gasosa do cólon até o nível da fossa ilíaca\nesquerda e ausência de distensão do intestino delgado. Realiza-se um clister opaco em que se\nobserva ?sinal do bico de pássaro?. A conduta a ser seguida, no caso, é:","options":{"A":"Colostomia transversa à direita.","B":"Descompressão nasogástrica e medidas de suporte clínico.","C":"Laparotomia exploradora.","D":"Descompressão endoscópica do intestino grosso.","E":"Descompressão videolaparoscópica do intestino grosso."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-149186","number":"149186","sourceNumber":"149186","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Com base no National Operative Statistics, as hérnias:","options":{"A":"Umbilicais constituem 20% das hérnias.","B":"Incisionais correspondem de 15 a 20% de todas as hérnias da parede abdominal.","C":"Epigástricas constituem 2% das hérnias.","D":"Femorais representam cerca de 25% das hérnias."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-149199","number":"149199","sourceNumber":"149199","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"?Hérnia inguinal indireta ? anel inguinal interno dilatado, medialmente enrolado\nou destruída a fáscia transversalis do triângulo\nde Hasselbach.? De acordo com a\nclassificação de NYHUS para hérnias da região inguinal, essa descrição corresponde ao:","options":{"A":"Tipo II.","B":"Tipo IIIA.","C":"Tipo IIIB.","D":"Tipo IIIC."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-157292","number":"157292","sourceNumber":"157292","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"As causas mais comuns de obstrução de intestino delgado e intestino grosso são,\nrespectivamente:","options":{"A":"Aderência e vólvulo.","B":"Aderência e neoplasia.","C":"Hérnia e aderência.","D":"Neoplasia e hérnia.","E":"Hérnia e neoplasia."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-158453","number":"158453","sourceNumber":"158453","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Sabe-se que as hérnias na região inguinal ocorrem na área descrita por Fruchaud,\ndenominada Triângulo miopectineo de Fruchaud. Quais são os limites desta área?","options":{"A":"É delimitado superiormente pelos músculos oblíquo interno e transverso, inferiormente pelo\nligamento pectíneo, lateralmente pelo músculo íleopsoas e medialmente pelo músculo reto\nabdominal.","B":"Limitada pelo ligamento inguinal, inferiormente, a borda do reto abdominal e os vasos\nepigástricos inferiores, superiormente","C":"É delimitado superiormente pelos músculos oblíquo externo e transverso, inferiormente pelo\nligamento inguinal, lateralmente pelo músculo íleopsoas e medialmente pelo músculo reto\nabdominal.","D":"Limitada pelo ligamento inguinal, superiormente, a borda do reto abdominal e os vasos\nepigástricos inferiores, inferiormente."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-157306","number":"157306","sourceNumber":"157306","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Qual a localização mais comum das hérnias da parede abdominal em um homem\nadulto?","options":{"A":"Femoral.","B":"Inguinal indireta.","C":"Inguinal direta.","D":"Epigástrica.","E":"Umbilical."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-156404","number":"156404","sourceNumber":"156404","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Em relação à anatomia da região inguinal, é correto afirmar que:","options":{"A":"o ligamento lacunar localiza-se no ângulo de encontro entre o ligamento pectíneo e o ligamento\ninguinal.","B":"a fáscia transversalis compreende o limite inferior do canal inguinal.","C":"a fáscia de Escarpa está localizada anteriormente à fáscia de Camper.","D":"a artéria epigástrica inferior é ramo da artéria ilíaca Interna."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-156400","number":"156400","sourceNumber":"156400","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Qual o melhor tratamento da síndrome de Ogilvie?","options":{"A":"Ressecção do segmento afetado.","B":"Realização de colostomia.","C":"Cecostomia.","D":"Sondagem nasogástrica."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-141530","number":"141530","sourceNumber":"141530","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Como se denomina a hérnia inguinal que contém em seu saco herniário o apêndice\ncecal com processo de apendicite?","options":{"A":"Hérnia de Garengeot.","B":"Hérnia de Richter.","C":"Hérnia de Littre.","D":"Hérnia de Amyand."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-129870","number":"129870","sourceNumber":"129870","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Durante o tratamento cirúrgico de uma hérnia, com protrusão de gordura pré-peritoneal\ne de um saco herniário através do orifício\nfemoral, a conduta do cirurgião foi a redução do\ncomponente por deslizamento, tratamento do saco herniário e reconstrução da parede com\naproximação e sutura do arco aponeurótico do músculo transverso ao ligamento de Cooper, com\npontos separados de nylon 0, até a altura dos vasos femorais. A descrição acima caracteriza uma\nclassificação para hérnias e uma técnica que pode ser usada para o tratamento cirúrgico, definidas,\nrespectivamente, como","options":{"A":"Nyhus do tipo III B e reparo à Shoudice.","B":"Nyhus do tipo III B e reparo à Bassini.","C":"Nyhus do tipo III C e reparo à McVay.","D":"Nyhus do tipo III C e reparo à Shoudice."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-127273","number":"127273","sourceNumber":"127273","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Sobre hérnias ventrais, assinale a alternativa INCORRETA.","options":{"A":"A hérnia mais comum em mulheres é a femural e, nos homens, a inguinal.","B":"O sinal de Howship-Romberg, na hérnia obturadora, indica dor referida acompanhando o nervo\nobturador.","C":"As hérnias lombares ocorrem nos flancos, com mais frequência no triângulo lombar superior\n(Grynfelt) ou inferior (Petit).","D":"Todas as alternativas estão incorretas."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-136881","number":"136881","sourceNumber":"136881","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente JBS, 21 anos, masculino, branco, estudante universitário, apresenta-se em\nconsulta de rotina com queixa de dor em cólica abdominal episódica que iniciou há 8 meses. Afirma\npiora progressiva da intensidade, relaciona a dor ao período pós-prandial, com melhora após uso\nde anti-espasmódico. Ao exame clínico, evidenciou-se lesões pigmentadas em pele, principalmente\nperi-oral e dor abdominal leve à palpação sem irritação peritoneal. Realizou USG de abdome sem\nalterações e EDA com diagnóstico de pólipo hamartomatoso ao exame histopatológico. Caso o\npaciente apresente quadro de distensão abdominal, vômitos com parada de eliminação de gazes e\nfezes, qual seria a melhor conduta?","options":{"A":"Sondagem nasogástrica.","B":"EDA com polipectomia endoscópica.","C":"Sondagem nasogástrica, radiografia de rotina para abdome agudo e laparotomia exploradora.","D":"Tratamento do fecaloma, comum nesses pacientes, com enemas glicerinados."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-127278","number":"127278","sourceNumber":"127278","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Sobre hérnias inguinais por deslizamento, marque (V) para Verdadeiro ou (F) para\nFalso e, em seguida, assinale a alternativa\ncontendo sequência CORRETA. ( ) Faz-se o reparo do\nligamento de Cooper após a redução do saco. ( ) A bexiga e o cólon são os principais órgãos\nenvolvidos. ( ) Na maioria dos casos são hérnias indiretas.","options":{"A":"V / F / V .","B":"F / V / F .","C":"F / F / V .","D":"V / V / F ."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-127059","number":"127059","sourceNumber":"127059","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paulo Roberto de 22 anos, com síndrome de Peutz-Jeghers, deu entrada no serviço de\nemergência com quadro de oclusão intestinal. Realizou tomografia computadorizada, que\nevidenciou distensão do intestino delgado com imagem \"em alvo?. A principal hipótese diagnóstica\npara esse quadro obstrutivo é:","options":{"A":"Invaginação intestinal.","B":"Torção mesentérica.","C":"Estenose luminal.","D":"Hérnia interna."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-127062","number":"127062","sourceNumber":"127062","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um homem de 55 anos apresenta, há 2 dias, história de distensão abdominal, vômitos,\ndor abdominal tipo cólica e obstipação. No\nmomento, refere piora da sintomatologia associada a\nsede e oligúria. A origem mais provável da sua dor abdominal é:","options":{"A":"Úlcera perfurada.","B":"Colecistite aguda.","C":"Apendicite aguda.","D":"Obstrução intestinal."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-127077","number":"127077","sourceNumber":"127077","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um paciente de 65 anos dá entrada no serviço de emergência apresentando quadro de\nobstrução intestinal baixa com, aproximadamente, 48 horas de evolução. Após reposição\nhidroeletrolítica, é encaminhado ao serviço de radiologia, onde é feito o diagnóstico de volvo do\nsigmoide. O estado geral do paciente é regular, não apresentando qualquer sinal clínico ou\nlaboratorial de infecção. A conduta mais adequada é realizar:","options":{"A":"Clister glicerinado, sob pressão para redução do volvo.","B":"Descompressão endoscópica e colocação de sonda retal.","C":"Laparotomia exploradora e colostomia em dupla boca.","D":"Laparotomia exploradora e procedimento de Hartmann.","E":"Colectomia esquerda com anastomose primária."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-136563","number":"136563","sourceNumber":"136563","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A indicação cirúrgica mais comum nos casos de doença de Crohn decorre de","options":{"A":"Perfuração livre.","B":"Hemorragia maciça.","C":"Obstrução intestinal.","D":"Degeneração maligna."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-138620","number":"138620","sourceNumber":"138620","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um paciente apresenta-se com abaulamento na região inguinal, sendo considerado\nportador de hérnia inguinal classificada como\nNyhus III A. Espera-se encontrar neste paciente qual\ntipo de alteração do canal inguinal?","options":{"A":"Alargamento do anel inguinal interno com parede posterior preservada.","B":"Alargamento do anel inguinal interno com parede posterior destruída.","C":"Alargamento do anel femoral.","D":"Defeito na parede posterior do canal inguinal."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-127621","number":"127621","sourceNumber":"127621","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Uma menina de nove meses levada ao pediatra porque foi percebido um \"caroço na\nvirilha\" da criança. Quando questionados, os\npais informaram que o caroço aparecia mais quando a\ncriança chorava e que, quando o palpavam, aparentemente não doía. Ao exame físico, observou-se\numa tumoração em região inguinal direita, redutível e indolor, de consistência macia. O provável\ndiagnóstico e o tratamento da criança são, respectivamente, os seguintes:","options":{"A":"Hérnia de ovário e tratamento cirúrgico porque, apesar de o encarceramento não levar ao\nsofrimento do ovário, podem ocorrer torção e sofrimento subsequente.","B":"Hérnia de ovário e tratamento conservador até que ocorra o encarceramento, já que o mesmo\nnão leva ao sofrimento do ovário.","C":"Cisto de cordão e tratamento cirúrgico porque o cisto pode se romper levando à peritonite.","D":"Cisto de cordão e tratamento conservador, já que o conduto peritoniovaginal pode fechar-se\nespontaneamente até três anos de idade."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-109380","number":"109380","sourceNumber":"109380","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Segundo a classificação de Nyhus, considerando as hérnias da região inguinal, é do\ntipo IIIB a seguinte:","options":{"A":"hérnia inguinal direta recidivante.","B":"hérnia inguinal indireta inguinoescrotal volumosa.","C":"hérnia inguinal direta com defeito da parede posterior.","D":"hérnia inguinal indireta com anel inguinal dilatado e parede posterior intacta."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-101150","number":"101150","sourceNumber":"101150","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"O reparo cirúrgico da hérnia inguinal, no qual ocorre aproximação e sutura do arco\naponeurótico do músculo transverso ao ligamento de Cooper, é conhecido como técnica de:","options":{"A":"McVay.","B":"Bassini.","C":"Shouldice.","D":"Cooper."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-101171","number":"101171","sourceNumber":"101171","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Qual é o fator de risco isolado mais importante para o surgimento do câncer colorretal?","options":{"A":"Idade.","B":"Tabagismo.","C":"História familiar.","D":"Dieta."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-102481","number":"102481","sourceNumber":"102481","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Pela classificação de Nyhus, a hérnia inguinal femoral é de que tipo?","options":{"A":"Tipo I;","B":"Tipo II;","C":"Tipo llla;","D":"Tipo lllc;","E":"Tipo IV."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-106692","number":"106692","sourceNumber":"106692","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente do sexo masculino, 32 anos de idade tem Índice de Massa Corporal (IMC) =\n26, e apresenta tumoração umbilical redutível. Sua profissão está relacionada com atividade que\nenvolve esforço físico. Com relação à correção cirúrgica e possibilidade de uso da anestesia local,\né correto afirmar que:","options":{"A":"é mais indicada para os pacientes magros.","B":"é mais indicada nas hérnias primárias.","C":"é mais indicada para as hérnias redutíveis e não muito volumosas.","D":"todas as alternativas anteriores estão corretas."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-110232","number":"110232","sourceNumber":"110232","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente JMS, de 40 anos, sexo masculino, dá entrada no pronto-socorro com dor\nabdominal intensa e difusa há três dias, com\npiora nas últimas 24 horas. Relata ainda anorexia,\nnáuseas, vômitos e ausência de flatos e evacuações neste período. Nega frebre e outros sinais\ne/ou sintomas. Antecedentes pessoais: sem comorbidades. Laparotomia exploradora há cinco anos\npor ferimento de arma de fogo. Ao exame clínico: regular estado geral, desidratado, corado, afebril.\nFrequência cardíaca de 120 bpm, e pressão arterial igual a 100 x 60 mmHg. Abdômen\nsemigloboso, tenso, distendido, com hipertimpanismo, intensamente doloroso à palpação, sem\nsinais de irritação peritoneal. Ruídos hidroaréreos ausentes. Toque retal sem fezes na ampola retal.\nExames laboratoriais: 16.000 leucócitos com 16% de bastões e 72% de segmentados amilase e\nurina I normais. Radiografia de abdômen em ortostase apresentada a seguir. (VER IMAGEM).\n\nNesse caso, qual a conduta para este paciente?","options":{"A":"Realizar tomografia de abdômen, pois se trata de exame mais específico, uma vez que o\ndiagnóstico não pode ser feito com a história clínica e exames solicitados.","B":"Indicar tratamento cirúrgico para o paciente, não sendo necessário realizar tomografia de\nabdômen, pois o diagnóstico pode ser feito com a história clínica e exames solicitados.","C":"Solicitar gasometria arterial e dosagem de eletrólitos para o paciente, pois, se houver distúrbio\nmetabólico, a cirurgia é contraindicada.","D":"Realizar tomografia de abdômen e após o exame, indicar tratamento cirúrgico por\nvideolaparoscopia, uma vez que se trata de um procedimento menos invasivo."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-78098","number":"78098","sourceNumber":"78098","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A hérnia da parede abdominal cujo conteúdo é um divertículo de Meckel é a hérnia de:","options":{"A":"Richter.","B":"Spiegel.","C":"Littré.","D":"Grynfeltt."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-85814","number":"85814","sourceNumber":"85814","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Com relação às hérnias inguinais, assinale a resposta CERTA:","options":{"A":"A hérnia crural- femoral é mais comum em mulheres. Durante a correção cirúrgica desse tipo de\nhérnia, é imprescindível o uso de uma técnica que inclua o fechamento do espaço femoral.","B":"A hérnia inguinal indireta, também chamada de oblíqua externa, é formada por um saco\nperitoneal que se exterioza pelo ânulo inguinal profundo medialmente aos vasos epigástricos.","C":"A hérnia inguinal direta é mais comumente encontrada em pacientes jovens, sendo incomum em\npacientes com idade avançada.","D":"A cirurgia para hérnia inguinal é classificada como cirurgia contaminada e haverá indicação de\nantibioticoprofilaxia.","E":"A técnica de Lichtenstein para reparo cirúrgico de hérnias inguinais é pouco utilizada pelo alto\níndice de recidiva herniário."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-84382","number":"84382","sourceNumber":"84382","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Com relação à HERNIA DE SPIEGEL, é INCORRETO afirmar que:","options":{"A":"Sua etiologia mais comum é adquirida, estando presente como causas: procedimentos\nlaparoscópicos, obesidade, DPOC, doença prostática,\ngestações múltiplas e perda acentuada de\npeso.","B":"A maioria tem diâmetros de 0,5 e 2 cm.","C":"É considerada uma hérnia intersticial.","D":"Os exames de imagem são importantes para demonstrar o defeito herniário e seu conteúdo, já\nque é difícil avaliação do anel herniário pelo exame clínico.","E":"Esse tipo de defeito da parede abdominal ocorre medialmente aos músculos retoabdominais."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-84662","number":"84662","sourceNumber":"84662","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Sobre a Pseudo-Obstrução Intestinal (POI) é correto afirmar:","options":{"A":"Quando ocorrem nos casos cirúrgicos, estes envolvem somente pós-operatórios de cirurgias\ndigestivas.","B":"O tempo de recuperação da contratilidade gástrica e colônica se equivalem no período\npós-operatório, cerca de 3-5 dias.","C":"Na pseudo-obstrução colônica aguda (Síndrome de Ogilvie) a complicação mais temida é o\nsangramento, que nesse caso é maciço.","D":"A eliminação de fezes e gases não deve afastar o diagnóstico de Síndrome de Ogilvie.","E":"Todas estão corretas."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-83662","number":"83662","sourceNumber":"83662","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"O reparo cirúrgico da hérnia inguinal pela técnica de colocação de uma malha\ninabsorvível protética que reforce a parede\nposterior do canal inguinal é o que caracteriza a técnica\nde:","options":{"A":"Bassini.","B":"Shouldice.","C":"McVay.","D":"Zimmermann.","E":"Lichtenstein."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-86380","number":"86380","sourceNumber":"86380","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Sobre as hérnias de parede abdominal, assinale a alternativa CORRETA:","options":{"A":"O diagnóstico diferencial de hérnia epigástrica deve ser feito com lipomas, hematomas, fibromas\ne neurofibromas.","B":"A hérnia incisional é de fácil diagnóstico ao exame ultrassonográfico, porém, nas hérnias\nvolumosas e complexas, cujo diâmetro do anel herniário ultrapassa o do transdutor, o melhor\nexame é a ressonância.","C":"A hérnia de Spiegel é ventral, adquirida através da linha arqueada de Douglas, abaixo da\ncicatriz\n\numbilical, e está localizada no ponto onde os vasos epigástricos inferiores atravessam a\nlâmina posterior da bainha do músculo reto abdominal.","D":"Todas anteriores corretas."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-86381","number":"86381","sourceNumber":"86381","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente portador de hérnia inguinal Nyhus tipo IIIA, assinalar a alternativa CORRETA.","options":{"A":"A técnica de correção mais adequada é Shouldice.","B":"A utilização de tela de polipropileno é obrigatória.","C":"O diagnóstico é realizado pela ultrassonografia.","D":"Nenhuma das anteriores."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-86360","number":"86360","sourceNumber":"86360","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Observando a anatomia vascular do cólon e do reto, qual dos itens é VERDADEIRO:","options":{"A":"A artéria mesentérica inferior localiza-se 5 cm acima do promontório sacral.","B":"A artéria ileocecocólica está ausente em 20% dos pacientes.","C":"A artéria mesentérica inferior nasce da aorta abdominal, 3 a 4 cm abaixo da terceira porção do\nduodeno.","D":"O ramo ascendente da artéria mesentérica inferior origina a artéria retal superior, que é o\nprincipal suprimento sanguíneo para o reto."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-63434","number":"63434","sourceNumber":"63434","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Sobre a dor inguinal crônica antes e após herniorrafia inguinal é INCORRETO afirmar:","options":{"A":"A dor neuropática é a mais importante não só pela prevalência, como pelo seu potencial\nincapacitante. Relaciona-se com a lesão dos nervos\nilioinguinal, ilio-hipogástrico e genitofemoral,\nalém do seu envolvimento no tecido cicatricial ou na formação de um neuroma.","B":"Deve-se evitar fixar pontos, clipes ou a tela na confluência do ligamento inguinal com o arco\npúbico (periósteo do púbis), tanto na\nhernioplastia convencional, como na laparoscópica evitando\nassim o aparecimento da dor somática.","C":"A inguinotomia exploradora está indicada nos pacientes que têm dor inguinal e ao exame clínico\nnão se percebe a presença de uma hérnia, assim deve-se procurar a causa da dor.","D":"Deve-se evitar a utilização de prótese nas hérnias indiretas pequenas, onde o simples\ntratamento do saco, associado ou não a um\nreforço pela técnica de McVay ou Bassini, a taxa de\nrecidiva não ultrapassa 2%.","E":"Na lesão do nervo ilioinguinal ou ilio-hipogástrico os sintomas usualmente envolvem a região\ninguinal com a irradiação para a porção interna e superior da coxa, para o escroto e lábio maior."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-61771","number":"61771","sourceNumber":"61771","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A classificação de NYHUS para um paciente que apresenta uma hérnia inguinal femoral\nrecidivada é:","options":{"A":"NYHUS IVc.","B":"NYHUS IVb.","C":"NYHUS IIIa.","D":"NYHUSIIIb.","E":"NYHUSIVa."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-61728","number":"61728","sourceNumber":"61728","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Limites do Triângulo de Hasselbach:","options":{"A":"Linha média, vasos epigástricos inferiores e ligamento inguinal.","B":"Margem lateral da bainha do m. reto abdominal, vasos epigástricos inferiores e ligamento\ninguinal.","C":"Margem lateral da bainha do m. reto abdominal,vasos epigástricos superiores e ligamento\ninguinal.","D":"Linha média, vasos epigástricos inferiores e ligamento pectíneo.","E":"M. reto abdominal, vasos epigástricos superiores e ligamento pectíneo"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-62688","number":"62688","sourceNumber":"62688","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"O reflexo celíaco é comum durante a realização de uma colonoscopia e deve ser\nconhecido e prontamente tratado por\nendoscopistas e anestesistas. A principal manifestação clínica\ne o correto tratamento desta situação urgente são, respectivamente:","options":{"A":"bradicardia e atropina.","B":"hipoxemia e oxigenioterapia.","C":"taquicardia e betabloqueador.","D":"liberação maciça de histamina e hidrocortisona."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-62695","number":"62695","sourceNumber":"62695","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Os objetivos no tratamento da doença de Crohn incluem cicatrização das lesões,\nindução da remissão e sua manutenção. A sequência que melhor caracteriza a abordagem\nterapêutica progressiva ou step-up na doença de Crohn é:","options":{"A":"Prednisona, azatioprina, adalimumabe, mesalazina e cirurgia.","B":"5-ASA, corticoides, imunossupressores, anti-TNFa e cirurgia.","C":"Colonoscopia, biópsia, mesalazina, azatioprina e cirurgia.","D":"Cirurgia, infliximabe, azatioprina, corticoides e 5-ASA."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-63264","number":"63264","sourceNumber":"63264","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Marcelo, 76 anos, é recebido no Serviço de Emergência referindo parada de eliminação\nde gases e fezes há quatro dias, seguida de\nvômitos e queda no estado geral. Ao exame,\napresenta PA: 120 x 70 mmHg; pulso: 110 bpm; TA: 36.8ºC; FR; 19 irpm; leucograma: 9.000\nleuc/mm³, sem desvio para a esquerda. Após medidas de suporte clínico, é submetido a estudo\nradiológico que revela acentuada distensão gasosa do cólon até o nível da fossa ilíaca esquerda e\nausência de distensão do intestino delgado. Realiza-se um clister opaco em que se observa \"sinal\ndo bico do pássaro\". A conduta a ser seguida, no caso, é:","options":{"A":"descompressão nasogástrica e medidas de suporte clínico.","B":"descompressão endoscópica do intestino grosso.","C":"descompressão videolaparoscópica do intestino grosso.","D":"laparotomia exploradora.","E":"colostomia transversa à direita."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-69208","number":"69208","sourceNumber":"69208","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A hérnia inguinal é patologia comum no ambulatório de cirurgia geral sendo de\ntratamento cirúrgico onde podemos empregar\ntécnicas ditas sob tensão e sem tensão. Dentre as\ntécnicas sem tensão podemos citar:","options":{"A":"Hernioplastia à Nyhus.","B":"Hernioplastia à Bassini.","C":"Hernioplastia à McVay.","D":"Hernioplastia à Shouldice.","E":"Hernioplastia à Stoppa."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-47703","number":"47703","sourceNumber":"47703","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Um paciente com história de obstipação intestinal de longa data, com piora progressiva\ndos sintomas nos últimos meses e exame de\nsorologia de Guerreiro-Machado positiva, deu entrada\nno serviço de emergência com quadro de dor e distensão abdominal volumosa, e parada de\neliminação de fezes há cerca de 12 horas. Nega vômitos ou febre. A conduta para o caso é:","options":{"A":"Tomografia de abdome total com contraste baritado, via retal, para adequada visualização do\ncólon;","B":"Radiografia simples de abdome (ortostático e deitado) e de tórax, além de exames bioquímicos;","C":"Tratamento cirúrgico de emergência, com realização de colectomia total, pelo risco de\nperfuração do sigmoide;","D":"Lavagem retal retrógrada com solução salina morna, seguida de laparoscopia diagnóstica."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-47325","number":"47325","sourceNumber":"47325","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Em relação à Colite Fulminante (CF) e ao Megacólon Tóxico (MT), complicações graves\nda doença intestinal inflamatória, assinale a\nalternativa incorreta:","options":{"A":"colonoscopia e enema opaco são contraindicados, no entanto, uma retossigmoidoscopia flexível\ncom pouca insuflação de ar poderá ser utilizada","B":"quando a CF não responde ao tratamento clínico, é possível usar ciclosporina venosa ou o\ninfliximabe anti-FNT (Fatos de Necrose Tumoral)","C":"o tratamento inicial de ambas consiste em: repouso alimentar, drenagem gástrica, hidratação\nvigorosa, antibióticos venosos, corticoterapia, associado a sintomáticos, como: antidiarreicos,\nopiáceos para dor e anticolinérgicos","D":"ambos necessitam de tratamento cirúrgico, quando o clínico falha e a colectomia total com\nileostomia terminal é a cirurgia de escolha","E":"o raio-x simples de abdome tem pouco valor no diagnóstico da CF (serve mais para excluir\noutras patologias), sendo importante para o diagnóstico do MT"},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-47329","number":"47329","sourceNumber":"47329","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A colite isquêmica:","options":{"A":"pode ser excluída, se a arteriografia demonstrar a artéria mesentérica superior e inferior\npatentes\ne normais","B":"geralmente acomete todo cólon e reto","C":"que ocorre após aneurismectomia da aorta, localiza-se geralmente na área de SUDECK\n(sigmoide)","D":"não deve ser avaliada por colonoscopia devido ao risco que esta acarreta","E":"deve ser sempre tratada cirurgicamente, uma vez diagnosticada com certeza, já que sua história\nnatural é a evolução para necrose e perfuração"},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-47334","number":"47334","sourceNumber":"47334","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"A hérnia incisional da parede anterior do abdome:","options":{"A":"decorre, obrigatoriamente, de uma falha na integridade da camada aponeurótica","B":"tem sempre indicação cirúrgica","C":"pouco se beneficia do uso de tela na sua correção","D":"ocorre mais no abdome superior do que no inferior","E":"ocorre mais nas incisões transversais do que nas medianas"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-53560","number":"53560","sourceNumber":"53560","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Na cirurgia por vídeolaparoscopia da hérnia inguinal, são utilizados o reparo\n\npré-peritoneal por viatransabominal (TAPP) e o reparo totalmenteextraperitoneal (TEP). Assinale a\nalternativa CORRETA.","options":{"A":"No TEP não se emprega o CO2.","B":"Ao contário da TAPP, o TEP não utiliza prótese (tela).","C":"Em geral, o TEP tem uma curva de aprendizado menor.","D":"O TAPP é preferido na presença de hérnia encarcerada.","E":"todas as alternativas acima estão corretas."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-48867","number":"48867","sourceNumber":"48867","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Escolar de nove anos apresenta quadro de emagrecimento e dor abdominal há oito\nmeses. A mãe refere episódios ocasionais de diarreia neste período. Exame físico: emagrecido;\nhipocorado ++/4; abdome globoso, hipertimpânico e difusamente doloroso à palpação profunda;\npresença de abscesso perianal. A principal hipótese diagnóstica é:","options":{"A":"Doença de Hirschsprung.","B":"Doença de Crohn.","C":"Doença celíaca.","D":"Fibrose cística.","E":"Maus tratos."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-48509","number":"48509","sourceNumber":"48509","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Sobre Hérnias inguinais podemos afirmar:","options":{"A":"As estruturas anatômicas na região inguinal se dispõem de tal forma, que deixam uma área\npouco protegida que Fruchaud denominou de óstio\nmiopectineo, esta é recoberta e protegida tão\nsomente por uma fina camada de tecido fibroso denominado de Fáscia Transversal.","B":"O princípio clássico introduzido por Bassini no final do século passado, consiste em se corrigir\na\nhérnia inguinal através da reaproximação e sutura de estruturas músculo-aponeuróticas deiscentes\ne enfraquecidas, reconstituindo de maneira anatomofuncional a região inguinal.","C":"A introdução de próteses de polipropileno no tratamento das hérnias inguinais, em nosso meio,\nganhou maior popularidade nos últimos dez anos após as publicações de Lichtenstein e sua escola.","D":"A técnica de Shouldice, desenvolvida no hospital de mesmo nome no Canadá, é uma das\ntécnicas com menor índice de recidiva porém uma das mais complexas de se realizar já que\nutiliza-se da imbricação de quatro planos de estruturas músculo-aponeuróticas no reforço da\nparede posterior.","E":"Todas estão corretas."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-05-48477","number":"48477","sourceNumber":"48477","collectionBlock":"med:med-cirurgia-med-cir-05","collectionLabel":"MED · MED CIR 05","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 05","subtopic":"","stem":"Paciente com 30 dias de vida, tendo iniciado há uma semana vômitos com conteúdo\nalimentar, raramente com estrias sanguineas,\nestado geral regular, desidratada. Exame abdominal:\nnodulação em hipocôndrio direito. Raio x contrastado de esôfago-estômago-duodeno: \" sinal do\nbico do seio\" Qual o provável diagnóstico?","options":{"A":"Invaginação intestinal.","B":"Apendicite aguda.","C":"Enterocolite necrotizante.","D":"Atresia de vias biliares.","E":"Estenose hipertrófica do piloro."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 05/MED CIR 05.txt","sourceLabel":"MED · MED CIR 05","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 05","MED"],"answerSource":"explicit","commentDeferred":true}]};
